MultiLanguageSpellData['de'][400026] = {name = "[q2]Medaillon des blutroten Kämpfers", additional_info = "Wirken in 2 sek.\nReagenzien:\nErweckte Zorneskraft (2), Ruhige Tinte (3), Frostige Rune\nOptionale Reagenzien:\nGeringe glorreiche Einsicht (#92) , Löschsand (#249)\nVerkäufer:\nKorganar Qualmschmiede\nZone:\nValdrakken\nKosten:\n3\n\n[q2]Medaillon des blutroten Kämpfers\nWird beim Anlegen gebunden\nEinzigartig anlegbar: Medaillons des Gladiators (1)Schmuck\n+205 [Beweglichkeit oder Stärke oder Intelligenz][q2]Benutzen: Entfernt alle bewegungseinschränkenden und Kontrollverlusteffekte.\n70\n\n[q]Auszeichnung des Gladiators (0/2)\n[q0]Emblem des Gladiators\nMedaillon des Gladiators"}
MultiLanguageSpellData['de'][400027] = {name = "[q2]Inbrunstinsigne des blutroten Kämpfers", additional_info = "Wirken in 2 sek.\nReagenzien:\nErweckte Zorneskraft (2), Lodernde Tinte (3), Frostige Rune\nOptionale Reagenzien:\nGeringe glorreiche Einsicht (#92) , Löschsand (#249)\nVerkäufer:\nKorganar Qualmschmiede\nZone:\nValdrakken\nKosten:\n3\n\n[q2]Inbrunstinsigne des blutroten Kämpfers\nWird beim Anlegen gebunden\nEinzigartig anlegbarSchmuck\n[q2]Erhöht Eure Tempowertung um + 291.\n[q2]Anlegen: Eure Zauber und Fähigkeiten haben eine Chance, Euren Primärwert für 20 Sek. um 457 zu erhöhen.\n70\n\n[q]Auszeichnung des Gladiators (0/2)\n[q0]Emblem des Gladiators\nMedaillon des Gladiators"}
MultiLanguageSpellData['de'][400028] = {name = "[q2]Emblem des blutroten Kämpfers", additional_info = "Wirken in 2 sek.\nReagenzien:\nErweckte Zorneskraft (2), Blühende Tinte (3), Frostige Rune\nOptionale Reagenzien:\nGeringe glorreiche Einsicht (#92) , Löschsand (#249)\nVerkäufer:\nKorganar Qualmschmiede\nZone:\nValdrakken\nKosten:\n3\n\n[q2]Emblem des blutroten Kämpfers\nWird beim Anlegen gebunden\nEinzigartig anlegbarSchmuck\n+205 [Beweglichkeit oder Stärke oder Intelligenz][q2]Benutzen: Erhöht 15 Sek. lang die maximale Gesundheit um 26226 . (2 Min Abklingzeit)\n70\n\n[q]Auszeichnung des Gladiators (0/2)\n[q0]Emblem des Gladiators\nMedaillon des Gladiators"}
