MultiLanguageSpellData['de'][400805] = {name = "Überwältigen", additional_info = "Nahkampfreichweite\n{Sofort} {12 sek. Abklingzeit}\n1 Aufladung\nBenötigt Nahkampfwaffe\n[q]Überwältigt den Gegner und fügt ihm (116.82% der Angriffskraft) körperlichen Schaden zu. Der Angriff kann nicht geblockt oder pariert und ihm kann nicht ausgewichen werden. [ Kampfgeschick : Erhöht den Schaden Eures nächsten Einsatzes von 'Tödlicher Stoß' oder 'Spalten' um 30%. Bis zu 1-mal stapelbar ] [ Erhöht den Schaden Eures nächsten Einsatzes von 'Tödlicher Stoß' um 30%. Bis zu 1-mal stapelbar ] [ Verbessertes Überwältigen : Erzeugt [(292.132% der Angriffskraft) / 10] Wut. ]"}
MultiLanguageSpellData['de'][400806] = {name = "Starker Waffenarm", additional_info = "Sofort\n[q]'Überwältigen' verursacht zusätzlich 15% Schaden, hat eine 10% höhere kritische Trefferchance und verursacht 10% mehr kritischen Schaden."}
MultiLanguageSpellData['de'][400807] = {name = "[q4]Beutel funkelnder Gewürze", additional_info = "Wirken in 3.5 sek.\nReagenzien:\nLangweilige Gewürze\nVerkäufer:\nHändlerin Hag'arth\nZone:\nVerbotene Insel\nKosten:\n10\n\n[q4]Beutel funkelnder Gewürze\nHandwerkliche Kuriositäten\n[q]\"Die fehlende Zutat war Liebe! Das Aroma ist phänomenal. Ein wunderbarer Geschmack der Verbotenen Insel. Löst womöglich eine besondere Begegnung aus.\""}
MultiLanguageSpellData['de'][400808] = {name = "[q4]Uralter zeremonieller Dreizack", additional_info = "Wirken in 3.5 sek.\nReagenzien:\nBeschädigter Dreizack\nVerkäufer:\nHändlerin Hag'arth\nZone:\nVerbotene Insel\nKosten:\n10\n\n[q4]Uralter zeremonieller Dreizack\nHandwerkliche Kuriositäten\n[q]\"Dieser Dreizack ist nicht für den Kampf gemacht. Er scheint ritueller Natur zu sein. Passt auf, wo Ihr in auf der Verbotenen Insel ablegt. Löst womöglich eine besondere Begegnung aus.\""}
MultiLanguageSpellData['de'][400809] = {name = "[q4]Leuchtendes Kristalllesezeichen", additional_info = "Wirken in 3.5 sek.\nReagenzien:\nTrüber Kristall\nVerkäufer:\nHändlerin Hag'arth\nZone:\nVerbotene Insel\nKosten:\n10\n\n[q4]Leuchtendes Kristalllesezeichen\nHandwerkliche Kuriositäten\n[q]\"Dieses glitzernde Lesezeichen bettelt darum, in ein gutes Buch, wie eines der Verbotenen Insel, gelegt zu werden. Löst womöglich eine besondere Begegnung aus.\""}
MultiLanguageSpellData['de'][400810] = {name = "[q4]Gnomischer Sprachkasten", additional_info = "Wirken in 3.5 sek.\nReagenzien:\nDefekter gnomischer Sprachkasten\nVerkäufer:\nHändlerin Hag'arth\nZone:\nVerbotene Insel\nKosten:\n10\n\n[q4]Gnomischer Sprachkasten\nHandwerkliche Kuriositäten\n[q]\"Wie kommt Gnomentechnologie auf die Verbotene Insel? Ihr benötigt eine Brummsäule, um sie abzuspielen. Löst womöglich eine besondere Begegnung aus.\""}
MultiLanguageSpellData['de'][400811] = {name = "[q4]Arkane Bannrune", additional_info = "Wirken in 3.5 sek.\nReagenzien:\nHastig geschriebene Rune\nVerkäufer:\nHändlerin Hag'arth\nZone:\nVerbotene Insel\nKosten:\n10\n\n[q4]Arkane Bannrune\nHandwerkliche Kuriositäten\n[q]\"Nachdem die Linien ausgebessert wurden, ist Euch klar geworden, dass diese Rune Zauberschutze, wie die auf der Verbotenen Insel, bannen soll. Löst womöglich eine besondere Begegnung aus.\""}
MultiLanguageSpellData['de'][400812] = {name = "[q4]Kristallstimmgabel", additional_info = "Wirken in 3.5 sek.\nReagenzien:\nKristallgabel\nVerkäufer:\nHändlerin Hag'arth\nZone:\nVerbotene Insel\nKosten:\n10\n\n[q4]Kristallstimmgabel\nHandwerkliche Kuriositäten\n[q]\"An den richtigen Kristall auf der Verbotenen Insel geschlagen, könnte ein melodischer Klang entstehen. Löst womöglich eine besondere Begegnung aus.\""}
MultiLanguageSpellData['de'][400813] = {name = "Zeitreibung", additional_info = "[q]Nutzt die Hitze der chaotischen Zeitlinien während des Ereignisses \"Der Zorn des Sturms\" in der Zukunft der Primalisten, um alle 11 Sek. einen Stapel von ' Eiskalt ' zu entfernen."}
MultiLanguageSpellData['de'][400814] = {name = "[q4]Verstärktes makelloses Leder", additional_info = "Wirken in 3.5 sek.\nReagenzien:\nMakelloser Pelz\nVerkäufer:\nHändlerin Hag'arth\nZone:\nVerbotene Insel\nKosten:\n10\n\n[q4]Verstärktes makelloses Leder\nHandwerkliche Kuriositäten\n[q]\"Diese Flicken aus verstärktem Leder werden von den Tuskarr von Morqut oft verwendet, um beschädigte Bälge der Verbotenen Insel zu reparieren. Löst womöglich eine besondere Begegnung aus.\""}
MultiLanguageSpellData['de'][400815] = {name = "[q4]Traditioneller Morqutdrachen", additional_info = "Wirken in 3.5 sek.\nReagenzien:\nZerrissener Morqutdrachen\nVerkäufer:\nHändlerin Hag'arth\nZone:\nVerbotene Insel\nKosten:\n10\n\n[q4]Traditioneller Morqutdrachen\nHandwerkliche Kuriositäten\n[q]\"Manche sagen, dass an Pfosten geknüpfte Tuskarrdrachen auf der Verbotenen Insel auf den Schwingen des Geistes fliegen. Löst womöglich eine besondere Begegnung aus.\""}
