MultiLanguageSpellData['de'][401124] = {name = "Eifernde Hinrichtung", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Neltharion verderbt den Glauben des Paladins, was ihn 30 Sek. lang dazu zwingt, alle 6 Sek. einen Hammer aus dem Licht zu rufen. Der Hammer weiht den Boden und fügt allen Zielen im Effektbereich 10 Heiligschaden zu. Zusätzlich erleiden sie 50 Heiligschaden, wenn der Hammer nach 5 Sek. landet."}
MultiLanguageSpellData['de'][401125] = {name = "Verderbte Tiere", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Neltharion zwingt den Jäger, verderbte Begleiter herbeizurufen und angreifen zu lassen.\n\n Nach Erlegen eines verderbten Begleiters wird der Jäger durch ' Entfesselte Dunkelheit ' ermächtigt."}
MultiLanguageSpellData['de'][401126] = {name = "Wilder Verrat", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Neltharion verderbt die natürliche Hinterhältigkeit des Schurken und zwingt ihn, alle 10 Sekunden durch die Schatten zu einem Verbündeten zu treten und dann Dolche auf alle Ziele innerhalb von 10 Metern zu werfen, die 20 körperlichen Schaden verursachen. Belegt alle Ziele zusätzlich mit ' Wildes Gift '."}
MultiLanguageSpellData['de'][401127] = {name = "Verzweifelter Schrei", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Neltharions Verderbnis untergräbt den Glauben des Priesters, sodass 30 Sek. lang alle 6 Sek. ein ' Verzweifelter Schrei ' aus ihm hervorbricht, der Spielercharakteren und Kreaturen innerhalb von 8 Metern alle 1 Sek. 7 Schattenschaden zufügt und sie für 6 Sek. vor Furcht davonlaufen lässt.\n\n Der Priester erhält für jedes getroffene Ziel eine Anwendung von ' Schattenwort: Niedertracht ', bis zu einem Maximum von 5."}
MultiLanguageSpellData['de'][401128] = {name = "Wilder Griff", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Neltharion übernimmt die Macht des Untodes des Todesritters und zwingt ihn 30 Sek. lang, alle 10 Sek. Bereiche von ' Wilde Pestilenz ' zu erschaffen und Verbündete mit 'Todesgriff' zu sich heranzuziehen."}
MultiLanguageSpellData['de'][401129] = {name = "Totem des Schattenelementars", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Neltharion zwingt den Schamanen, Totems zu beschwören, um Schattenelementare zu binden, die danach angreifen.\n\n Nach dem Sieg über einen Elementar wird der Schamane durch ' Entfesselte Dunkelheit ' ermächtigt."}
MultiLanguageSpellData['de'][401130] = {name = "Wilde Magie", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Neltharion verdirbt den Fluss der arkanen Energien im Magier, wodurch 30 Sek. lang alle 10 Sek. ' Wilde Magie ' aus ihm hervorbricht, was Spielercharakteren und Kreaturen innerhalb von 10 Metern 4 Sek. lang alle 0.5 Sek. 20 Arkanschaden zufügt."}
MultiLanguageSpellData['de'][401131] = {name = "Wilde Beschwörung", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Neltharion zwingt den Hexenmeister, Halluzinationen ausgehungerter Leerenbestien zu beschwören, die den Hexenmeister 25 Sek. lang angreifen.\n\n Jedes Mal, wenn der Hexenmeister eine dieser Bestien tötet, wird er durch ' Entfesselte Dunkelheit ' ermächtigt."}
MultiLanguageSpellData['de'][401132] = {name = "Geister, Wasser und Verfall", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Neltharion verderbt die Essenz des Mönchs, wodurch Geister sich von ihm abspalten und ihn 30 Sek. lang angreifen.\n\n Wenn der Mönch einen dieser Geister besiegt, wird er durch ' Entfesselte Dunkelheit ' ermächtigt."}
MultiLanguageSpellData['de'][401133] = {name = "Wilde Verwandlung", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Neltharion nutzt die Verbindung des Druiden zur Natur aus und zwingt ihn 30 Sek. lang, sich alle 10 Sek. in eine zufällige Gestalt zu verwandeln. Die wilde Gewalt der Verwandlung lässt den Druiden ' Wildes Hauen ' einsetzen und gewährt ihm ' Eifer des Gestaltwandlers '."}
MultiLanguageSpellData['de'][401134] = {name = "Chaostanz", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Neltharion zwingt den Dämonenjäger 30 Sek. lang, alle 6 Sek. in einen chaotischen Klingentanz auszubrechen, der allen Kreaturen und Spielercharakteren innerhalb von 8 Metern mehrfach 20 Chaosschaden zufügt."}
MultiLanguageSpellData['de'][401135] = {name = "Wilder Atem", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Neltharion übernimmt die Kontrolle über den Rufer und zwingt ihn 30 Sek. lang, alle 6 Sek. ' Wilder Atem ' zu wirken, was allen Spielercharakteren 10 Feuerschaden zufügt, während sie über das Schlachtfeld fliegen."}
