MultiLanguageSpellData['de'][402784] = {name = "Äonenerschütterung", additional_info = "Unbegrenzte Reichweite\nWirken in 3 sek.\n[q]Chronikar wirft ihre Waffe auf die Siechende Sandlache , die ihr am nächsten ist, um dieser die Macht zu entziehen und ihr eigenes Angriffstempo 8 Sek. lang um 50% zu erhöhen.\n\n Fügt allen Spielercharakteren innerhalb von 18 Metern um den Einschlag 50 Arkanschaden zu.\n\n Die Explosion zerschmettert die Lache in Äonenfragmente und lässt Äonenrückstände herabregnen."}
MultiLanguageSpellData['de'][402787] = {name = "Explosive Schläge", additional_info = "Sofort\n[q]Die automatischen Angriffe des Zaubernden fügen Gegnern innerhalb von 5 Metern um den Einschlagsort 25 Feuerschaden zu.\n(5s Abklingzeit)"}
MultiLanguageSpellData['de'][402793] = {name = "Feuerschlag", additional_info = "Unbegrenzte Reichweite\nWirken in 3 sek.\n[q]Gholna schlägt auf ihr aktuelles Ziel ein, fügt Spielercharakteren innerhalb eines kegelförmigen Bereichs vor sich 65 Vulkanschaden zu und stößt sie zurück.\n\n Belegt von diesem Effekt getroffene Spielercharaktere außerdem mit ' Brennende Berührung '."}
MultiLanguageSpellData['de'][402795] = {name = "Feuerschlag", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Gholna schlägt auf ihr aktuelles Ziel ein, fügt Spielercharakteren innerhalb eines kegelförmigen Bereichs vor sich 129026 Vulkanschaden zu und stößt sie zurück.\n\n Belegt von diesem Effekt getroffene Spielercharaktere außerdem mit ' Brennende Berührung '."}
