MultiLanguageSpellData['de'][402798] = {name = "Kristallisieren", additional_info = "Sofort\n[q]Die automatischen Angriffe des Zaubernden belegen das Ziel mit 'Kristallisieren'. 'Kristallisieren' verursacht alle 2 Sek. 5 Arkanschaden und verringert den erlittenen körperlichen Schaden um 5% sowie die Bewegungsgeschwindigkeit um 10%. Hält 10 Sek. lang an. Dieser Effekt ist stapelbar.\n\n Der Effekt wird durch ' Zertrümmernder Stachel ' entfernt."}
