MultiLanguageSpellData['de'][405113] = {name = "Strahlstrom", additional_info = "Wirken in 3 sek.\n[q]Der Zaubernde kanalisiert Hochdruckwellen vor und hinter sich, was Gegnern 12 Frostschaden zufügt und sie zurückstößt.\n\n Während der Kanalisierung rotieren die Wellen um den Zaubernden herum."}
MultiLanguageSpellData['de'][405115] = {name = "Krustenverhexung", additional_info = nil}
MultiLanguageSpellData['de'][405116] = {name = "Kauterisierende Heilung", additional_info = "40 Meter Reichweite\nSofort\n[q]Gewährt einem Verbündeten einen Schild in Höhe von 3320 und kanalisiert gleichzeitig einen Strahl aus geschmolzenen Flammen, der dem Verbündeten im Verlauf von 2.5 Sek. ( 78 * 5) Feuerschaden zufügt. Wenn der Verbündete die Kanalisierung überlebt, wird er um 8301 Gesundheit geheilt."}
MultiLanguageSpellData['de'][405117] = {name = "Frostblinzeln", additional_info = "500 Meter Reichweite\nWirken in 2 sek.\n[q]Lady Shaz'ra überträgt ihre Essenz durch die Essenz des Frosts selbst an einen neuen Ort."}
MultiLanguageSpellData['de'][405118] = {name = "Kondensierender Dampfstein", additional_info = "30 Meter Reichweite\nSofort\n[q]Beim Erhalten von Heilung besteht eine Chance, Dampf freizusetzen, der bei Euch sowie 2 Verbündeten in der Nähe 623 Gesundheit wiederherstellt."}
MultiLanguageSpellData['de'][405120] = {name = "Metamorphes Serevitvorkommen", additional_info = "5 Meter Reichweite\nWirken in 3.2 sek.\n[q]Serevit ist das am häufigsten zu findende Erz auf den Dracheninseln. Obwohl es oft in Gebirgsregionen vorkommt, wird es auch durch fließendes Wasser freigelegt.\n\n Erzablagerungen in einem aktiven metamorphen Zustand können nur in der Zaralekhöhle gefunden werden.\n\n Gewährt beim Abbauen den folgenden Effekt:\n\n Zaralekleuchtstaub :\nBedeckt Euch mit leuchtendem Staub, der perfekt geeignet ist, um die Fortpflanzung von Sporen zu unterstützen. Hält 2 Min. lang an."}
MultiLanguageSpellData['de'][405121] = {name = "Metamorphes Drakoniumvorkommen", additional_info = "5 Meter Reichweite\nWirken in 3.2 sek.\n[q]Drakoniumvorkommen sind ein seltener Fund auf den Dracheninseln, aber sie wurden öfter in rauen oder schwer zu erreichenden Umgebungen gesichtet.\n\n Erzablagerungen in einem aktiven metamorphen Zustand können nur in der Zaralekhöhle gefunden werden.\n\n Gewährt beim Abbauen den folgenden Effekt:\n\n Zaralekleuchtstaub :\nBedeckt Euch mit leuchtendem Staub, der perfekt geeignet ist, um die Fortpflanzung von Sporen zu unterstützen. Hält 2 Min. lang an."}
MultiLanguageSpellData['de'][405122] = {name = "Krustenverhexung", additional_info = nil}
MultiLanguageSpellData['de'][405123] = {name = "Flackernde Hochblume", additional_info = "5 Meter Reichweite\nWirken in 2.5 sek.\n[q]Hochblume ist das häufigste Kraut der Dracheninseln. Es kann so gut wie in jedem Gelände gefunden werden und wächst, wo immer es möglich ist.\n\n Flackernde Kräuter können nur in der Zaralekhöhle gefunden werden.\n\n Gewährt beim Sammeln den folgenden Effekt:\n\n Zaralekleuchtklette :\nBedeckt Euch mit Leuchtsporen, die sich dringend fortpflanzen wollen. Hält 2 Min. lang an."}
MultiLanguageSpellData['de'][405124] = {name = "Flackernder Blasenmohn", additional_info = "5 Meter Reichweite\nWirken in 2.5 sek.\n[q]Blasenmohn ist ein empfindliches Kraut, das an feuchten Orten auf den Dracheninseln wächst. Es wächst entlang der Flüsse, Küsten und in feuchten Höhlen.\n\n Die Blasenmohnblume mag einzigartig aussehen, ist aber nicht zu viel zu gebrauchen. Die wässrige Pilzkugel, die sich am Stiel bildet, ist der wertvolle Teil.\n\n Flackernde Kräuter können nur in der Zaralekhöhle gefunden werden.\n\n Gewährt beim Sammeln den folgenden Effekt:\n\n Zaralekleuchtklette :\nBedeckt Euch mit Leuchtsporen, die sich dringend fortpflanzen wollen. Hält 2 Min. lang an."}
MultiLanguageSpellData['de'][405125] = {name = "Strahlstrom", additional_info = "100 Meter Reichweite\nSofort\n[q]Der Zaubernde kanalisiert Hochdruckwellen vor und hinter sich, was Gegnern 12 Frostschaden zufügt und sie zurückstößt.\n\n Während der Kanalisierung rotieren die Wellen um den Zaubernden herum."}
MultiLanguageSpellData['de'][405126] = {name = "Flackerndes Steinbrich", additional_info = "5 Meter Reichweite\nWirken in 2.5 sek.\n[q]Steinbrich ist ein widerstandsfähiges Kraut, das an zahlreichen Orten gedeihen kann. Obwohl es allgemein an felsigen Standorten wie Gebirgen oder Klippen auffindbar ist, wächst es auch auf weiten Ebenen oder vereinzelt in vulkanischen Gebieten.\n\n Flackernde Kräuter können nur in der Zaralekhöhle gefunden werden.\n\n Gewährt beim Sammeln den folgenden Effekt:\n\n Zaralekleuchtklette :\nBedeckt Euch mit Leuchtsporen, die sich dringend fortpflanzen wollen. Hält 2 Min. lang an."}
MultiLanguageSpellData['de'][405127] = {name = "Flackernde Krümmrinde", additional_info = "5 Meter Reichweite\nWirken in 2.5 sek.\n[q]Krümmrinde ist ein grünliches Kraut, das auf den Dracheninseln gefunden werden kann. Es wächst dort, wo es reichlich Bäume oder Grünpflanzen gibt.\n\n Flackernde Kräuter können nur in der Zaralekhöhle gefunden werden.\n\n Gewährt beim Sammeln den folgenden Effekt:\n\n Zaralekleuchtklette :\nBedeckt Euch mit Leuchtsporen, die sich dringend fortpflanzen wollen. Hält 2 Min. lang an."}
