MultiLanguageSpellData['de'][405500] = {name = "Death Knight Blood 10.1 Class Set 4pc", additional_info = "[q]Wenn Ihr 'Vampirblut' erhalten würdet, werdet Ihr stattdessen mit 'Vampirstärke' erfüllt, was Euch 5 Sek. lang 0.5 Stärke gewährt. Eure Fähigkeiten 'Herzstoß' und 'Siedendes Blut' verlängern die Dauer von 'Vampirstärke' um 10% Sek."}
MultiLanguageSpellData['de'][405501] = {name = "Death Knight Frost 10.1 Class Set 2pc", additional_info = "[q]Der Schaden von 'Heulende Böe' ist um 20% erhöht. Das Verbrauchen von 'Raureif' erhöht den Schaden Eures nächsten Einsatzes von 'Furor des Frostwyrms' um 5%, bis zu 10-mal stapelbar. 'Säule des Frosts' löst 'Furor des Frostwyrms' mit 30% Effektivität aus, wobei der Effekt Gegner nicht einfrieren kann."}
MultiLanguageSpellData['de'][405502] = {name = "Death Knight Frost 10.1 Class Set 4pc", additional_info = "[q]'Furor des Frostwyrms' lässt getroffene Gegner 12 Sek. lang um 20% erhöhten Schaden durch Eure kritischen Treffer erleiden."}
MultiLanguageSpellData['de'][405503] = {name = "Death Knight Unholy 10.1 Class Set 2pc", additional_info = "[q]Der Schaden von 'Todesmantel' und 'Epidemie' ist um 10% erhöht. Der Einsatz von 'Todesmantel' oder 'Epidemie' gewährt einen Stapel von 'Meister des Todes', bis zu 20 Stapel. 'Dunkle Transformation' verbraucht 'Meister des Todes' und gewährt Euch 25 Sek. lang pro Stapel 1% Meisterschaft."}
MultiLanguageSpellData['de'][405504] = {name = "Death Knight Unholy 10.1 Class Set 4pc", additional_info = "[q][ Monstrosität erwecken : 'Monstrosität erwecken' / 'Armee der Toten'] gewährt 20 Stapel von 'Meister des Todes'. Wenn 'Hereinbrechende Verdammnis' durch 'Todesmantel' oder 'Epidemie' verbraucht wird, erhaltet Ihr zusätzlich 1 Stapel von 'Meister des Todes' und 6 Sek. lang 10% Meisterschaft."}
