MultiLanguageSpellData['de'][405508] = {name = "Demon Hunter Vengeance 10.1 Class Set 2pc", additional_info = "[q]Seelenfragmente heilen 10% mehr und das Erzeugen eines Seelenfragments erhöht Euren Feuerschaden 6 Sek. lang um 2%. Mehrere Einsätze können sich überlappen."}
