MultiLanguageSpellData['de'][405510] = {name = "Druid Balance 10.1 Class Set 2pc", additional_info = "[q]Der Radius von 'Sonnenfeuer' ist um 3 Meter erhöht. Der Schaden von 'Sonnenfeuer', 'Mondfeuer' und 'Sternschnuppen' ist um 20% erhöht."}
