MultiLanguageSpellData['de'][405512] = {name = "Druid Feral 10.1 Class Set 2pc", additional_info = "[q]Eure automatischen Angriffe haben eine Chance von 25%, 'Schatten des Raubtiers' zu gewähren, was Eure Beweglichkeit um 1.0% erhöht. Jede Anwendung über 5 hinaus hat eine ansteigende Chance, den Effekt auf 2 Stapel zurückzusetzen.\n(Procchance: 25%, 100ms Abklingzeit)"}
MultiLanguageSpellData['de'][405513] = {name = "Druid Feral 10.1 Class Set 4pc", additional_info = "[q]Wenn eine Anwendung von 'Schatten des Raubtiers' die Stapel zurücksetzt, wird Eure Beweglichkeit um 8% erhöht und Ihr erzeugt alle 2 Sek. 1 Combopunkte. Hält 8 Sek. lang an."}
MultiLanguageSpellData['de'][405514] = {name = "Druid Guardian 10.1 Class Set 2pc", additional_info = "[q]Wenn Ihr Schaden erleidet, wird der Schaden von 'Zerfleischen' und 'Hauen' sowie die Wuterzeugung 8 Sek. lang um 15% erhöht und Ihr werdet im Verlauf von 8 Sek. um 6% des erlittenen Schadens geheilt."}
MultiLanguageSpellData['de'][405515] = {name = "Druid Guardian 10.1 Class Set 4pc", additional_info = "[q]Der Schaden von [ Plätten : 'Plätten' / 'Zermalmen'] ist um 20% erhöht und der Einsatz von 'Eisenfell' oder [ Plätten : 'Plätten' / 'Zermalmen'] erhöht Eure maximale Gesundheit für 12 Sek. um 3%. 5-mal stapelbar."}
MultiLanguageSpellData['de'][405516] = {name = "Druid Restoration 10.1 Class Set 2pc", additional_info = "[q]Die Heilung von 'Verjüngung' und 'Blühendes Leben' ist um 10% erhöht. Die regelmäßige Heilung von 'Nachwachsen' ist um 35% erhöht."}
MultiLanguageSpellData['de'][405517] = {name = "Druid Restoration 10.1 Class Set 4pc", additional_info = "[q]'Gedeihen' erhöht für zusätzlich 16 Sek. nach seinem Ablauf die Rate Eurer regelmäßigen Heileffekte um 26%. 'Üppige Infusion' bewirkt, dass Eure Heilung bei Eurem Ziel von 'Rasche Heilung' 6 Sek. lang um 15% erhöht wird."}
MultiLanguageSpellData['de'][405518] = {name = "Evoker Devastation 10.1 Class Set 2pc", additional_info = "[q]'Desintegration' und 'Scheiterhaufen' durchbohren Gegner mit Obsidiansplittern, die 18% des Schadens als Vulkanschaden über 8 Sek. verursachen."}
MultiLanguageSpellData['de'][405519] = {name = "Evoker Devastation 10.1 Class Set 4pc", additional_info = "[q]Ermächtigungszauber verursachen 12% mehr Schaden und lassen Eure Obsidiansplitter mit Macht lodern, wodurch diese 5 Sek. lang 200% mehr Schaden verursachen. Während 'Drachenwut' lodern Eure Splitter immer mit Macht."}
MultiLanguageSpellData['de'][405520] = {name = "Evoker Preservation 10.1 Class Set 2pc", additional_info = "[q]'Geisterblüte' wendet einen regelmäßigen Heileffekt von 40% der hervorgerufenen Heilung über 8 Sek. an. 'Traumatem' ruft 15% mehr Heilung hervor."}
MultiLanguageSpellData['de'][405521] = {name = "Herdtotem von Morqut", additional_info = "Wirken in 5 sek.\n[q]Teleportiert den Zaubernden zum Morqutdorf. Kann nur auf der Verbotenen Insel aktiviert werden."}
MultiLanguageSpellData['de'][405522] = {name = "Evoker Preservation 10.1 Class Set 4pc", additional_info = "[q]Nachdem Ihr 4 Ermächtigungszauber gewirkt habt, erhaltet Ihr eine 'Essenzexplosion' sofort und eine weitere 3 Sek. später."}
