MultiLanguageSpellData['de'][405525] = {name = "Hunter Beast Mastery 10.1 Class Set 4pc", additional_info = "[q]'Kobraschuss', 'Tötungsbefehl' und 'Mehrfachschuss' verringern die Abklingzeit von 'Zorn des Wildtiers' um 2.0 Sek."}
MultiLanguageSpellData['de'][405526] = {name = "Hunter Marksmanship 10.1 Class Set 2pc", additional_info = "[q][ Schimärenschuss : 'Schimärenschuss' / 'Arkaner Schuss'] und 'Mehrfachschuss' verursachen 10% mehr Schaden und haben eine Chance von 8%, den Effekt von 'Todesstoß' zu gewähren.\n(Procchance: 8%)"}
MultiLanguageSpellData['de'][405527] = {name = "Hunter Marksmanship 10.1 Class Set 4pc", additional_info = "[q]'Tödlicher Schuss' verursacht 15% mehr Schaden und verringert die Abklingzeit von 'Gezielter Schuss' und 'Schnellfeuer' um 1.5 Sek."}
MultiLanguageSpellData['de'][405528] = {name = "Hunter Survival 10.1 Class Set 2pc", additional_info = "[q]'Lauffeuerbombe' verursacht 10% mehr Schaden und erhöht den Schaden Eures nächsten Einsatzes von 'Tötungsbefehl' um 40%."}
MultiLanguageSpellData['de'][405529] = {name = "Gregg wählen", additional_info = nil}
MultiLanguageSpellData['de'][405530] = {name = "Hunter Survival 10.1 Class Set 4pc", additional_info = "[q]Verringert die Abklingzeit von ' Lauffeuerbombe' pro 30 verbrauchtem Fokus um 1.0 Sek."}
MultiLanguageSpellData['de'][405531] = {name = "Explosion", additional_info = "40 Meter Reichweite\nWirken in 1.5 sek.\n[q]Überzieht das Ziel mit Feuerschaden."}
MultiLanguageSpellData['de'][405532] = {name = "Mage Arcane 10.1 Class Set 2pc", additional_info = "[q]'Arkane Woge' erhöht den Zauberschaden um zusätzlich 10% und der Effekt hält 3 Sek. länger an."}
MultiLanguageSpellData['de'][405533] = {name = "Mage Arcane 10.1 Class Set 4pc", additional_info = "[q]Pro 420000 Mana, das Ihr für und während 'Arkane Woge' verbraucht, wird Euer Zauberschaden für 18 Sek. nach dem Ablauf von 'Arkane Woge' um 1.0% erhöht. Bis zu 25-mal stapelbar. Die Manaregeneration ist währenddessen um 50% erhöht."}
MultiLanguageSpellData['de'][405534] = {name = "Mage Fire 10.1 Class Set 2pc", additional_info = "[q]'Phönixflammen' belegt alle Gegner, die durch den Zauber Schaden erleiden, mit 'Verkohlende Glut', was ihren durch Euch erlittenen Schaden 14 Sek. lang um 6% erhöht."}
MultiLanguageSpellData['de'][405535] = {name = "Mage Fire 10.1 Class Set 4pc", additional_info = "[q]Wenn Eure direkten Schadenszauber 25-mal einen Gegner treffen, der mit 'Verkohlende Glut' belegt ist, verursachen Eure nächsten 2 'Phönixflammen' 100% mehr Schaden und erstatten eine Aufladung."}
MultiLanguageSpellData['de'][405536] = {name = "Mage Frost 10.1 Class Set 2pc", additional_info = "[q]Der Schaden von 'Hagel' und 'Eislanze' ist um 20% erhöht. Euer Zauber 'Hagel' löst beim Einschlag eine Explosion aus, die Gegnern in der Nähe 35% seines Schadens zufügt. Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu."}
MultiLanguageSpellData['de'][405538] = {name = "Mage Frost 10.1 Class Set 4pc", additional_info = "[q]Wenn Ihr 'Eislanze' gegen ein eingefrorenes Ziel einsetzt, besteht eine Chance von 10%, 'Hirnfrost' auszulösen."}
MultiLanguageSpellData['de'][405539] = {name = "Monk Brewmaster 10.1 Class Set 2pc", additional_info = "[q]Der Schaden von 'Blackout-Tritt' ist um 20% erhöht. Ihr habt eine Chance von 10%, Eure Stapel von 'Flüchtiger Kämpfer' bei erfolgreichem Ausweichen nicht zurückzusetzen."}
MultiLanguageSpellData['de'][405540] = {name = "Monk Brewmaster 10.1 Class Set 4pc", additional_info = "[q]'Tritt der aufgehenden Sonne' gewährt einen Stapel von 'Flüchtiger Kämpfer'. Wenn Ihr ausweicht, werden der Schaden und die kritische Trefferchance Eures nächsten Einsatzes von 'Wirbelnder Kranichtritt' oder 'Tritt der aufgehenden Sonne' um 5% erhöht. Bis zu 5-mal stapelbar."}
MultiLanguageSpellData['de'][405541] = {name = "Monk Mistweaver 10.1 Class Set 2pc", additional_info = "[q]Heilung von 'Erneuernder Nebel', 'Beruhigender Nebel' und 'Einhüllender Nebel' um 12 erhöht."}
MultiLanguageSpellData['de'][405542] = {name = "Monk Mistweaver 10.1 Class Set 4pc", additional_info = "[q]Das Trinken von Tee erhöht die Heilung von 'Beleben' und 'Erneuernder Nebel' 6 Sek. lang um 40%."}
MultiLanguageSpellData['de'][405543] = {name = "Monk Windwalker 10.1 Class Set 2pc", additional_info = "[q]'Tritt der aufgehenden Sonne' verursacht 5% mehr Schaden und erzeugt eine Nova, die allen Gegnern innerhalb von 8 Metern (83% der Angriffskraft) Schattenflammenschaden zufügt."}
MultiLanguageSpellData['de'][405544] = {name = "Monk Windwalker 10.1 Class Set 4pc", additional_info = "Ca. 2 Procs pro Minute\n[q]Eure automatischen Nahkampfangriffe haben eine Chance, einen Schattenflammengeist auf Euren Gegner zu hetzen, der 7.5 Sek. lang Eure Fähigkeiten bei 20% Effektivität kopiert."}
MultiLanguageSpellData['de'][405545] = {name = "Paladin Holy 10.1 Class Set 2pc", additional_info = "[q]Kritische Treffer durch 'Heiliger Schock' heilen 80% mehr Gesundheit und verringern die Abklingzeit von 'Hammer des Lichts' um 2 Sek. oder 'Heiliges Prisma' um 1.0 Sek."}
MultiLanguageSpellData['de'][405546] = {name = "Paladin Holy 10.1 Class Set 4pc", additional_info = "[q]'Hammer des Lichts' heilt 100% häufiger und erzeugt alle 4 Sek. 1 Heilige Kraft. Die Heilung von 'Heiliges Prisma' ist um 40% erhöht und die Fähigkeit erzeugt 1 Heilige Kraft beim Einsatz auf ein gegnerisches Ziel oder 3 beim Einsatz auf einen Verbündeten."}
MultiLanguageSpellData['de'][405547] = {name = "Paladin Protection 10.1 Class Set 2pc", additional_info = "[q]'Schild des Rächers' lässt getroffene Ziele mit 'Herzensfeuer' brennen, was zusätzlich 20% des verursachen Schadens im Verlauf von 5 Sek. verursacht. 'Herzensfeuer' heilt Euch um 100% seines verursachten Schadens."}
MultiLanguageSpellData['de'][405548] = {name = "Paladin Protection 10.1 Class Set 4pc", additional_info = "[q]Kritische Treffer durch 'Richturteil' wenden 'Herzensfeuer' an und können 'Oberster Kreuzfahrer' auslösen."}
MultiLanguageSpellData['de'][405549] = {name = "Paladinklassenset 10.1, Vergeltung, 2 Teile", additional_info = "[q]'Richturteil' und 'Hammer des Zorns' verursachen 10% mehr Schaden und 15% mehr kritischen Schaden. 'Hammer des Zorns' wendet 'Richturteil' auf Gegner an."}
MultiLanguageSpellData['de'][405550] = {name = "Paladinklassenset 10.1, Vergeltung, 4 Teile", additional_info = "[q]'Richturteil' erhöht den Schaden, den Gegner durch Eure Heilige Kraft verbrauchenden Fähigkeiten erleiden, um zusätzlich 15%. 'Hammer des Zorns' fügt jetzt 4 Zielen in der Nähe 20% seines Schadens zu."}
MultiLanguageSpellData['de'][405551] = {name = "Priest Discipline 10.1 Class Set 2pc", additional_info = "[q]Der Schaden von [ Läuterung des Bösen : 'Läuterung des Bösen' / 'Schattenwort: Schmerz'] wird um 25% erhöht. Die Heilung von 'Machtwort: Glanz' wird um 15% erhöht."}
MultiLanguageSpellData['de'][405552] = {name = "Kampfbereit", additional_info = nil}
MultiLanguageSpellData['de'][405553] = {name = "Priest Discipline 10.1 Class Set 4pc", additional_info = "[q]Wenn ein Ziel durch 'Machtwort: Glanz' mit 'Abbitte' belegt wird, hält der Effekt 3 Sek. länger an. Eure Zauber haben eine Chance, Euer nächstes 'Machtwort: Glanz' zu einem Spontanzauber zu machen und seine Manakosten um 50% zu verringern. Kann bis zu 2 Aufladungen ansammeln."}
MultiLanguageSpellData['de'][405554] = {name = "Priest Holy 10.1 Class Set 2pc", additional_info = "[q]Wenn Ihr 'Gebet der Besserung' wirkt, besteht eine Chance von 35%, dass der Effekt auf einen weiteren Verbündeten kopiert wird."}
MultiLanguageSpellData['de'][405555] = {name = "Wasserbombe", additional_info = "100 Meter Reichweite\n{Sofort} {8 sek. Abklingzeit}\n[q]Schleudert eine massive Kugel aus Wasser, die alle Feuer in der Nähe löscht."}
MultiLanguageSpellData['de'][405556] = {name = "Priest Holy 10.1 Class Set 4pc", additional_info = "[q]Wenn 'Gebet der Besserung' springt oder abläuft, erhöht es den Schaden und die Heilung Eures nächsten Segensworts um 4%. Dieser Effekt ist bis zu 15-mal stapelbar."}
MultiLanguageSpellData['de'][405557] = {name = "Priest Shadow 10.1 Class Set 2pc", additional_info = "[q]Erhöht die Chance, dass 'Schattenhafte Einsicht' ausgelöst wird, um 25%. 'Gedankenschlag' verursacht beim Verbrauchen von 'Schattenhafte Einsicht' 40% mehr Schaden und erzeugt 4 mehr Wahnsinn."}
MultiLanguageSpellData['de'][405558] = {name = "Priest Shadow 10.1 Class Set 4pc", additional_info = "[q]Der Schaden von 'Verschlingende Seuche' ist um 18% erhöht. Jeder 4. Einsatz von 'Verschlingende Seuche' erhöht den Schaden von schattenhaften Erscheinungen, die innerhalb der nächsten 10 Sek. beschworen werden, um 100%."}
MultiLanguageSpellData['de'][405559] = {name = "Rogue Assassination 10.1 Class Set 2pc", additional_info = "[q]'Blutung' verursacht zusätzlich 40% Schaden als Naturschaden. 'Blutroter Sturm' verursacht zusätzlich 20% Schaden als Naturschaden."}
MultiLanguageSpellData['de'][405560] = {name = "Rogue Assassination 10.1 Class Set 4pc", additional_info = "[q]Erhöht Euren verursachten Naturschaden 30 Sek. lang um 40%, wenn 'Todesmal' ausläuft."}
MultiLanguageSpellData['de'][405561] = {name = "Rogue Outlaw 10.1 Class Set 2pc", additional_info = "[q]Schaden, den Ihr verursacht, wendet einen 'Seelenriss' an, der 5% Eures gesamten Schadens im Verlauf von 8 Sek. als körperlichen Schaden verursacht."}
MultiLanguageSpellData['de'][405562] = {name = "Rogue Outlaw 10.1 Class Set 4pc", additional_info = "[q]'Zwischen die Augen' entfesselt jeden 'Seelenriss', wodurch Ihr 200% des verbleibenden Schadens verursacht und 15 Sek. lang 5% Beweglichkeit erhaltet."}
MultiLanguageSpellData['de'][405563] = {name = "Rogue Subtlety 10.1 Class Set 2pc", additional_info = "[q]'Schattentanz' gewährt Euch 6 Sek. lang 'Symbole des Todes' und verlängert die Dauer von 'Blutung' um 4 Sek."}
MultiLanguageSpellData['de'][405564] = {name = "Rogue Subtlety 10.1 Class Set 4pc", additional_info = "[q]'Symbole des Todes' erhöht den kritischen Schaden von 'Ausweiden' und 'Schwarzpulver' um 40%."}
MultiLanguageSpellData['de'][405565] = {name = "Shaman Elemental 10.1 Class Set 2pc", additional_info = "[q]Erhaltet alle 50 Sek. 'Sturmhüter'."}
MultiLanguageSpellData['de'][405566] = {name = "Shaman Elemental 10.1 Class Set 4pc", additional_info = "[q]Nachdem Ihr Sturmhüter verbraucht habt, erzeugen Eure 'Blitzschläge', 'Lavaeruptionen', 'Eisfurore' und 'Frostschocks' 8 Sek. lang 50% mehr Mahlstrom und Eure 'Kettenblitzschläge', 'Lavastrahle' und 'Erdbeben' verursachen 20% mehr kritischen Schaden."}
MultiLanguageSpellData['de'][405567] = {name = "Shaman Enhancement 10.1 Class Set 2pc", additional_info = "[q]'Zerschlagung' erhöht Eure Meisterschaft 15 Sek. lang um (12 * 2 )%."}
MultiLanguageSpellData['de'][405568] = {name = "Shaman Enhancement 10.1 Class Set 4pc", additional_info = "[q]'Zerschlagung' erhöht Euren körperlichen und Feuerschaden 15 Sek. lang um 20% und Eure nächsten 2 Einsätze von 'Kettenblitzschlag' verursachen 20% mehr Schaden und erstatten 50% der verbrauchten Aufladungen von 'Waffe des Mahlstroms' zurück."}
MultiLanguageSpellData['de'][405569] = {name = "Shaman Restoration 10.1 Class Set 2pc", additional_info = "[q]Wenn Ihr 'Heilender Regen' wirkt, wird jeder mit Eurer 'Springflut' belegte Verbündete durch 'Flutwasser' um (322% der Zaubermacht) Gesundheit flächengeheilt."}
MultiLanguageSpellData['de'][405570] = {name = "Shaman Restoration 10.1 Class Set 4pc", additional_info = "[q]Jeder Verbündete, der durch 'Flutwasser' geheilt wird, erhöht 8 Sek. lang Eure hervorgerufene Heilung um 1.0% sowie die Heilung Eures nächsten Einsatzes von 'Welle der Heilung' oder 'Heilende Woge' um 10% oder von 'Kettenheilung' um 2%."}
MultiLanguageSpellData['de'][405571] = {name = "Warlock Affliction 10.1 Class Set 2pc", additional_info = "[q]Verringert die Abklingzeit von 'Übler Makel' um 5 Sek., die Abklingzeit von 'Phantomsingularität' um 12 Sek. und erhöht deren Schaden um 60%."}
MultiLanguageSpellData['de'][405572] = {name = "Warlock Affliction 10.1 Class Set 4pc", additional_info = "[q]Gegner, die durch 'Phantomsingularität' Schaden erleiden, erhalten während seiner Dauer 'Schwäche' und Gegner, die durch 'Übler Makel' Schaden erleiden, erhalten 10 Sek. lang 'Schwäche'. 'Schwäche' erhöht den erlittenen Schaden um 10%."}
MultiLanguageSpellData['de'][405573] = {name = "Warlock Demonology 10.1 Class Set 2pc", additional_info = "[q]'Dämonenblitz' verursacht 20% mehr Schaden. Der Verbrauch eines 'Dämonischen Kerns' verringert die Abklingzeit von 'Grimoire: Teufelswache' um 0.5 Sek."}
MultiLanguageSpellData['de'][405574] = {name = "Warlock Demonology 10.1 Class Set 4pc", additional_info = "[q]Der Schaden von 'Grimoire: Teufelswache' ist um 20% erhöht. Während 'Grimoire: Teufelswache' aktiv ist, verursachen all Eure Dämonen 20% mehr Schaden."}
MultiLanguageSpellData['de'][405575] = {name = "Warlock Destruction 10.1 Class Set 2pc", additional_info = "[q]Blitze von 'Dämonenfeuer kanalisieren', 'Feuerbrand' und 'Verbrennen' haben eine Chance, einen zusätzlichen Dämonenfeuerblitz zu verschießen. Diese Blitze fügen ihrem Primärziel 50% mehr Schaden zu."}
MultiLanguageSpellData['de'][405576] = {name = "Warlock Destruction 10.1 Class Set 4pc", additional_info = "[q]Blitze von 'Dämonenfeuer' erhöhen Euren verursachten Feuerschaden 13 Sek. lang um 1.0%. Bis zu 8-mal stapelbar. Das Hinzugewinnen eines Stapels setzt die Effektdauer nicht zurück. Das Wirken von 'Dämonenfeuer kanalisieren' setzt diesen Effekt zurück."}
MultiLanguageSpellData['de'][405577] = {name = "Kriegerklassenset 10.1, Waffen, 2 Teile", additional_info = "[q]'Tiefe Wunden' erhöht Eure kritische Trefferchance und den an betroffenen Zielen verursachten kritischen Schaden um 5%."}
MultiLanguageSpellData['de'][405578] = {name = "Kriegerklassenset 10.1, Waffen, 4 Teile", additional_info = "[q]Bei kritischen Treffern durch 'Tiefe Wunden' besteht eine Chance, dass der Schaden Eures nächsten Einsatzes von 'Tödlicher Stoß' um 10% erhöht wird und dieser Einsatz Gegnern vor Euch [(19.32% der Angriffskraft) * 2] körperlichen Schaden zufügt. Bis zu 3-mal stapelbar. Der Schaden ist bei über 5 Zielen verringert.\n(2s Abklingzeit)"}
MultiLanguageSpellData['de'][405579] = {name = "Kriegerklassenset 10.1, Furor, 2 Teile", additional_info = "[q]Erhöht den Schaden und die kritische Trefferchance von 'Toben' um 15%."}
