MultiLanguageSpellData['de'][405581] = {name = "Kriegerklassenset 10.1, Schutz, 2 Teile", additional_info = "[q]'Schildschlag' verursacht 15% mehr Schaden und verringert die Abklingzeit von 'Letztes Gefecht' um 2 Sek. Während 'Letztes Gefecht' sind diese Effekte verdoppelt."}
