MultiLanguageSpellData['de'][406393] = {name = "Temporalrausch", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Chronikar stürmt durch die Raumzeit auf den Standort eines Spielercharakters zu, was Spielercharakteren in ihrer Bahn 50 Arkanschaden zufügt und sie wegstößt.\n\n Dann kehrt sie die Raumzeit um, wodurch sie sich zum Spielercharakter zurückteleportiert, den sie ursprünglich angegriffen hat, und schlägt mit ' Temporales Abscheren ' zu."}
