MultiLanguageSpellData['de'][408232] = {name = "10GFX_VoidCosmic_Shader", additional_info = "3% von Grundmana\n{Sofort} {25 sek. Abklingzeit}\n[q]Schirmt Euch 1 Min. lang ab und absorbiert [0 + Frostzaubermacht * 10 * (1 + Vielseitigkeit)] Schaden . Nahkampfangriffe gegen Euch verringern die Bewegungsgeschwindigkeit des Angreifers um 50%."}
MultiLanguageSpellData['de'][408233] = {name = "Weyrnstein verschenken", additional_info = "25 Meter ReichweiteWirken in 3 sek. 1 min Abklingzeit\n[q]Beschwört zwei Weyrnsteine, einen für Euer verbündetes Ziel und einen für Euch selbst. Nur ein Verbündeter kann Euren Weyrnstein zur gleichen Zeit tragen.\n\n Ein Weyrnstein kann von seinem Träger aktiviert werden, um ihn zum Ort des anderen Weyrnsteins zu teleportieren, wenn dieser sich in einem Umkreis von 100 Metern aufhält."}
MultiLanguageSpellData['de'][408234] = {name = "Weyrnstein aktivieren", additional_info = "Wirken in 1.5 sek. 2 min Abklingzeit\n[q]Konzentriert Euch für 1.5 Sek. auf den Stein, um Euch zu dem Träger des zugehörigen Weyrnsteins zu teleportieren, wenn dieser sich in einem Umkreis von 100 Metern aufhält."}
