MultiLanguageSpellData['de'][414177] = {name = "Kataklysmische Auslöschung", additional_info = "Sofort\n[q]Iridikron entfesselt eine kataklysmische Explosion, die allen Spielercharakteren 1212224691 Naturschaden zufügt. Dieser Schaden kann nicht verhindert werden.\n\n Bei der Vorbereitung seines Angriffs fügt er allen Spielercharakteren alle 1.5 Sek. 1818337 Naturschaden zu.\n\n Iridikron verliert Energie, wenn er Schaden erleidet, und wenn seine Energie auf 0 fällt, versagt diese Fähigkeit. Chromie wirkt ' Zeitlinientranszendenz ', um ihre Verbündeten zu unterstützen."}
MultiLanguageSpellData['de'][414178] = {name = "Zeitlinientranszendenz", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Chromie erschafft eine Zeitverzerrungsblase, die Spielercharakteren ihr maximales zukünftiges Potenzial gewährt.\n\n Erhöht den verursachten Schaden um 100%, das Tempo um 100%, die Abklingzeitrate um 100% und die Ressourcenregenerationsrate um 100.\n\n Chromie kann dies nur einmal tun, ohne eine dauerhafte Konvergenz der Zeitlinien zu riskieren."}
