MultiLanguageSpellData['de'][414300] = {name = "Ausrottungsschlag", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Iridikron visiert einen Spielercharakter mit einer verheerenden Erdexplosion an, die Spielercharakteren innerhalb von 20 Metern 121222469 Naturschaden sowie zusätzlich 8 Sek. lang alle 1 Sek. 1454670 Naturschaden zufügt.\n\n Chromies ' Zeitlinienschutz ' reduziert den Schaden dieser Fähigkeit."}
MultiLanguageSpellData['de'][414303] = {name = "Entkoppeln", additional_info = "100 Meter Reichweite\n{Wirken in} {2 sek. 5 sek. Abklingzeit}\n[q]Entfesselt Zeitenergie in die Richtung eines anvisierten Spielercharakters und fügt Spielercharakteren in einem frontalen kegelförmigen Bereich zweimal 16971146 Arkanschaden zu. Wenn beim Ziel der Effekt ' Zeit zersetzen ' aktiv ist, wird der zweite Effekt deutlich verzögert."}
