MultiLanguageSpellData['de'][414658] = {name = "Eiskalt", additional_info = "Sofort 4 min Abklingzeit\n[q]Euer Blut wird eisig, was sämtlichen erlittenen Schaden 6 Sek. lang um 70% verringert.\n\n Verursacht den Effekt 'Unterkühlung', der 30 Sek. lang verhindert, dass 'Eiskalt' erneut gewirkt werden kann."}
MultiLanguageSpellData['de'][414659] = {name = "Eiskalt", additional_info = "[q]'Eisblock' verringert 6 Sek. lang sämtlichen erlittenen Schaden um 70%, gewährt aber keine Immunität mehr und verhindert nicht mehr, dass Ihr Euch bewegt, angreift oder Zauber wirkt. Löst die globale Abklingzeit nicht aus."}
MultiLanguageSpellData['de'][414660] = {name = "Massenbarriere", additional_info = "8% von Grundmana\nSofort 3 min Abklingzeit\n[q]Frost\n Setzt 'Eisbarriere' bei Euch und 4 Verbündeten innerhalb von 40 Metern ein.\n\nFeuer\n Setzt 'Lodernde Barriere' bei Euch und 4 Verbündeten innerhalb von 40 Metern ein.\n\nArkan\n Setzt 'Prismatische Barriere' bei Euch und 4 Verbündeten innerhalb von 40 Metern ein."}
MultiLanguageSpellData['de'][414661] = {name = "Eisbarriere", additional_info = "Sofort\n[q]Umhüllt Euch für 1 Min. mit Eis, das [24 / 100 * Gesamtgesundheit * (1 + Vielseitigkeit)] Schaden absorbiert [ Gletscherpanzer : und Eure Rüstung um 0% erhöht ].\n\n Nahkampfangriffe gegen Euch verringern die Bewegungsgeschwindigkeit des Angreifers um 50%."}
MultiLanguageSpellData['de'][414662] = {name = "Lodernde Barriere", additional_info = "3% von Grundmana\nSofort\n[q]Umhüllt Euch für 1 Min. mit Flammen, die [20 / 100 * Gesamtgesundheit * (1 + Vielseitigkeit)] Schaden absorbieren [ Geschmolzene Haut : und den erlittenen körperlichen Schaden um 0% verringern ].\n\n Nahkampfangriffe gegen Euch fügen dem Angreifer (14.375% der Zaubermacht) Feuerschaden zu."}
MultiLanguageSpellData['de'][414663] = {name = "Prismatische Barriere", additional_info = "3% von Grundmana\nSofort\n[q]Umhüllt Euch für 1 Min. mit einem arkanen Schild, der [20 / 100 * Gesamtgesundheit * (1 + Vielseitigkeit)] Schaden absorbiert und den erlittenen Magieschaden um 15% verringert.\n\n Die Dauer aller schädlichen Magieeffekte gegen Euch wird um 25% verringert."}
MultiLanguageSpellData['de'][414664] = {name = "Massenunsichtbarkeit", additional_info = "6% von Grundmana\nSofort 5 min Abklingzeit\n[q]Ihr und Eure Verbündeten innerhalb von 40 Metern werdet sofort für 12 Sek. unsichtbar. Jegliche Aktion hebt den Effekt auf.\n\n Wirkt sich nicht auf Verbündete aus, die in einen Kampf verwickelt sind."}
