MultiLanguageSpellData['de'][417786] = {name = "Berngefängnis", additional_info = "100 Meter Reichweite\nSofort\n[q]Hüllt einen Gegner in Bern, was diesem alle 1 Sek. 10 Naturschaden zufügt und dabei seine Bewegungsgeschwindigkeit um 15% verringert. Hält 5 Sek. lang an. Dieser Effekt ist stapelbar. Bei Erreichen von 5 Stapeln wird der Gegner für 3 Sek. betäubt."}
