MultiLanguageSpellData['de'][421326] = {name = "Entfachung", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Larodar versucht, mehrere Spielercharaktere mit einem Feuerblitz zu treffen und lässt sie 8 Sek. lang 654259 Heilung absorbieren. Nach 8 Sek. bricht jeder Spielercharakter aus und fügt Spielercharakteren in einem Umkreis von 8 Metern 290095 Feuerschaden zu.\n\n Wenn die Absorption nicht vor Ablauf geheilt wird, belegt ' Entfachung ' getroffene Spielercharaktere zusätzlich mit ' In Asche eingeschlossen '."}
