MultiLanguageSpellData['de'][422798] = {name = "Hackende Qual", additional_info = "300 Meter Reichweite\nSofort\n[q]Igira verursacht 507666 Schattenflammenschaden, stößt Spielercharaktere innerhalb von 45 Metern zurück und entzündet drei Bereiche für Qualen. Spielercharaktere, die innerhalb eines entzündeten Bereichs stehen, lassen ihn schrumpfen, leiden jedoch unter ' Qualen sammeln ', während Igira ihre nächste Waffe schmiedet.\n\n Igiras fertiggestellte Waffen werden aus den nicht vollständig ausgelöschten Bereichen ausgewählt und sie führt beide, um ihre Angriffe zu kombinieren. Wenn kein Bereich vollständig ausgelöscht wurde, entfesselt Igira ' Ruinöses Ende '.\n\n Beim Schmieden einer Waffe sendet jeder Hammerschlag von Igira ' Sengende Funken ' aus."}
MultiLanguageSpellData['de'][422799] = {name = "Schlitzende Qual", additional_info = "300 Meter Reichweite\nSofort\n[q]Igira verursacht 507666 Schattenflammenschaden, stößt Spielercharaktere innerhalb von 45 Metern zurück und entzündet drei Bereiche für Qualen. Spielercharaktere, die innerhalb eines entzündeten Bereichs stehen, lassen ihn schrumpfen, leiden jedoch unter ' Qualen sammeln ', während Igira ihre nächste Waffe schmiedet.\n\n Igiras fertiggestellte Waffen werden aus den nicht vollständig ausgelöschten Bereichen ausgewählt und sie führt beide, um ihre Angriffe zu kombinieren. Wenn kein Bereich vollständig ausgelöscht wurde, entfesselt Igira ' Ruinöses Ende '.\n\n Beim Schmieden einer Waffe sendet jeder Hammerschlag von Igira ' Sengende Funken ' aus."}
