MultiLanguageSpellData['de'][423582] = {name = "Entzündendes Inferno", additional_info = "100 Meter Reichweite\nSofort\n[q]Lohenzar entfesselt eine feurige Explosion auf jede gelöschte Kerze, entzündet sie wieder und fügt allen dabei getroffenen Spielercharakteren 8487876 Feuerschaden zu.\n\n Das Inferno versengt alle Spielercharaktere und fügt ihnen so 8 Sek. lang alle 1 Sek. 242445 Feuerschaden zu. Dieser Effekt ist stapelbar."}
MultiLanguageSpellData['de'][423583] = {name = "Verdammnisbrand", additional_info = "100 Meter Reichweite\nSofort\n[q]Wenn ein 'Dämonischer Kern' verschlungen wird, verursacht dies einen 'Verdammnisbrand', der nach 20 Sek. explodiert und Gegnern in der Nähe (268.747% der Zaubermacht) Schattenschaden oder einem einzigen Gegner [(268.747% der Zaubermacht) * 2.25] Schattenschaden zufügt. 'Hand von Gul'dan' verringert die Dauer Eurer aktiven Verdammnisbrände um 1 Sek. pro verbrauchtem Seelensplitter."}
MultiLanguageSpellData['de'][423584] = {name = "Verdammnisbrand", additional_info = "100 Meter Reichweite\nSofort\n[q]Wenn ein 'Dämonischer Kern' verschlungen wird, verursacht dies einen 'Verdammnisbrand', der nach 20 Sek. explodiert und Gegnern in der Nähe (268.747% der Zaubermacht) Schattenschaden oder einem einzigen Gegner [(268.747% der Zaubermacht) * 2.25] Schattenschaden zufügt. 'Hand von Gul'dan' verringert die Dauer Eurer aktiven Verdammnisbrände um 1 Sek. pro verbrauchtem Seelensplitter."}
MultiLanguageSpellData['de'][423585] = {name = "Schreckensdämon", additional_info = "100 Meter Reichweite\nSofort\n[q]Wenn 'Verdammnisbrand' entfernt wird, besteht eine Chance, einen Schreckensdämon zu beschwören, der 5-mal 'Verdammnisblitzsalve' wirkt, bevor er wieder verschwindet. Jede 'Verdammnisblitzsalve' fügt bis zu 4 Gegnern [(1.553369999\n * (Zaubermacht) * 1 * (1 + Vielseitigkeit)) * 1.169617819] Schattenschaden oder einem einzigen Gegner [((1.553369999\n * (Zaubermacht) * 1 * (1 + Vielseitigkeit)) * 1.169617819) * 2.1] Schattenschaden zu."}
