MultiLanguageSpellData['de'][423590] = {name = "Echos des Zorns", additional_info = "Sofort\n[q]'Zornerfüllte Sanktion' gewährt Euch 'Echos des Zorns', wodurch Euer nächster Einsatz von 'Urteil des Templers' oder 'Göttlicher Sturm' ein zweites Mal mit 25% Effektivität Schaden verursacht. Dieser Effekt verbraucht kein 'Richturteil'.\n(100ms Abklingzeit)"}
MultiLanguageSpellData['de'][423591] = {name = "Sturm des Lichtbringers", additional_info = "100 Meter Reichweite\nSofort\n[q]Der Aschenbringer projiziert den Zauber 'Göttlicher Sturm' 20 Meter nach vorne und fügt allen Gegnern auf dem Weg Schaden zu.\n\n Erhöht zusätzlich den von 'Göttlicher Sturm' verursachten Schaden um 33%."}
MultiLanguageSpellData['de'][423593] = {name = "Göttlicher Sturm", additional_info = "100 Meter Reichweite\nSofort\n[q]Entfesselt einen Wirbel göttlicher Energie, der allen Gegnern in der Nähe [ Brennender Kreuzzug : [(128.05% der Angriffskraft) * 1.05] Strahlenschaden / (128.05% der Angriffskraft) Heiligschaden] zufügt.\n\n Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu."}
