MultiLanguageSpellData['de'][423601] = {name = "Saat von Amirdrassil", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Wenn Amirdrassil zu blühen beginnt, bilden sich auf der Oberfläche Samen, die von Spielercharakteren getragen werden können.\n\n Die Samen entfalten in regelmäßigen Abständen ihre Kraft und ermöglichen Spielercharakteren, die sie tragen, den Start einer ' Blüte '.\n\n Saaten werden ' Lodernde Saat ', wenn sie von Schattenflamme direkt getroffen werden."}
