MultiLanguageSpellData['de'][424577] = {name = "Lodernder Pilz", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Tindral lässt 9 Sek. lang alle 3 Sek. lodernde Pilze um sich herum entstehen. Jeder Pilz bricht nach 3 Sek. aus und fügt Spielercharakteren im Bereich 1087717 körperlichen Schaden sowie 434183 Feuerschaden zu und erhöht ihren durch lodernde Pilze erlittenen Schaden 3 Sek. lang um 500%.\n\n Wenn ' Lodernder Pilz ' keinen Spielercharakter trifft, erleiden alle Spielercharaktere 506547 Feuerschaden."}
MultiLanguageSpellData['de'][424578] = {name = "Lodernder Pilz", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Tindral lässt 9 Sek. lang alle 3 Sek. lodernde Pilze um sich herum entstehen. Jeder Pilz bricht nach 3 Sek. aus und fügt Spielercharakteren im Bereich 1087717 körperlichen Schaden sowie 434183 Feuerschaden zu und erhöht ihren durch lodernde Pilze erlittenen Schaden 3 Sek. lang um 500%.\n\n Wenn ' Lodernder Pilz ' keinen Spielercharakter trifft, erleiden alle Spielercharaktere 506547 Feuerschaden."}
MultiLanguageSpellData['de'][424579] = {name = "Unterdrückende Glut", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Tindral umgibt zufällige Spielercharaktere mit unterdrückender Glut und absorbiert die nächsten 261704 Heilung. Dieser Effekt ist stapelbar."}
MultiLanguageSpellData['de'][424580] = {name = "Sternschnuppe", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Tindral lässt eine Sternschnuppe auf die Plattform stürzen, was allen Spielercharakteren 398880 Astralschaden zufügt und ' Sternfragmente ' zurücklässt."}
MultiLanguageSpellData['de'][424581] = {name = "Feuriges Wachstum", additional_info = "Unbegrenzte Reichweite\nWirken in 1 sek.\n[q]Tindral lässt Flammen im Inneren zufälliger Spielercharaktere anwachsen, die diesen 20 Sek. lang alle 1 Sek. 87028 Feuerschaden zufügen.\n\n Die Flammen brechen aus Spielercharakteren aus, wenn 'Feuriges Wachstum' entfernt wird, die Spielercharaktere mit ' Haftende Asche ' belegen und an der Position des aktuellen Spielercharakters einen Bereich von ' Sengender Boden ' hinterlassen."}
MultiLanguageSpellData['de'][424582] = {name = "Haftende Asche", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Die Asche der Explosion von ' Feuriges Wachstum ' bleibt an allen Spielercharakteren haften und verursacht 2 Sek. lang alle 1 Sek. 14505 Feuerschaden. Dieser Effekt ist stapelbar.\n\n Jeder zusätzliche Stapel von ' Haftende Asche ' erhöht den Schaden um 5000%."}
