MultiLanguageSpellData['de'][425153] = {name = "Feuerteufel", additional_info = "Sofort\n[q]Eure Nahkampfangriffe und -fähigkeiten haben eine Chance, Euer Ziel zu brandmarken, was ihm im Verlauf von 6 Sek. [ 796 * (1.2^9)] Feuerschaden zufügt und Euch ' Feuerteufel ' gewährt. Bis zu 15-mal stapelbar. Der Schaden erhöht sich pro Stapel bis auf ein Maximum von [ 796 * (1.2^5)] Schaden.\n\n Bei mehr als 5 Stapeln erleidet Ihr selbst 50% des Schadens. Bei 15 Stapeln erleiden Gegner in der Nähe Eures Ziels 10% des verursachten Schadens, der auf sie aufgeteilt wird. Außerhalb des Kampfes lässt die Wirkung von ' Feuerteufel ' alle 3 Sek. nach und erlischt nach 15 Sek. vollständig."}
MultiLanguageSpellData['de'][425154] = {name = "Boshafter Brand", additional_info = "15 Meter Reichweite\nSofort\n[q]Eure Nahkampfangriffe und -fähigkeiten haben eine Chance, Euer Ziel zu brandmarken, was ihm im Verlauf von 6 Sek. [ 796 * (1.2^9)] Feuerschaden zufügt und Euch ' Feuerteufel ' gewährt. Bis zu 15-mal stapelbar. Der Schaden erhöht sich pro Stapel bis auf ein Maximum von [ 796 * (1.2^5)] Schaden.\n\n Bei mehr als 5 Stapeln erleidet Ihr selbst 50% des Schadens. Bei 15 Stapeln erleiden Gegner in der Nähe Eures Ziels 10% des verursachten Schadens, der auf sie aufgeteilt wird. Außerhalb des Kampfes lässt die Wirkung von ' Feuerteufel ' alle 3 Sek. nach und erlischt nach 15 Sek. vollständig."}
MultiLanguageSpellData['de'][425156] = {name = "Strahlender Brand", additional_info = "15 Meter Reichweite\nSofort\n[q]Eure Nahkampfangriffe und -fähigkeiten haben eine Chance, Euer Ziel zu brandmarken, was ihm im Verlauf von 6 Sek. [ 796 * (1.2^9)] Feuerschaden zufügt und Euch ' Feuerteufel ' gewährt. Bis zu 15-mal stapelbar. Der Schaden erhöht sich pro Stapel bis auf ein Maximum von [ 796 * (1.2^5)] Schaden.\n\n Bei mehr als 5 Stapeln erleidet Ihr selbst 50% des Schadens. Bei 15 Stapeln erleiden Gegner in der Nähe Eures Ziels 10% des verursachten Schadens, der auf sie aufgeteilt wird. Außerhalb des Kampfes lässt die Wirkung von ' Feuerteufel ' alle 3 Sek. nach und erlischt nach 15 Sek. vollständig."}
