MultiLanguageSpellData['de'][425180] = {name = "Boshafter Brand", additional_info = "45 Meter Reichweite\nSofort\n[q]Eure Nahkampfangriffe und -fähigkeiten haben eine Chance, Euer Ziel zu brandmarken, was ihm im Verlauf von 6 Sek. [ 796 * (1.2^9)] Feuerschaden zufügt und Euch ' Feuerteufel ' gewährt. Bis zu 15-mal stapelbar. Der Schaden erhöht sich pro Stapel bis auf ein Maximum von [ 796 * (1.2^5)] Schaden.\n\n Bei mehr als 5 Stapeln erleidet Ihr selbst 50% des Schadens. Bei 15 Stapeln erleiden Gegner in der Nähe Eures Ziels 10% des verursachten Schadens, der auf sie aufgeteilt wird. Außerhalb des Kampfes lässt die Wirkung von ' Feuerteufel ' alle 3 Sek. nach und erlischt nach 15 Sek. vollständig."}
MultiLanguageSpellData['de'][425181] = {name = "Dornenausbruch", additional_info = "10 Meter Reichweite\nSofort\n[q]Eure Nahkampffähigkeiten haben eine Chance, das Ziel mit 'Dorngeist' zu belegen, was im Verlauf von 15 Sek. ( 723 * 5) Naturschaden verursacht. Wenn Ihr das Ziel trefft, während der Geist noch da ist, werden 265 Naturschaden verursacht, die auf alle Gegner in der Nähe aufgeteilt werden. Dieser Effekt kann nur alle 2 Sek. auftreten.\n\n Wenn ein Ziel stirbt, während es mit 'Dorngeist' belegt ist, sucht sich der Geist einen neuen Gegner."}
MultiLanguageSpellData['de'][425182] = {name = "Statische Aufladung", additional_info = "Sofort\n[q]Solange Ihr Euch in der Nähe von Wänden befindet, sammelt Ihr 'Statische Aufladung', wodurch Ihr Elan wie durch 'Bodenkratzer' aufladet und pro Sekunde einen Stapel erhaltet, bis zu 10. Bei maximalen Stapeln wird 'Blitzerfüllung' verfügbar."}
MultiLanguageSpellData['de'][425196] = {name = "[q3]Der beste Webrahmen", additional_info = "[q0]Animabonus\n20 Meter Reichweite\nSofort\n[q]Webt eine Schicht überragender Rüstung, die den erlittenen Schaden um 50% verringert, die Ausdauer um 100% erhöht und die erzeugte Bedrohung 10 Min. lang deutlich erhöht.\n(1s Abklingzeit)"}
MultiLanguageSpellData['de'][425206] = {name = "Endloses Mondlicht", additional_info = "Sofort\n[q][ Wächter : Mondstrahl\n 'Mondstrahl' lässt Euch nun Leben im Wert von 10% des gesamten Gegnern innerhalb des Strahls zugefügten Schadens rauben.\n\n Zorn der Elune\n 'Zorn der Elune' endet jetzt mit einem Energieblitz, der Gegnern in der Nähe (227.7% der Zaubermacht) Astralschaden zufügt /\n\nGleichgewicht\nZorn der Elune\n 'Zorn der Elune' endet jetzt mit einem Energieblitz, der Gegnern in der Nähe (227.7% der Zaubermacht) Astralschaden zufügt.\n\n Vollmond\n'Vollmond' ruft 2 kleine Monde herab, die (198.4% der Zaubermacht) Astralschaden verursachen und 3 Astrale Macht generieren. ]"}
