MultiLanguageSpellData['de'][426589] = {name = "Nierenhieb", additional_info = "100 Meter Reichweite\nSofort\nBenötigt Nahkampfwaffe\n[q]Finishing-Move, der das Ziel betäubt . Hält pro Combopunkt länger an, bis zu maximal 8 Sek.:\n 1 Punkt: 4 Sek.\n 2 Punkte: 5 Sek.\n 3 Punkte: 6 Sek.\n 4 Punkte: 7 Sek.\n 5 Punkte: 8 Sek."}
