MultiLanguageSpellData['de'][426595] = {name = "Schattentechniken", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Eure automatischen Angriffe haben eine Chance von 28%, 4 Energie zu erzeugen und 1 Combopunkt zu speichern, bis zu einem Maximum von 10 Combopunkten.\n\n Angriffe, die Combopunkte erzeugen, können gespeicherte Combopunkte verbrauchen, um zusätzliche Combopunkte bis zum Maximum zu erzeugen."}
