MultiLanguageSpellData['de'][429634] = {name = "Kolossale Macht", additional_info = "[q]Schutz\n Eure 'Kolossale Macht' erhöht den verursachten Schaden Eures nächsten Einsatzes von 'Demolieren' um 10%. Bis zu 5-mal stapelbar.\n\n 'Schildschlag' gewährt einen Stapel von 'Kolossale Macht' und 'Rache' gewährt einen Stapel von 'Kolossale Macht', wenn die Fähigkeit 3 oder mehr Ziele trifft.\n\nWaffen\n Eure 'Kolossale Macht' erhöht den verursachten Schaden Eures nächsten Einsatzes von 'Demolieren' um 10%. Bis zu 5-mal stapelbar.\n\n 'Tödlicher Stoß' gewährt einen Stapel von 'Kolossale Macht' und 'Spalten' gewährt einen Stapel von 'Kolossale Macht', wenn die Fähigkeit 3 oder mehr Ziele trifft."}
MultiLanguageSpellData['de'][429635] = {name = "Kolossaler Sturmangriff", additional_info = "[q]Eure 'Kolossale Macht' schüchtert Eure Gegner ein. Erhöht Eure kritische Trefferchance und kritische Blockchance bei Gegnern, die von Eurem 'Kolosseinschlag' betroffen sind, 6 Sek. lang um 1% pro Stapel."}
MultiLanguageSpellData['de'][429636] = {name = "Dominanz des Kolosses", additional_info = "[q]Waffen\n 'Kolossale Macht' ist bis zu 10-mal stapelbar. Wenn Ihr bei maximalen Stapeln sonst einen Stapel 'Kolossale Macht' erhalten würdet, verringert sich die Abklingzeit von 'Demolieren' um 2 Sek.\n\n Von 'Demolieren' betroffene Gegner erleiden bis zu 10% mehr Schaden durch Euch und fügen Euch bis zu 10% weniger Schaden zu, abhängig davon, wie viele Stapel 'Kolossale Macht' von 'Demolieren' verbraucht wurden. Hält 10 Sek. lang an.\n\nSchutz\n 'Kolossale Macht' ist bis zu 10-mal stapelbar. Wenn Ihr bei maximalen Stapeln sonst einen Stapel 'Kolossale Macht' erhalten würdet, verringert sich die Abklingzeit von 'Demolieren' um 4 Sek.\n\n Von 'Demolieren' betroffene Gegner erleiden bis zu 20% mehr Schaden durch Euch und fügen Euch bis zu 10% weniger Schaden zu, abhängig davon, wie viele Stapel 'Kolossale Macht' von 'Demolieren' verbraucht wurden. Hält 10 Sek. lang an."}
MultiLanguageSpellData['de'][429637] = {name = "Einer gegen Viele", additional_info = "[q]Schutz\n 'Schockwelle', 'Rache' und 'Wirbelwind' verursachen pro betroffenem Ziel (bis zu 5 Ziele) 3% mehr Schaden.\n\nWaffen\n 'Schockwelle', 'Spalten' und 'Wirbelwind' verursachen pro betroffenem Ziel (bis zu 5 Ziele) 5% mehr Schaden."}
MultiLanguageSpellData['de'][429638] = {name = "Kampfkunstexperte", additional_info = "[q]Erhöht den kritischen Schaden Eurer Fähigkeiten um 10% sowie die Schadensmenge, die Ihr mit kritischem Blocken blockt, um 20%."}
MultiLanguageSpellData['de'][429639] = {name = "Knochenerschütterer", additional_info = "[q]Erhöht die Betäubungsdauer von 'Schockwelle' um 1 Sek. und verringert die Bewegungsgeschwindigkeit betroffener Gegner für 3 Sek., nachdem die Betäubung endet, um 40%."}
MultiLanguageSpellData['de'][429641] = {name = "Kriegsglück", additional_info = "[q]Schutz\n Eure 'Kolossale Macht' erhöht den Schaden von 'Rache' um 7% pro Stapel.\n\nWaffen\n Eure 'Kolossale Macht' erhöht den Schaden von 'Überwältigen' um 5% pro Stapel."}
