MultiLanguageSpellData['de'][430584] = {name = "Saat der Flamme", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Saaten der Flamme, die nicht von einem Spielercharakter zerquetscht werden, sind nach 5 Sek. ein ' Flammender Baum '.\n\n Wenn ein Spielercharakter auf eine ' Saat der Flamme ' tritt, wird diese zerstört. Der Spielercharakter erleidet dabei 108785 Feuerschaden und wird 10 Sek. lang mit ' Keimende Aura ' belegt."}
