MultiLanguageSpellData['de'][430607] = {name = "Boshaftes Fläschchen der klassischen Geister", additional_info = "Wirken in 2 sek. 2\nReagenzien:\nBoshaftes Fläschchen der Ehre , Orbinid (6)\nVerkäufer:\nHotharn\nZone:\nDornogal\nKosten:\n7500\n\n[q2]Benutzen: Trinkt dies, um Eure Manaregeneration um 8% zu erhöhen, wenn Ihr 5 Sek. lang keinen hilfreichen Zauber gewirkt habt, der Mana kostet.\n\n Erhaltene Ehre ist um 15% erhöht.\n\nHält 1 Stunde lang und über den Tod hinaus an. Die Benutzung eines identischen Fläschchens verlängert die Dauer um 1 Stunde\n71"}
MultiLanguageSpellData['de'][430608] = {name = "Boshaftes Fläschchen der Ehre", additional_info = "Wirken in 2 sek. 2\nReagenzien:\nMykopracht (16), Segensblume (8), Goldbesetzte Phiole (2)\nVerkäufer:\nHotharn\nZone:\nDornogal\nKosten:\n7500\n\n[q2]Benutzen: Trinkt dies, um Eure erhaltene Ehre um 15% zu erhöhen. Kann in allen gewerteten und ungewerteten PvP-Umgebungen eingesetzt werden.\n\nHält 1 Stunde lang und über den Tod hinaus an. Die Benutzung eines identischen Fläschchens verlängert die Dauer um 1 Stunde\n71"}
