MultiLanguageSpellData['de'][431038] = {name = "Frostfeuermeisterschaft", additional_info = "[q]Eure schädlichen Feuerzauber erzeugen 1 Stapel 'Feuermeisterschaft' und Frostzauber erzeugen 1 Stapel 'Frostmeisterschaft'.\n\n 'Feuermeisterschaft' erhöht 14 Sek. lang Euer Tempo um 2% und 'Frostmeisterschaft' Eure Meisterschaft um 2%, jeweils bis zu 6-mal stapelbar.\n\n Wenn Stapel hinzukommen, wird die Dauer nicht zurückgesetzt."}
MultiLanguageSpellData['de'][431039] = {name = "Frostmeisterschaft", additional_info = "Sofort\n[q]Eure schädlichen Feuerzauber erzeugen 1 Stapel 'Feuermeisterschaft' und Frostzauber erzeugen 1 Stapel 'Frostmeisterschaft'.\n\n 'Feuermeisterschaft' erhöht 14 Sek. lang Euer Tempo um 2% und 'Frostmeisterschaft' Eure Meisterschaft um 2%, jeweils bis zu 6-mal stapelbar.\n\n Wenn Stapel hinzukommen, wird die Dauer nicht zurückgesetzt."}
MultiLanguageSpellData['de'][431040] = {name = "Feuermeisterschaft", additional_info = "Sofort\n[q]Eure schädlichen Feuerzauber erzeugen 1 Stapel 'Feuermeisterschaft' und Frostzauber erzeugen 1 Stapel 'Frostmeisterschaft'.\n\n 'Feuermeisterschaft' erhöht 14 Sek. lang Euer Tempo um 2% und 'Frostmeisterschaft' Eure Meisterschaft um 2%, jeweils bis zu 6-mal stapelbar.\n\n Wenn Stapel hinzukommen, wird die Dauer nicht zurückgesetzt."}
