MultiLanguageSpellData['de'][432117] = {name = "Kosmische Singularität", additional_info = "{100 Energie} {175 Meter Reichweite}\n{Wirken in} {7 sek. 6 sek. Abklingzeit}\n[q]Ki'katal die Ernterin zieht alle Spielercharakter zu sich heran und beginnt, eine räumliche Verzerrung zu erzeugen. Nach abgeschlossenem Zauber erleiden alle Spielercharaktere im Umkreis von 10 Metern 7273348 Schattenschaden und werden weggestoßen."}
MultiLanguageSpellData['de'][432118] = {name = "Fesselzahn", additional_info = "Nahkampfreichweite\nWirken in 1.5 sek.\n[q]Der Zaubernde beißt sein aktuelles Ziel und bespuckt es mit Spinnweben, was ihm Naturschaden zufügt und es 1 Sek. lang um 35 verlangsamt."}
MultiLanguageSpellData['de'][432119] = {name = "Verblasst", additional_info = "300 Meter Reichweite\nSofort\n[q]Wenn Spielercharaktere von ' Kosmische Singularität ' getroffen werden, löst sich ihre Essenz teilweise auf, wodurch sich ihr verursachter Schaden um 75% verringert und ihr erlittener Schaden um 75% erhöht. Hält 12 Sek. lang an."}
MultiLanguageSpellData['de'][432120] = {name = "Tückisches Spalten", additional_info = "Unbegrenzte Reichweite\n{Wirken in} {1 sek. 1 sek. Abklingzeit}\n[q]Zerstörung\nDas Wirken von 'Chaosblitz', 'Feuerregen' oder 'Schattenbrand' gewährt 'Diabolisches Ritual' für 20 Sek.. Wenn 'Diabolisches Ritual' bereits aktiv ist, wird seine Dauer stattdessen um 1 Sek. verringert.\n\n Wenn 'Diabolisches Ritual' abläuft, erhaltet Ihr 'Dämonische Kunst', wodurch Euer nächster Einsatz von 'Chaosblitz', 'Feuerregen' oder 'Schattenbrand' einen Oberanführer, eine Mutter des Chaos oder einen Grubenlord herbeiruft, die einen vernichtenden Angriff gegen Eure Gegner entfesseln.\n\nDämonologie\nDer Verbrauch eines Seelensplitters gewährt Euch für 20 Sek. 'Diabolisches Ritual'. Während 'Diabolisches Ritual' aktiv ist, verringert jeder für einen schadensverursachenden Zauber verbrauchte Seelensplitter dessen Dauer um 1 Sek.\n\n Wenn 'Diabolisches Ritual' abläuft, erhaltet Ihr 'Dämonische Kunst', wodurch Euer nächster Einsatz von 'Hand von Gul'dan' einen Oberanführer, eine Mutter des Chaos oder einen Grubenlord herbeiruft, die einen vernichtenden Angriff gegen Eure Gegner entfesseln."}
