MultiLanguageSpellData['de'][432768] = {name = "Feengestalt", additional_info = "{Sofort} {16 sek. Abklingzeit}\n[q]- Stärkungseffekt für Zaubernden\n- Hebt Kontrollverlusteffekte auf\n- Mobilität\n\n16 Sek. Abklingzeit\n Verwandelt in eine Feenkreatur und gewährt für kurze Zeit erhöhte Bewegungsgeschwindigkeit und Immunität gegen Schwächungseffekte.\n\n Während der Verwandlung kann nicht angegriffen werden."}
