MultiLanguageSpellData['de'][432770] = {name = "Feengestalt", additional_info = "{Sofort} {12 sek. Abklingzeit}\n[q]- Stärkungseffekt für Zaubernden\n- Hebt Kontrollverlusteffekte auf\n- Mobilität\n\n12 Sek. Abklingzeit\n Verwandelt in eine Feenkreatur und gewährt für kurze Zeit erhöhte Bewegungsgeschwindigkeit und Immunität gegen Schwächungseffekte.\n\n Während der Verwandlung kann nicht angegriffen werden."}
MultiLanguageSpellData['de'][432772] = {name = "Chikokon", additional_info = "40 Meter Reichweite\nSofort\n[q]Ihr erhaltet einen Energieschub, der Euren nächsten Zauber verstärkt.\n\nEinhüllender Nebel : Heilt sofort um (312% der Zaubermacht) Gesundheit und ist ein Spontanzauber.\nErneuernder Nebel : Dauer um 10 Sek. erhöht.\nBeleben : Keine Manakosten.\nTritt der aufgehenden Sonne : Abklingzeit um 9 Sek. verringert.\nSchadensumleitung : Wandelt 25% zusätzliche Heilung in Schaden um und erschafft einen Chikokon, der [Gesamtgesundheit * 16 / 100 * (1 + Vielseitigkeit)] Schaden absorbiert. [ Donnernder Fokustee : Knisternder Jadeblitz : Rückstoßeffekt wird sofort angewendet.\nRollen : Erstattet eine Aufladung zurück und heilt Euch um (240% der Angriffskraft) Gesundheit ]"}
MultiLanguageSpellData['de'][432774] = {name = "Teufelskreuzschlag", additional_info = "8 Meter Reichweite\nWirken in 1.5 sek.\n[q]Schlägt das Ziel mit teufelserfüllten Klingen und verursacht 10 Feuerschaden."}
MultiLanguageSpellData['de'][432775] = {name = "Gefrorene Quelle", additional_info = "100 Meter Reichweite\nSofort 2 min Abklingzeit\n[q]Verleiht Euren Fähigkeiten die Macht der Kugel und gewährt 50 Aufladungen von 'Gefrorene Quelle'. Wenn Ihr Schaden verursacht, wird eine Aufladung verbraucht, die 23 zusätzlichen Frostschaden verursacht sowie Gegner mit 'Quellfrost' belegt, um die Bewegungsgeschwindigkeit von Gegnern um 2% pro Stapel zu verringern.\n\n Wenn 'Gefrorene Quelle' vollständig verbraucht wurde, erleiden alle Ziele, die mit 'Quellfrost' belegt sind, 76 Frostschaden pro Stapel, aufgeteilt auf alle Ziele in der Nähe."}
MultiLanguageSpellData['de'][432777] = {name = "Foliant der instabilen Macht", additional_info = "Ca. 1.5 Procs pro Minute\n[q]Eure schädlichen Zauber haben eine Chance, ein bis drei arkane Illusionen von Euch zu erzeugen. Die arkanen Illusionen kanalisieren 3 Sek. lang, bevor sie 'Arkanbeschuss' auf den Standort Eures Ziels entfesseln und allen Gegnern in diesem Bereich bis zu ( 1343 * 1.1) Arkanschaden zufügen."}
MultiLanguageSpellData['de'][432778] = {name = "Arkane Intelligenz", additional_info = "40 Meter Reichweite\nSofort\n[q]Erfüllt das Ziel mit Brillanz, die seine Intelligenz 1 Stunde lang um 5% erhöht.\n\n Wenn sich das Ziel in Eurer Gruppe oder Eurem Schlachtzug befindet, werden alle Mitglieder den Effekt erhalten."}
