MultiLanguageSpellData['de'][432781] = {name = "Umarmung der Leere", additional_info = "Unbegrenzte Reichweite\nWirken in 2 sek.\n[q]Erschafft eine Hülle aus Leerenenergie, die Schaden in Höhe von 30% der maximalen Gesundheit absorbiert und den eigenen Schaden um 20% erhöht. Bei Ablauf wird der Zaubernde betäubt und erleidet 40% Schaden. Die Leere wird aus dem Körper geschleudert und fügt Spielercharakteren innerhalb der Überreste 7273348 Schattenschaden zu."}
MultiLanguageSpellData['de'][432783] = {name = "Stahlfalle", additional_info = "Sofort\n[q]- Kurze Reichweite\n- Bewegungsunfähigkeit durch Fallen\n- Lange Dauer\n\n16 Sek. Abklingzeit\n Wirft ein Bündel Stahlfallen direkt vor den Zaubernden. Die Fallen fügen Gegnern, die sie auslösen, Schaden zu und machen diese bewegungsunfähig."}
