MultiLanguageSpellData['de'][432799] = {name = "Umarmung der Leere", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Erschafft eine Hülle aus Leerenenergie, die Schaden in Höhe von 30% der maximalen Gesundheit absorbiert und den eigenen Schaden um 20% erhöht. Bei Ablauf wird der Zaubernde betäubt und erleidet 40% Schaden. Die Leere wird aus dem Körper geschleudert und fügt Spielercharakteren innerhalb der Überreste 7273348 Schattenschaden zu."}
MultiLanguageSpellData['de'][432800] = {name = "Heiliges Bollwerk", additional_info = "100 Meter Reichweite\nSofort\n[q]Zwingt das Licht, sich zu konzentrieren und als 'Heilige Bewaffnung' zu manifestieren, die von Eurem verbündeten Ziel geführt werden kann.\n\n Heiliges Bollwerk :\n\nWährend Ihr ein 'Heiliges Bollwerk' tragt, erhaltet Ihr einen Schild, der Schaden in Höhe von 15.0% Eurer maximalen Gesundheit und alle 2 Sek. zusätzlichen Schaden in Höhe von 2.0% Eurer maximalen Gesundheit absorbiert. Hält 20 Sek. lang an.\n\n Wird nach dem Einsatz zu 'Heilige Waffe'."}
MultiLanguageSpellData['de'][432802] = {name = "Solidarität", additional_info = "40 Meter Reichweite\n[q]Wenn Ihr einem Verbündeten eine Bewaffnung gewährt, werden die Vorteile auch Euch zuteil.\n\n Wenn Ihr Euch selbst eine Bewaffnung gewährt, werden die Vorteile auch einem Verbündeten in der Nähe zuteil."}
