MultiLanguageSpellData['de'][433731] = {name = "Bodensturm", additional_info = "100 Meter Reichweite\nSofort\n[q]Anub'zekt gräbt sich durch einen zufälligen Spielercharakter, verursacht 4848899 körperlichen Schaden und stößt Spielercharaktere auf seinem Weg zurück.\n\n Am Ende seines Weges bricht er aus der Erde hervor, verursacht 6061123 körperlichen Schaden und stößt Spielercharaktere im Umkreis von 13 Metern zurück."}
MultiLanguageSpellData['de'][433732] = {name = "Errettung des Lichts", additional_info = "Sofort\n[q]Wenn Ihr einen Himmelshammer herabruft, erhaltet Ihr einen Stapel von 'Errettung des Lichts'.\n\n Während [ Schutz : 'Auge von Tyr' /\n\nVergeltung\n'Aschewelle' ] und 'Hammer des Lichts' nicht verfügbar sind, verbraucht Ihr 60 Stapel von 'Errettung des Lichts', um 'Hammer des Lichts' kostenlos ein zusätzliches Mal einsetzen zu können."}
MultiLanguageSpellData['de'][433734] = {name = "Geläutertes Quellwasser", additional_info = "100 Meter Reichweite\nSofort\n[q]Tränkt Euch im Kampf regelmäßig mit besudeltem ursprünglichen Quellwasser, das für 15 Sek. Eure Vielseitigkeit um 23 sowie Eure Bewegungsgeschwindigkeit um 10% verringert.\n Wenn Ihr die Unreinheiten des Wassers bannt, kehrt sich der Effekt um und erhöht für 15 Sek. Eure Vielseitigkeit um 96 , Eure Bewegungsgeschwindigkeit um 10% und gewährt allen Verbündeten in der Nähe einen Schild in Höhe von 587 ."}
MultiLanguageSpellData['de'][433737] = {name = "Feuerbrandaura", additional_info = "Sofort\n[q]'Feuerbrandaura' hat 1 zusätzliche Aufladung sowie eine Chance von 30%, beim Einsatz eine Aufladung zurückzuerstatten, und verursacht Chaos- statt Feuerschaden.\n\n Ihr könnt mehrere Instanzen von 'Feuerbrandaura' gleichzeitig aktiv haben."}
MultiLanguageSpellData['de'][433740] = {name = "Befall", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Anub'zekt ruft einen Schwarm herbei, der sich an einem zufälligen Spielercharakter gütlich tut und ihm 5 Sek. lang alle 0.5 Sek. 545501 Naturschaden zufügt.\n\n Bei Entfernung formiert sich ein ' Endloser Schwarm ' und macht Jagd auf weitere Beute."}
