MultiLanguageSpellData['de'][434246] = {name = "Das Blut ist Leben", additional_info = "100 Meter Reichweite\nSofort\n[q]Blut\n'Tanzende Runenwaffe' beschwört eine Blutbestie, die Euren Gegner 10 Sek. lang angreift.\n\n Jedes Mal, wenn die Blutbestie angreift, wird ein Teil des verursachten Schadens in ihr gespeichert. Wenn die Blutbestie stirbt, explodiert sie und fügt Gegnern in der Nähe 25% des angesammelten Schadens zu, während sie den Todesritter um denselben Wert heilt. Gibt es mehr als 8 Ziele, wird der verursachte Schaden verringert.\n\nUnheilig\nbeschwört eine Blutbestie, die Euren Gegner 10 Sek. lang angreift.\n\n Jedes Mal, wenn die Blutbestie angreift, wird ein Teil des verursachten Schadens in ihr gespeichert. Wenn die Blutbestie stirbt, explodiert sie und fügt Gegnern in der Nähe 15% des angesammelten Schadens zu, während sie den Todesritter um denselben Wert heilt. Gibt es mehr als 8 Ziele, wird der verursachte Schaden verringert."}
MultiLanguageSpellData['de'][434247] = {name = "Seltsamer Schneemann", additional_info = nil}
MultiLanguageSpellData['de'][434249] = {name = "Kontrolle des Traumes", additional_info = "[q]Gleichgewicht\n Zeit, in der Eure Hauptfähigkeiten verfügbar sind oder maximale Aufladungen erreicht haben, wird von der Abklingzeit dieser Fähigkeit abgezogen, wenn Ihr sie das nächste Mal benutzt, maximal 15 Sek.\n\n Beeinflusst 'Naturgewalt', und 'Konvokation der Geister'.\n\nWiederherstellung\n Zeit, in der Eure Hauptfähigkeiten verfügbar sind oder maximale Aufladungen erreicht haben, wird von der Abklingzeit dieser Fähigkeit abgezogen, wenn Ihr sie das nächste Mal benutzt, maximal 15 Sek.\n\n Beeinflusst 'Schnelligkeit der Natur', 'Inkarnation: Baum des Lebens', und 'Konvokation der Geister'."}
MultiLanguageSpellData['de'][434250] = {name = "Kreatur der Träume", additional_info = nil}
MultiLanguageSpellData['de'][434251] = {name = "Zorn des Urctos", additional_info = "Sofort\n[q]Schlägt den nächsten Gegner, verursacht 206 körperlichen Schaden und gewährt 1 Stapel ' Aufsteigender Zorn ', wenn Ihr oder ein Verbündeter Schaden erleidet. Ein Stapel gewährt 1 Hauptwert. Bis zu 30-mal stapelbar. Dieser Effekt kann alle 3 Sek. auftreten.\n\n Bei 30 Stapeln von ' Aufsteigender Zorn ' erhaltet Ihr 8 Sek. lang ' Zorn des Urctos ', bevor Ihr sie verbraucht. Der Effekt ist eine Gegenmaßnahme gegen alle Treffer und regeneriert alle 1 Sek. 322 Gesundheit.\n\nNur für Tankspezialisierungen gültig.\n(100ms Abklingzeit)"}
MultiLanguageSpellData['de'][434252] = {name = "Massives Schmettern", additional_info = "Wirken in 3.2 sek.\n[q]Stampft auf den Boden, fügt Gegnern innerhalb von 60 Metern 2909340 Naturschaden zu und betäubt sie für 1 Sek."}
MultiLanguageSpellData['de'][434253] = {name = "Allerias dunkler Ansturm", additional_info = "500 Meter Reichweite\n{Sofort} {1.5 sek. Abklingzeit}\n[q]Befiehlt dem Schiff, die Geschwindigkeit zu erhöhen."}
MultiLanguageSpellData['de'][434254] = {name = "Intensität", additional_info = "Sofort\n[q]Erhöht den verursachten Schaden 30 Sek. lang um 10%. Dieser Effekt ist stapelbar."}
MultiLanguageSpellData['de'][434255] = {name = "Segen der Schmiede", additional_info = "100 Meter Reichweite\nSofort\n[q]Beim Einsatz eines Segensworts wird ein Abbild eines Naaru an Eure Seite beschworen. Für die nächsten 9 Sek. imitiert der Naaru alle von Euch gewirkten Heilungs- oder Schadenszauber.\n\n Wenn ein Abbild bereits beschworen wurde, wird dieses Abbild stattdessen verstärkt."}
