MultiLanguageSpellData['de'][434260] = {name = "Das Blut ist Leben", additional_info = "[q]Blut\n 'Tanzende Runenwaffe' beschwört eine Blutbestie, die Euren Gegner 10 Sek. lang angreift.\n\n Jedes Mal, wenn die Blutbestie angreift, wird ein Teil des verursachten Schadens in ihr gespeichert. Wenn die Blutbestie stirbt, explodiert sie und fügt Gegnern in der Nähe 25% des angesammelten Schadens zu, während sie den Todesritter um denselben Wert heilt. Gibt es mehr als 8 Ziele, wird der verursachte Schaden verringert.\n\nUnheilig\n beschwört eine Blutbestie, die Euren Gegner 10 Sek. lang angreift.\n\n Jedes Mal, wenn die Blutbestie angreift, wird ein Teil des verursachten Schadens in ihr gespeichert. Wenn die Blutbestie stirbt, explodiert sie und fügt Gegnern in der Nähe 15% des angesammelten Schadens zu, während sie den Todesritter um denselben Wert heilt. Gibt es mehr als 8 Ziele, wird der verursachte Schaden verringert.\n\n(1s Abklingzeit)"}
MultiLanguageSpellData['de'][434261] = {name = "Pakt der San'layn", additional_info = "[q]Blut\n Ihr speichert 10% sämtlichen verursachten Schattenschadens, in eurer Blutbestie, der bei ihrer Todesexplosion zusätzlich entfesselt wird.\n\nUnheilig\n Ihr speichert 15% sämtlichen verursachten Schattenschadens, in eurer Blutbestie, der bei ihrer Todesexplosion zusätzlich entfesselt wird."}
MultiLanguageSpellData['de'][434263] = {name = "Blutaroma", additional_info = "[q]Blut\n Eure Zauber 'Todesmantel' und 'Todesstoß' haben eine um 15% höhere Chance, 'Vampirstoß' auszulösen, wenn sie Gegnern mit weniger als 35% Gesundheit Schaden zufügen.\n\nUnheilig\n Eure Zauber 'Todesmantel', 'Epidemie' und 'Todesstoß' haben eine um 15% höhere Chance, 'Vampirstoß' auszulösen, wenn sie Gegnern mit weniger als 35% Gesundheit Schaden zufügen."}
