MultiLanguageSpellData['de'][434268] = {name = "Quakplatsch", additional_info = "100 Meter Reichweite\nSofort\n[q]Verzaubert eine Zielposition, sodass sie nach einer kurzen Verzögerung explodiert, allen Gegnern innerhalb von 12 Metern Frostschaden zufügt und sie zurückstößt."}
MultiLanguageSpellData['de'][434269] = {name = "Quakplatsch", additional_info = "40 Meter Reichweite\n{Wirken in} {2 sek. 12 sek. Abklingzeit}\n[q]Verzaubert eine Position, sodass dort nach einer kurzen Verzögerung eine Explosion auftritt, die allen Gegnern innerhalb von 12 Metern Frostschaden zufügt und sie zurückstößt."}
MultiLanguageSpellData['de'][434270] = {name = "Granyths robuste Schuppe", additional_info = "Sofort\n[q]Verringert den erlittenen Schaden 20 Sek. lang um 75% oder bis 12268 Schaden absorbiert wurden. Bei aktivem Schild ist Eure Rüstung um 107 erhöht und wird um weitere 5 erhöht, wenn Ihr einen Treffer erleidet. Bis zu 20-mal stapelbar. Der Schild explodiert, wenn er durchbrochen wird, und verursacht dabei 2683 körperlichen Schaden, der unter allen Gegnern in der Nähe aufgeteilt wird.\n\n Der Schaden erhöht sich für jeden getroffenen Gegner, bis zu einem Maximum von 5 Gegnern."}
