MultiLanguageSpellData['de'][434422] = {name = "Vampirstoß", additional_info = "Sofort\n[q]Unheilig\nEin 'Vampirstoß', der (114.4% der Angriffskraft) Schattenschaden verursacht und Euch um 1% Eurer maximalen Gesundheit heilt.\n\n Gewährt Euch außerdem 20 Sek. lang 'Essenz der Blutkönigin'.\n\nBlut, Frost\nEin 'Vampirstoß', der (75.5885% der Angriffskraft) Schattenschaden verursacht und Euch um 2% Eurer maximalen Gesundheit heilt.\n\n Gewährt Euch außerdem 20 Sek. lang 'Essenz der Blutkönigin'."}
