MultiLanguageSpellData['de'][435103] = {name = "Flinkes Windross", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Windrösser sind ungemein sanft und leicht zu trainieren... wenn man sie fangen kann.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria"}
