MultiLanguageSpellData['de'][435107] = {name = "Waldwindross", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Das Fell dieses Windrosses passt nicht nur farblich zu seiner bewaldeten Heimat, für gewöhnlich ist es auch mit Rindenstücken und Blättern gespickt.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['de'][435108] = {name = "Tagsturmwindross", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Wenn ein Blitz die Sonne trifft, soll ein gleißendes Biest in roter Rüstung aus den Himmeln herabsteigen. Das Tagsturmwindross hat von dieser Legende noch nie gehört und war schon immer hier.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['de'][435109] = {name = "Gefiederter Windwellenreiter", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Vor dem Aufsteigen die aktuelle Windstärke und Höhe überprüfen. Bäume und andere hohe Objekte vermeiden. Beschädigte Drachen sind von der Rückgabe ausgeschlossen.\" - Bedienungsanleitung des Windwellenreiters\nWeltereignis:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['de'][435110] = {name = "Extrahieren", additional_info = nil}
