MultiLanguageSpellData['de'][435115] = {name = "Qilenwächter", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Als Quan der Unerbittliche im Kampf fiel, harrten seine treuen Hunde seiner Rückkehr. Jahrtausende später warten sie noch immer geduldig.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['de'][435118] = {name = "Marmorqilen", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Von einem Mogumagier erschaffen, der seinem Lieblingsstein Leben einhauchte.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['de'][435119] = {name = "Netzwirbel", additional_info = "300 Meter Reichweite\nSofort\n[q]Ulgrax speit Spinnweben auf einen Spielercharakter und alle Verbündeten im Umkreis von 10 Metern und verursacht 17331401 Naturschaden, die gleichmäßig auf alle Spielercharaktere aufgeteilt werden, und fesselt sie an Ulgrax.\n\n Gefesselte Spielercharaktere erleiden alle 2 Sek. 575632 Naturschaden und werden zu Ulgrax gezogen. Die Stärke, mit der Ulgrax die Spielercharaktere anzieht, wird für jeden gefesselten Spielercharakter verringert."}
MultiLanguageSpellData['de'][435123] = {name = "Goldener Reitkranich", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Ein Kaiser soll einst eine große Summe für einen goldenen Kranich bezahlt haben. Als er erkannte, dass der Kranich lediglich seine Farbe mit dem wertvollen Metall teilte, verkroch er sich voller Scham eine Woche in seinem Schlafgemach.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['de'][435124] = {name = "Luxuriöser Reitkranich", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Ein majestätischer Vogel, aber ziemlich wählerisch, was sein Futter angeht.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['de'][435125] = {name = "Tropischer Reitkranich", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Dieser Bewohner des Jadewalds nutzt seine Färbung zur Tarnung.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['de'][435126] = {name = "Silberner Reitkranich", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Dieser große Vogel gehört zu den anmutigsten und elegantesten Kranichen, mehr noch als der Bronzekranich, wenn auch nicht so sehr wie der Goldene.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['de'][435127] = {name = "Rosenreitkranich", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Dieser farbenprächtige Vogel wird oft mit einem Flamingo oder Marabu verwechselt.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['de'][435128] = {name = "Bleicher Reitkranich", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Und ich sah, und siehe, ein fahler... Kranich?\"\nWeltereignis:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['de'][435129] = {name = "Gut gewürzt", additional_info = "100 Meter Reichweite\nSofort\n[q]Der Koch würzt alle Spielercharaktere mit Salz, was alle 1.5 Sek. 4 körperlichen Schaden verursacht und sämtlichen erlittenen Schaden um 10% erhöht. Hält 9 Sek. lang an.\n\n Dieser Effekt ist stapelbar."}
MultiLanguageSpellData['de'][435130] = {name = "Gut gewürzt", additional_info = "100 Meter Reichweite\nSofort\n[q]Der Koch würzt alle Spielercharaktere mit Salz, was alle 1.5 Sek. 4 körperlichen Schaden verursacht und sämtlichen erlittenen Schaden um 10% erhöht. Hält 9 Sek. lang an.\n\n Dieser Effekt ist stapelbar."}
MultiLanguageSpellData['de'][435131] = {name = "Verschneite Reitziege", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Die Bergziegen des Kun-Lai-Gipfels sind bekannt dafür, auf der Suche nach Kafabohnen und Salzlecksteinen selbst die höchsten Wipfel zu erklimmen.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria"}
