MultiLanguageSpellData['de'][435133] = {name = "Kleine rote Reitziege", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Was dieser Ziege an Größe fehlt, macht sie mit Sturheit wett.\"\nWeltereignis:\nMists of Pandaria: Remix"}
