MultiLanguageSpellData['de'][435136] = {name = "Giftpeitscher", additional_info = "20 Meter Reichweite\nWirken in 2 sek.\n[q]Ulgrax schleudert Gift auf alle Spielercharaktere, das beim Einschlag 1726895 Naturschaden sowie 6 Sek. lang alle 1 Sek. 978574 zusätzlichen Naturschaden verursacht."}
MultiLanguageSpellData['de'][435138] = {name = "Verdauungssäure", additional_info = "300 Meter Reichweite\nWirken in 2 sek.\n[q]Ulgrax speit Verdauungssäure auf mehrere Spielercharaktere, die 6 Sek. lang alle 2 Sek. 1726895 Naturschaden verursacht.\n\n Wenn der Effekt entfernt wird, bricht Gift aus der Haut des Opfers aus, das allen Spielercharakteren innerhalb von 7 Metern 1151263 Naturschaden zufügt und jegliche Spinnweben zersetzt, die von ' Pirscherspinnweben ' hinterlassen wurden."}
MultiLanguageSpellData['de'][435140] = {name = "In die Maschine - Verlassen", additional_info = nil}
MultiLanguageSpellData['de'][435141] = {name = "Pakt des Todesbringers", additional_info = "[q]Wenn Ihr Schaden entsprechend 2% Eurer maximalen Gesundheit erleidet, wirkt Ihr sofort 'Todespakt' mit 25% Effektivität. Kann nur alle 50 Min. auftreten.\n\n Wenn ein 'Mal des Schnitters' explodiert, wird die Abklingzeit dieses Effekts und von 'Dunkler Pakt' um 25 Sek. verringert."}
MultiLanguageSpellData['de'][435142] = {name = "In die Maschine - Verlassen - Teleportieren", additional_info = nil}
MultiLanguageSpellData['de'][435143] = {name = "Phasenklingen", additional_info = "Unbegrenzte Reichweite\nKanalisiert (Wirken in 1.5 sek.)\n[q]Sikran markiert Spielcharaktere, springt zu den einzelnen markierten Zielen und fügt jedem auf seinem Weg 3741605 körperlichen Schaden zu.\n\n Zusätzlich wird die erhaltene Heilung betroffener Spielercharaktere um 50% verringert und sie erleiden 20 Sek. lang alle 2 Sek. 474896 zusätzlichen Schattenschaden.\n\n Markierte Ziele hinterlassen ein ' Kosmisches Simulakrum ', wenn sie getroffen werden."}
MultiLanguageSpellData['de'][435144] = {name = "Pfählende Splitter", additional_info = "[q]Jedes Mal, wenn Euer durch 'Permafrost' erzeugter Schild Schaden nimmt, besteht die Chance, dass eisige Splitter auf Gegner in der Nähe gefeuert werden, die (5% der Angriffskraft) Frostschaden verursachen und der Schaden, den Euch Gegner zufügen, wird für 5 Sek. um 5% reduziert."}
MultiLanguageSpellData['de'][435145] = {name = "Blutiger Himmelskreischer", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Dieser Dinosaurier trägt noch immer den Zorn seiner Vorfahren von der Zandalariinvasion in sich.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['de'][435146] = {name = "Nachtpterrorschwinge", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Die Gelehrten erkennen im fürchterlichen Kreischen dieser Kreatur ein \"Fürchtet mich, ich bin die Nacht!\"\"\nWeltereignis:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['de'][435147] = {name = "Jadepterrordax", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Das bevorzugte Reittier der Zandalari ist ein großartiger Sänger, zumindest denkt es das.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['de'][435148] = {name = "Lodernder Angriff", additional_info = "8 Meter Reichweite\nWirken in 1.5 sek.\n[q]Verursacht 4848899 Heiligschaden sowie zusätzlich 10 Sek. lang alle 1 Sek. 484890 Heiligschaden."}
MultiLanguageSpellData['de'][435149] = {name = "Kobaltkoloss", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Die einstige Bergbau- und Holzfällermaschine nahm schnell chaotische Züge an, als den Ingenieuren der Gedanke kam, ob man sie nicht noch etwas cooler machen könnte.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['de'][435150] = {name = "Teufelseisenkoloss", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Diese Kriegsmaschine wurde aus einer Zeitlinie gestohlen, in der Garrosh Höllschrei sich der Brennenden Legion anschloss. Unnötig zu erwähnen, dass von dieser Zeitlinie nicht mehr viel übrig ist.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['de'][435151] = {name = "Auge des Schwarms", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Wenn Anub'zekt 100 Energie erreicht, ruft er einen riesigen Schwarm herbei, der die Arena umgibt. Spielercharaktere innerhalb des Insektenschwarms erhalten schnell Anwendungen von 'Endloser Schwarm'."}
MultiLanguageSpellData['de'][435152] = {name = "Verdauungssäure", additional_info = "300 Meter Reichweite\nSofort\n[q]Ulgrax speit Verdauungssäure auf mehrere Spielercharaktere, die 6 Sek. lang alle 2 Sek. 1726895 Naturschaden verursacht.\n\n Wenn der Effekt entfernt wird, bricht Gift aus der Haut des Opfers aus, das allen Spielercharakteren innerhalb von 7 Metern 1151263 Naturschaden zufügt und jegliche Spinnweben zersetzt, die von ' Pirscherspinnweben ' hinterlassen wurden."}
MultiLanguageSpellData['de'][435153] = {name = "Violetter Shado-Pan-Reittiger", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Wollt Ihr einen Tiger wecken, nehmt einen langen Stock. Oder noch besser: Schickt einen Freund, den Tiger zu wecken.\" - Pandarensprichwort\nWeltereignis:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['de'][435155] = {name = "Feuerhonig halten", additional_info = nil}
MultiLanguageSpellData['de'][435156] = {name = "Lichtausstoß", additional_info = "40 Meter Reichweite\nSofort\n[q]Eine Lichtexplosion fährt aus dem Körper des Auferstandenen und fügt allen Spielercharakteren innerhalb von 60 Metern 1212225 Heiligschaden zu."}
MultiLanguageSpellData['de'][435160] = {name = "Flussläufermushan", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Das Mushan ist eine gierige Bestie. Es kann zwar gezähmt werden, doch wird es ein zweites, drittes, ja sogar viertes Frühstück an jedem Tag verlangen.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['de'][435161] = {name = "Fahles Mushan", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Das fahle Mushan ist das köstlichste seiner Art, allerdings wird es nicht gern daran erinnert.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria"}
