MultiLanguageSpellData['de'][435389] = {name = "[q3]Gedenkstein", additional_info = "Wirken in 2 sek.\nTools: Juwelierswerkzeuge\nReagenzien:\nNullstein (4), Weißer Rosenstrauß , Bismut (50), Aqirit (30), Eisenklauenerz (30), Marmorstein (200)\nVerkäufer:\nLyrendal\nZone:\nDornogal\nKosten:\n150\n\n[q3]Gedenkstein\nSpielzeug\n[q2]Benutzen: Bereitet einem gefallenen Spielercharakter ein respektvolles Begräbnis. (5 Min Abklingzeit)\n[q]\"Seid immer vorbereitet.\""}
MultiLanguageSpellData['de'][435391] = {name = "[q3]Verschönerungsiris", additional_info = "Wirken in 2 sek.\nTools: Juwelierswerkzeuge\nReagenzien:\nZermahlene Edelsteine (40), Invertiertes Prisma (5)\nBeute von:\nWeltkreaturen\n\n[q3]Verschönerungsiris\nSpielzeug\n[q2]Benutzen: Fokussiert einen farbenfrohen Lichtstrahl durch einen Edelstein auf ein hilfloses Kleintier. (10 Min Abklingzeit)\n[q]\"Die Welt ist grässlich, aber das heißt nicht, dass sie auch hässlich sein muss.\""}
