MultiLanguageSpellData['de'][435811] = {name = "Mykopracht", additional_info = "5 Meter Reichweite\nWirken in 2.5 sek.\n[q]Mykopracht ist ein sehr weit verbreiteter Pilz, der auf Khaz Algar zu finden ist. Es kann auf praktisch jedem Terrain gefunden werden, da der Pilz absolut überall wächst."}
MultiLanguageSpellData['de'][435812] = {name = "Üppige Mykopracht", additional_info = "5 Meter Reichweite\nWirken in 2.5 sek.\n[q]Mykopracht ist ein sehr weit verbreiteter Pilz, der auf Khaz Algar zu finden ist. Es kann auf praktisch jedem Terrain gefunden werden, da der Pilz absolut überall wächst.\n\n Manche Kräuter wachsen besonders gut und gedeihen aus allerlei Gründen, ganz unabhängig vom Klima oder Ort. Kräuterkundige, die auf diese seltenen Kräuter stoßen, können zusätzliche nützliche Materialien ergattern.\nEntdeckung:\nIrgendwo in Khaz Algar gefunden"}
MultiLanguageSpellData['de'][435813] = {name = "Instabile Energie", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Wenn Instabile Fragmente aufgehoben werden, werden Heilung und Schaden gegen ' Verstärkter Panzer ' 30 Sek. lang um 50% erhöht. Dieser Effekt ist stapelbar.\n\n Zusätzlich fügt ' Instabile Energie ' allen betroffenen Spielercharakteren alle 2 Sek. 363667 Schattenschaden zu."}
