MultiLanguageSpellData['de'][438592] = {name = "Serum der zügellosen Kampfeslust", additional_info = "Sofort 1 min Abklingzeit\n[q]Konsumiert methodisch eine kleine Dose des Serums, wenn Ihr Euch in den Kampf stürzt, um Eure Sinne bis an ihre Grenzen zu schärfen.\n In diesem Zustand besteht beim Parieren und Ausweichen eine Chance, dem Angreifer mit 'Konter' zu begegnen und ihm Y körperlichen Schaden zufügen."}
MultiLanguageSpellData['de'][438593] = {name = "Lieblingsgericht", additional_info = "100 Meter Reichweite\nSofort\n[q]Benk Sumsebrumm beschwört Fässer mit köstlichem Honig. Ein Zusammenstoß fügt Spielercharakteren, die sich im Umkreis von 3 Metern um den Aufprall befinden, 12122247 körperlichen Schaden zu.\n\n Der Geruch des Honigs lockt alle 30 Sek. eine gefräßige Glutbiene an."}
MultiLanguageSpellData['de'][438595] = {name = "Feuerüberschuss", additional_info = "[q]Frost\n Wenn Ihr 'Kometenhagel' einsetzt, explodiert Euer nächster Einsatz von 'Eislanze' in einem 'Frostfeuerausstoß', der Gegnern in der Nähe (265.6% der Zaubermacht) Frostfeuerschaden zufügt. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu.\n\n 'Frostfeuerausstoß' hat eine Chance von 50%, 'Hirnfrost' zu gewähren.\n\nFeuer\n Wenn Ihr 'Meteor' einsetzt, explodiert Euer nächster Einsatz von 'Feuerschlag' in einem 'Frostfeuerausstoß', der Gegnern in der Nähe (265.6% der Zaubermacht) Frostfeuerschaden zufügt. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu.\n\n 'Frostfeuerausstoß' verringert die Abklingzeit von 'Phönixflammen' um 5 Sek."}
MultiLanguageSpellData['de'][438597] = {name = "Sturmschild", additional_info = "[q]Wenn Ihr 'Einschreiten' bei einem Ziel einsetzt, gewährt ihm das einen Schild, der 5 Sek. lang anhält und Magieschaden in Höhe des 3-Fachen Eurer Rüstung absorbiert."}
MultiLanguageSpellData['de'][438598] = {name = "Sturmschild", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Wenn Ihr 'Einschreiten' bei einem Ziel einsetzt, gewährt ihm das einen Schild, der 5 Sek. lang anhält und Magieschaden in Höhe des 3-Fachen Eurer Rüstung absorbiert."}
MultiLanguageSpellData['de'][438599] = {name = "Bluthieb", additional_info = "40 Meter Reichweite\nSofort\n[q]Schlägt einen Spielercharakter und lässt ihn bluten, wodurch er 3 Sek. lang alle 0.5 Sek. 181834 körperlichen Schaden erleidet. Dieser Effekt ist stapelbar."}
MultiLanguageSpellData['de'][438600] = {name = "Frostüberschuss", additional_info = "[q]Frost\n Wenn Ihr 'Feuerüberschuss' verbraucht, löst Euer nächster Einsatz von 'Hagel' zusätzlich 'Eisnova' mit 150% Effektivität aus.\n\n Wenn Ihr 'Frostüberschuss' verbraucht, wird die Abklingzeit von 'Kometenhagel' um 3 Sek verringert.\n\nFeuer\n Wenn Ihr 'Feuerüberschuss' verbraucht, löst Euer nächster Einsatz von 'Phönixflammen' zusätzlich 'Eisnova' mit 200% Effektivität aus.\n\n Wenn Ihr 'Frostüberschuss' verbraucht, wird die Abklingzeit von 'Meteor' um 5 Sek verringert."}
