MultiLanguageSpellData['de'][439732] = {name = "Optimiertes Relikt", additional_info = "Sofort\n[q]Außerhalb eines Kampfes steigt die Bewegungsgeschwindigkeit der Gruppenmitglieder um 10%. Bei Kampfeintritt steigt das Tempo der Gruppenmitglieder 8 Sek. lang um 5%."}
MultiLanguageSpellData['de'][439735] = {name = "Reiches Thema", additional_info = "5 Meter Reichweite\nWirken in 2.5 sek.\n[q]Gelegentlich finden sich unter der Oberfläche ungewöhnlich große Vorkommen, sehr zur Freude von Minenarbeitern, die damit ihr tägliches Brot verdienen."}
MultiLanguageSpellData['de'][439736] = {name = "Flözthema", additional_info = "5 Meter Reichweite\nWirken in 2.5 sek.\n[q]Selbst unter der Oberfläche sind metallreiche Flöze ein eher seltener und aufregender Anblick. Man findet sie gewöhnlicherweise an Wänden oder Decken in besonders engen Räumen."}
MultiLanguageSpellData['de'][439737] = {name = "Kristallisiertes Thema", additional_info = "5 Meter Reichweite\nWirken in 2.5 sek.\n[q]Aufgrund ihrer Nähe zum Kernweg haben einige Vorkommen eine direkte Verbindung zur Weltenseele. Jeder Minenarbeiter erhält beim Abbau einen kleinen Segen sowie etwas kristallines Pulver, eine nützliche Reagenz für viele Herstellungsverfahren."}
MultiLanguageSpellData['de'][439738] = {name = "Heulendes Thema", additional_info = "5 Meter Reichweite\nWirken in 2.5 sek.\n[q]Das schwarze Blut der Alten Götter hat begonnen, sich unter Khaz Algar anzusammeln. Sein Schwären wirkt sich sogar auf die wertvollen Metalle aus, mit denen es in Berührung kommt. Jeder Minenarbeiter, der sich den tiefsten Tiefen stellt und derartige Vorkommen abbaut, wird Qualen erleiden, wie sie Sterbliche eigentlich nicht ertragen können. Glücklicherweise erhalten Überlebende dafür aber auch zappelnde Proben."}
