MultiLanguageSpellData['de'][439763] = {name = "Ausschlussprinzip", additional_info = "300 Meter Reichweite\nSofort\n[q]Izo ruft alle Anomalien zurück an ihren Standort und schleudert sie dann eine nach der anderen gewaltsam auf ihr Ziel. Fügt Spielercharakteren innerhalb von 10 Metern im Verlauf von 3 Sek. insgesamt 3-mal 4848899 Schattenschaden und 5818679 körperlichen Schaden zu."}
