MultiLanguageSpellData['de'][439776] = {name = "Säurepfützen", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]'Ätzspucke', 'Ätzender Hagel' und 'Walzende Säure' können 1.5 Min. lang ätzende Zonen bilden. Der Kontakt mit einer solchen Zone verursacht alle 0.5 Sek. 1582987 Naturschaden."}
MultiLanguageSpellData['de'][439777] = {name = "Säurepfützen", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]'Ätzspucke', 'Ätzender Hagel' und 'Walzende Säure' können 1.5 Min. lang ätzende Zonen bilden. Der Kontakt mit einer solchen Zone verursacht alle 0.5 Sek. 1582987 Naturschaden."}
MultiLanguageSpellData['de'][439778] = {name = "Spinndrüsengespinstriss", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Wenn ' Spinndrüsenstränge ' reißen, erleiden alle Spielercharaktere 690758 Naturschaden."}
MultiLanguageSpellData['de'][439779] = {name = "Spinndrüsenstränge", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Rasha'nan beschießt markierte Ziele mit Netzen, die Spielercharakteren innerhalb von 0 Metern 2014711 Naturschaden zufügen, alle getroffenen Spielercharaktere fesseln und ' Klebrige Netze ' erschaffen. Die Fessel verursacht alle 1 Sek. 575632 Naturschaden und zieht Opfer nach innen.\n\n Wenn die Fessel 0 Meter gedehnt wird, reißt sie und löst einen ' Spinndrüsengespinstriss ' aus."}
MultiLanguageSpellData['de'][439780] = {name = "Klebrige Netze", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Die ' Spinndrüsenstränge ' überziehen die Arena mit Seidenkleber, der alle 0.5 Sek. 115126 Naturschaden verursacht und die Bewegungsgeschwindigkeit um 20% verringert."}
MultiLanguageSpellData['de'][439781] = {name = "Spinndrüsenstränge", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Rasha'nan beschießt markierte Ziele mit Netzen, die Spielercharakteren innerhalb von 0 Metern 2014711 Naturschaden zufügen, alle getroffenen Spielercharaktere fesseln und ' Klebrige Netze ' erschaffen. Die Fessel verursacht alle 1 Sek. 575632 Naturschaden und zieht Opfer nach innen.\n\n Wenn die Fessel 0 Meter gedehnt wird, reißt sie und löst einen ' Spinndrüsengespinstriss ' aus."}
