MultiLanguageSpellData['de'][439784] = {name = "Spinndrüsenstränge", additional_info = "Wirken in 2 sek.\n[q]Rasha'nan beschießt markierte Ziele mit Netzen, die Spielercharakteren innerhalb von 0 Metern 2014711 Naturschaden zufügen, alle getroffenen Spielercharaktere fesseln und ' Klebrige Netze ' erschaffen. Die Fessel verursacht alle 1 Sek. 575632 Naturschaden und zieht Opfer nach innen.\n\n Wenn die Fessel 0 Meter gedehnt wird, reißt sie und löst einen ' Spinndrüsengespinstriss ' aus."}
MultiLanguageSpellData['de'][439785] = {name = "Korrosion", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Abscheuliche Säure korrodiert das Ziel für 15 Sek., wodurch es alle 863447 Sek. 1.5 Naturschaden erleidet. Dieser Effekt ist stapelbar."}
MultiLanguageSpellData['de'][439786] = {name = "Walzende Säure", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Rasha'nan stößt ein giftiges Gebräu auf markierte Ziele aus, das in Wellen vom Ziel aus in die angegebene Richtung schwappt.\n\n Spielercharaktere, die von der anfänglichen ätzenden Eruption bespritzt werden, erleiden ' Ätzende Benommenheit '.\n\n Jeder Spielercharakter, der eine Welle berührt, wird um 50% verlangsamt und wird alle 1 Sek. mit ' Korrosion ' belegt.\n\n Die Wellen verbrennen ' Klebrige Netze ', fügen Spielcharakteren im Umkreis von 5 Metern 1726895 Naturschaden zu und erzeugen ' Säurepfützen '."}
MultiLanguageSpellData['de'][439787] = {name = "Ätzende Benommenheit", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Die ' Walzende Säure ' wird katapultartig ausgestoßen, verursacht 4029421 Naturschaden und betäubt Opfer für 1.5 Sek."}
