MultiLanguageSpellData['de'][439794] = {name = "Netzbrecher", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Rasha'nan hackt auf das Zielgebiet ein, verursacht 56987520 Naturschaden und zieht die Spielercharaktere zu sich. Diese Effekte verteilen sich gleichmäßig auf die Spielercharaktere im Umkreis von 8 Metern um den Einschlagsort.\n\n Wenn 'Netzbrecher' nicht mindestens 4 Ziele trifft, erleiden alle Spielercharaktere den vollen Effekt."}
