MultiLanguageSpellData['de'][440042] = {name = "Verdunkelnde Seele", additional_info = "[q]Dämonologie, Zerstörung\n Der durch 'Feuerbrand' verursachte regelmäßige Schaden hat die Chance, dem Ziel über 15 Sek. (46.9878% der Zaubermacht) Schattenflammenschaden zuzufügen.\n\n Schaden durch 'Chaosblitz' verbraucht 'Verdunkelnde Seele' und verursacht den übrigen Schaden sofort. Schaden, der durch 'Feuerregen' verursacht wird, verbraucht 1 Sek. von 'Verdunkelnde Seele'.\n\nGebrechen\n Der durch 'Verderbnis' verursachte regelmäßige Schaden hat die Chance, dem Ziel über 15 Sek. (46.9878% der Zaubermacht) Schattenflammenschaden zuzufügen.\n\n Schaden durch 'Unheilvolle Euphorie' verbraucht 'Verdunkelnde Seele' und verursacht den übrigen Schaden sofort."}
MultiLanguageSpellData['de'][440043] = {name = "Geschwärzte Seele", additional_info = "[q]Das Verbrauchen von Seelensplittern für Schadenszauber verderbt Gegner, die von Eurem 'Welken' betroffen sind, noch weiter und erhöht die Anzahl der Stapel von 'Welken' um 1.\n\n Immer wenn sich die Stapel von 'Welken' erhöhen, besteht eine Chance, dass der Effekt zerfällt, wodurch alle 1 Sek. ein Stapel entfernt wird, um dem Opfer (76.6411% der Zaubermacht) Schattenflammenschaden zuzufügen, bis noch 1 Stapel übrig ist."}
MultiLanguageSpellData['de'][440044] = {name = "Xalans Wildheit", additional_info = "[q]Gebrechen\n Durch Eure Zauber und Fähigkeiten verursachter Feuerschaden wird um 6% erhöht und die kritische Trefferchance Eurer Feuerzauber aus allen Quellen steigt um 10%.\n\nZerstörung\n Durch Eure Zauber und Fähigkeiten verursachter Feuerschaden wird um 8% erhöht und die kritische Trefferchance Eurer Feuerzauber aus allen Quellen steigt um 10%."}
MultiLanguageSpellData['de'][440045] = {name = "Mal von Peroth'arn", additional_info = "[q]Zerstörung\n Erhöht den kritischen Schaden von 'Welken' um 10%.\n\n 'Welken' hat eine Chance, bei kritischen Treffern einen Stapel zu erhalten. Auf diese Weise erhaltene Stapel aktivieren 'Geschwärzte Seele' nicht.\n\nGebrechen\n Erhöht den kritischen Schaden von 'Welken' um 25%.\n\n 'Welken' hat eine Chance, bei kritischen Treffern einen Stapel zu erhalten. Auf diese Weise erhaltene Stapel aktivieren 'Geschwärzte Seele' nicht."}
MultiLanguageSpellData['de'][440046] = {name = "Mal von Xavius", additional_info = "[q][ Agonie : Erhöht den Schaden von 'Agonie' um 20% / Erhöht den Schaden von 'Welken' um 25%.]\n 'Geschwärzte Seele' verursacht pro Stapel von 'Welken' 2% mehr Schaden."}
