MultiLanguageSpellData['de'][441295] = {name = "Raureifdolch", additional_info = "100 Meter Reichweite\nSofort\n[q]Vx versieht ihre Dolche mit Eis und stößt sie in ihr aktuelles Ziel, wodurch sie 7273348 körperlichen Schaden und 10 Anwendungen von ' Eisiges Blut ' verursacht. Dann zerspringen die Dolche und fügen allen Spielercharakteren 2424449 Frostschaden zu."}
