MultiLanguageSpellData['de'][441994] = {name = "Kerzenlicht", additional_info = "300 Meter Reichweite\nSofort\n[q]Von Euch geht eine schwache Flamme aus. Die Dunkelheit vermag sie nicht zu vertreiben, aber sie offenbart 5 Min. lang durch die Dunkelheit verborgene Geheimnisse.\n\n Solange das Licht scheint, könnt Ihr nicht in Verstohlenheit übergehen."}
