MultiLanguageSpellData['de'][442037] = {name = "Spinndrüsenstränge", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Rasha'nan beschießt anvisierte Spielercharaktere mit Netzen, die Spielercharakteren innerhalb von 10 Metern 719539 Schattenschaden zufügen, das ursprüngliche Ziel fesseln und ' Klebrige Netze ' erschaffen.\n\n Die Verbindung verursacht alle 1 Sek. 172689 Schattenschaden und zieht das ursprüngliche Ziel zu sich. Wenn man sich 0 Meter bewegt, reißt die Verbindung, was einen ' Spinndrüsengespinstriss ' auslöst."}
MultiLanguageSpellData['de'][442038] = {name = "Spinndrüsenstränge", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Rasha'nan beschießt markierte Ziele mit Netzen, die Spielercharakteren innerhalb von 0 Metern 2014711 Naturschaden zufügen, alle getroffenen Spielercharaktere fesseln und ' Klebrige Netze ' erschaffen. Die Fessel verursacht alle 1 Sek. 575632 Naturschaden und zieht Opfer nach innen.\n\n Wenn die Fessel 0 Meter gedehnt wird, reißt sie und löst einen ' Spinndrüsengespinstriss ' aus."}
