MultiLanguageSpellData['de'][442428] = {name = "Dezimieren", additional_info = "300 Meter Reichweite\nWirken in 2 sek.\n[q]Sikran entfesselt mit seiner Stangenwaffe ein Sperrfeuer aus kosmischen Eruptionen, die allen Spielercharakteren zwischen ihm und seinen Zielen 1439079 Schattenschaden zufügen.\n\n Von dem Effekt betroffene kosmische Simulakren werden zerstört."}
MultiLanguageSpellData['de'][442429] = {name = "Lauffeuerdocht", additional_info = "Ca. 6 Procs pro Minute\n[q]Eure Nahkampfangriffe haben eine Chance, das Ziel in Brand zu stecken und ihm so ( 53 * 11) Feuerschaden im Verlauf von 11 Sek. zuzufügen.\n\n Wenn dieser Effekt ausgelöst wird, während das Ziel bereits brennt, wird seine Dauer erneuert und er breitet sich auf einen Gegner in der Nähe aus."}
MultiLanguageSpellData['de'][442430] = {name = "Schwarzblut einnehmen", additional_info = "100 Energie Unbegrenzte Reichweite\nSofort\n[q]Wenn Brutverderber Ovi'nax seine volle Energie erreicht hat, stürzt er sich auf einen vollen Kanister Schwarzblut und beginnt, ihn zu verschlingen. Durch das Verschlingen des Kanisters entfesselt er alle 5 Sek. einen Schwall von ' Widerwärtige Entladung ' und verursacht 1439079 Schattenschaden, der bei allen Spielercharakteren die nächsten 2453672 Heilung absorbiert. Wenn der Kanister leer ist, erhält Brutverderber Ovi'nax ' Instabile Infusion '."}
