MultiLanguageSpellData['de'][442648] = {name = "[q2]Köder für tosende Anglersucher", additional_info = "Wirken in 2 sek.\nReagenzien:\nTrödelnder Häsling , Blutbarsch , Kristalliner Stör , Bismutbitterling\nSpezialisierung:\nAbbauen - Fischereifreund (40)\n\n[q2]Köder für tosende Anglersucher\n[q2]Benutzen: Taucht Euren Haken in Anglersucherköder, der einen Fang aus jedem Fischschwarm in den Schallenden Tiefen oder Heilsturz garantiert.\n\n Dieser Köder hält 30 Min. lang an und lässt sich bis zu 50-mal stapeln.\n70"}
MultiLanguageSpellData['de'][442649] = {name = "[q3]Infusion: Kristall", additional_info = "Wirken in 2 sek.\nReagenzien:\nKöder für scheue Kreaturen , Kristallines Pulver (3)\nSpezialisierung:\nKödern - Inspirierender Infusor\n\n[q3]Köder für kristalline Kreaturen\nWird beim Aufheben gebunden\n[q2]Benutzen: Platziert den Köder, was nach kurzer Zeit eine scheue Kreatur anlockt. Wer weiß, was sich blicken lässt?\n\n Die Abklingzeit des Köders für scheue Kreaturen wird beim Kürschnern von Kreaturen in Khaz Algar verringert.\n\n Kann nur im Freien in Khaz Algar verwendet werden.\n70\n[q]\"Ein verlockender Köder, um scheue Kreaturen aus ihrem Versteck zu locken. Mit Kristallpulver angereichert.\""}
MultiLanguageSpellData['de'][442650] = {name = "[q3]Infusion: Sporen", additional_info = "Wirken in 2 sek.\nReagenzien:\nKöder für scheue Kreaturen , Grünliche Sporen (3)\nSpezialisierung:\nKödern - Inspirierender Infusor (20)\n\n[q3]Köder für sporenverschmolzene Kreaturen\nWird beim Aufheben gebunden\n[q2]Benutzen: Platziert den Köder, was nach kurzer Zeit eine scheue Kreatur anlockt. Wer weiß, was sich blicken lässt?\n\n Die Abklingzeit des Köders für scheue Kreaturen wird beim Kürschnern von Kreaturen in Khaz Algar verringert.\n\n Kann nur im Freien in Khaz Algar verwendet werden.\n70\n[q]\"Ein verlockender Köder, um scheue Kreaturen aus ihrem Versteck zu locken. Mit magischen Sporen angereichert.\""}
MultiLanguageSpellData['de'][442651] = {name = "[q3]Infusion: Zuckend", additional_info = "Wirken in 2 sek.\nReagenzien:\nKöder für scheue Kreaturen , Zappelnde Probe\nSpezialisierung:\nKödern - Inspirierender Infusor (40)\n\n[q3]Köder für zuckende Kreaturen\nWird beim Aufheben gebunden\n[q2]Benutzen: Platziert den Köder, was nach kurzer Zeit eine scheue Kreatur anlockt. Wer weiß, was sich blicken lässt?\n\n Die Abklingzeit des Köders für scheue Kreaturen wird beim Kürschnern von Kreaturen in Khaz Algar verringert.\n\n Kann nur im Freien in Khaz Algar verwendet werden.\n70\n[q]\"Ein verlockender Köder, um scheue Kreaturen aus ihrem Versteck zu locken. Mit einer Essenz angereichert, die vor boshafter Energie trieft.\""}
