MultiLanguageSpellData['de'][442799] = {name = "Blutiger Überschuss", additional_info = "300 Meter Reichweite\nSofort\n[q]Schwarzblut ergießt sich aus Kanistern über den Boden der Kammer und breitet sich langsam aus. Die Lache verursacht alle 0.5 Sek. 287816 Schattenschaden und absorbiert die nächsten 490734 von Spielercharakteren innerhalb des Effektbereichs erhaltene Heilung.\n\n Experimentelle Eier, die in Kontakt mit der Lache kommen, lösen eine ' Ätzende Reaktion ' aus."}
MultiLanguageSpellData['de'][442801] = {name = "Lauffeuerdocht", additional_info = "50 Meter Reichweite\nSofort\n[q]Eure Nahkampfangriffe haben eine Chance, das Ziel in Brand zu stecken und ihm so ( 53 * 11) Feuerschaden im Verlauf von 11 Sek. zuzufügen.\n\n Wenn dieser Effekt ausgelöst wird, während das Ziel bereits brennt, wird seine Dauer erneuert und er breitet sich auf einen Gegner in der Nähe aus."}
