MultiLanguageSpellData['de'][442988] = {name = "[q2]Magischer Mulch", additional_info = "Wirken in 2 sek.\nReagenzien:\nMykopracht (5)\nSpezialisierung:\nBotanik - Mulchherstellung\n\n[q2]Magischer Mulch\nWird beim Aufheben gebunden\n[q2]Benutzen: Bereitet den Mulch für dessen Verwendung vor. Bedeckt damit Eure nächsten Kräuter, die Ihr sammeln möchtet, um eine mittlere Menge Finesse zu erhalten. Ihr könnt immer nur jeweils eine Portion Mulch verwenden.\n70\nBenötigtKräuterkunde von Khaz Algar\n(1)"}
MultiLanguageSpellData['de'][442989] = {name = "[q3]Verzauberter Mulch", additional_info = "Wirken in 2 sek.\nReagenzien:\nLeylinienrückstände (2), Mykopracht (10)\nSpezialisierung:\nBotanik - Mulchherstellung (20)\n\n[q3]Verzauberter Mulch\nWird beim Aufheben gebunden\n[q2]Benutzen: Bereitet den Mulch für dessen Verwendung vor. Bedeckt damit Eure nächsten Kräuter, die Ihr sammeln möchtet, um eine große Menge Finesse zu erhalten. Ihr könnt immer nur jeweils eine Portion Mulch verwenden.\n70\nBenötigtKräuterkunde von Khaz Algar\n(1)"}
MultiLanguageSpellData['de'][442990] = {name = "[q4]Machterfüllter Mulch", additional_info = "Wirken in 2 sek.\nReagenzien:\nGrünliche Sporen (4), Mykopracht (15)\nSpezialisierung:\nBotanik - Mulchherstellung (40)\n\n[q4]Machterfüllter Mulch\nWird beim Aufheben gebunden\n[q2]Benutzen: Bereitet den Mulch für dessen Verwendung vor. Bedeckt damit Eure nächsten Kräuter, die Ihr sammeln möchtet, um eine riesige Menge Finesse zu erhalten. Ihr könnt immer nur jeweils eine Portion Mulch verwenden.\n70\nBenötigtKräuterkunde von Khaz Algar\n(1)"}
