MultiLanguageSpellData['de'][443328] = {name = "Umhüllen", additional_info = "{5% von Grundmana} {25 Meter Reichweite}\n{Sofort} {27 sek. Abklingzeit}\n1 Aufladung\n[q]Verheerung\n Umhüllt Euer Ziel mit Drachenflammen, die ihm (962% der Zaubermacht) Feuerschaden zufügen oder es um (1020% der Zaubermacht) Gesundheit heilen. Für jeden Eurer regelmäßigen Effekte auf dem Ziel wird die Effektivität um 20% erhöht.\n\n Setzt voraus, dass 'Feueratem' für das Ziel aktiv ist.\n\nBewahrung\n Umhüllt Euer Ziel mit Drachenflammen, die ihm (962% der Zaubermacht) Feuerschaden zufügen oder es um (1020% der Zaubermacht) Gesundheit heilen. Für jeden Eurer regelmäßigen Effekte auf dem Ziel wird die Effektivität um 20% erhöht.\n\n Setzt voraus, dass 'Traumatem' oder 'Feueratem' für das Ziel aktiv ist."}
MultiLanguageSpellData['de'][443329] = {name = "Umhüllen", additional_info = "25 Meter Reichweite\nSofort\n[q]Umhüllt Euer Ziel mit Drachenflammen, die ihm (962% der Zaubermacht) Feuerschaden zufügen oder es um (1020% der Zaubermacht) Gesundheit heilen. Für jeden Eurer regelmäßigen Effekte auf dem Ziel wird die Effektivität um 20% erhöht.\n\n Setzt voraus, dass [ Bewahrung : 'Traumatem' oder 'Feueratem' /\n\nVerheerung\n'Feueratem' ] für das Ziel aktiv ist."}
