MultiLanguageSpellData['de'][443446] = {name = "Letzter Ruf", additional_info = "[q]Elementar\n Wenn ein Ahne abtritt, setzt er 'Elementarschlag' gegen einen Gegner in der Nähe ein.\n\nWiederherstellung\n Wenn ein Ahne abtritt, setzt er 'Hydroblase' gegen einen verwundeten Verbündeten in der Nähe ein.\n\n Hydroblase\nUmgibt Euer Ziel 15 Sek. lang mit einer schützenden Wasserblase.\n\n Der Schild absorbiert den nächsten eintreffenden Schaden in Höhe von 0, aber die absorbierte Menge nimmt im Laufe seiner Dauer kontinuierlich bis auf 0 ab."}
MultiLanguageSpellData['de'][443447] = {name = "Mahlstrom-Überlegenheit", additional_info = "[q]Elementar\n Erhöht den Schaden von 'Erdschock', 'Elementarschlag' und 'Erdbeben' um 25%.\n\n Erhöht die Heilung von 'Heilende Woge' und 'Kettenheilung' um 25%.\n\nWiederherstellung\n Erhöht die Heilung von 'Welle der Heilung', 'Heilende Woge', 'Lebensquell', 'Platzregen' und 'Kettenheilung' um 25%."}
