MultiLanguageSpellData['de'][443515] = {name = "Schicksalsfaden", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Eure schädlichen und hilfreichen Zauber haben eine Chance, für 5 Sek. einen Schicksalsfaden zwischen Euch und Eurem Ziel zu weben. Angeleinte Verbündete erhalten einen Bonus von 47 auf Ihren Primärwert, solange der Faden hält, und Gegner erleiden ( 1 * 975 ) kosmischen Schaden, wenn der Faden reißt."}
