MultiLanguageSpellData['de'][443527] = {name = "Verziertes Lohenzarwachs", additional_info = "Ca. 2 Procs pro Minute\n[q]Eure Zauber haben eine Chance, das Wachs zu verzaubern, um für 15 Sek. eine lodernde Kerze zu erzeugen, die Eure Vielseitigkeit um 122 und, während Ihr in ihrem Licht bleibt, weiter um 32 erhöht."}
