MultiLanguageSpellData['de'][443529] = {name = "Stichel des Kerzenkönigs", additional_info = "40 Meter Reichweite\nSofort 1.5 min Abklingzeit\n[q]Schnitzt eine Wachskopie Eures Ziels, die 50% des erlittenen Schadens absorbiert. Durch die Absorption erhitzt sich das Wachs, bis es nach Absorption von 6705 Schaden schmilzt."}
MultiLanguageSpellData['de'][443530] = {name = "Fragment der Dunkelheit", additional_info = "Ca. 2 Procs pro Minute\n[q]Eure Fähigkeiten haben eine Chance, die Dunkelheit zu Euch zu rufen, wodurch sich Eure Hauptwert um 19 erhöht, bis zu ( 19 * 5).\n\n Bei Erreichen voller Kraft wird die Dunkelheit entfesselt und verursacht ( 1 * 1789 * 15 / 3) Schattenschaden, die zwischen Gegnern in der Nähe im Verlauf von 15 Sek. aufgeteilt werden, bevor sie wieder in das Fragment verblasst."}
MultiLanguageSpellData['de'][443531] = {name = "Anstachelndes Licht", additional_info = "Sofort 2 min Abklingzeit\n[q]Erhebt Euer Siegel zum Licht und erhöht so Euren höchsten Sekundärwert 20 Sek. lang um 260 . Eure Tat inspiriert andere Siegelträger Eurer Gruppe in der Nähe und gewährt ihnen 20 Sek. lang 7 desselben Werts."}
MultiLanguageSpellData['de'][443532] = {name = "In Dunkelheit gebunden", additional_info = "Sofort\n[q][ Blut : 'Siedendes Blut' fügt seinem Hauptziel 10% mehr Schaden /\n\nFrost\nDurch 'Raureif' ermächtigte 'Heulende Böen' fügt seinem Hauptziel 60% mehr Schaden ] zu und ist jetzt Schattenfrost.\n\n Schattenfrostschaden gewährt 2 Stapel für 'Mal des Schnitters' oder 4 Stapel bei kritischen Treffern."}
MultiLanguageSpellData['de'][443533] = {name = "Foliant der Hingabe des Lichts", additional_info = "[q]Ihr blättert zu den 50 Versen der inneren Abhärtung weiter und lest sie, während Ihr angegriffen werdet.\n 'Innere Abhärtung' erhöht Eure Rüstung um 136 und gewährt Euren Angriffen eine Chance, einen Schutz zu beschwören, der 3376 Magieschaden absorbiert. Sobald Ihr fertig seid, blättert Ihr zum nächsten Kapitel weiter.\n\nGilt nur für Tankspezialisierungen.\n(500ms Abklingzeit)"}
MultiLanguageSpellData['de'][443534] = {name = "Strahlen", additional_info = "Sofort\n[q]Ihr strahlt, was die Effizienz Eures Verses erhöht."}
MultiLanguageSpellData['de'][443535] = {name = "Foliant der Hingabe des Lichts", additional_info = "Sofort 1.5 min Abklingzeit\n[q]Blättert mit erhöhter Strahlung durch die Textstellen des Folianten."}
MultiLanguageSpellData['de'][443536] = {name = "Explodierender Lichtsplitter", additional_info = "35 Meter Reichweite\nSofort 2 min Abklingzeit\n[q]Beschwört eine berstende Lichtbrut, die ihre Gesundheit opfert, um Lichtstöße zu entfesseln, die 1446 Heiligschaden verursachen, der alle 2 Sekunden auf Gegner in der Nähe aufgeteilt wird, solange die Brut lebt."}
MultiLanguageSpellData['de'][443537] = {name = "Leerenpaktstein", additional_info = "Ca. 2 Procs pro Minute\n[q]Eure Angriffe haben eine Chance, den Pakt anzurufen und eine Explosion auszulösen, die ( 1 * 897 ) Schattenschaden verursacht, die auf Gegner in der Nähe aufgeteilt werden, und Euer Tempo 10 Sek. lang um 36 erhöht.\n\n Euer Tod beendet den Pakt und führt zu einer gewaltigen Explosion."}
MultiLanguageSpellData['de'][443538] = {name = "Ermächtigender Kristall von Anub'ikkaj", additional_info = "Ca. 1.55 Procs pro Minute\n[q]Eure Zauber und Fähigkeiten haben eine Chance, eine wachsende Ermächtigung aus dem Kristall freizusetzen, die einen zufälligen Sekundärwert 20 Sek. lang um 131 erhöht."}
MultiLanguageSpellData['de'][443539] = {name = "Mereldars Tribut", additional_info = "50 Meter Reichweite\nSofort\n[q]Entfesselt einen Tribut aus heiligem Licht auf das Ziel und fügt ihm ( 1 * 1368 ) Heiligschaden zu. Die nächsten 5 Verbündeten, die das Ziel angreifen, erhalten den 'Segen von Mereldar', was ihre Vielseitigkeit 10 Sek. lang um 62 erhöht."}
MultiLanguageSpellData['de'][443541] = {name = "Kokonbrut von Ara-Kara", additional_info = "Ca. 2.5 Procs pro Minute\n[q]Eure Fähigkeiten haben eine Chance, den Kokon zu bewegen, der ein Ei freigibt, das Eure Hauptwert um 15 erhöht. Jedes Ei schlüpft nach 1 Min. Die neue Brut greift Euer nächstes Ziel an und fügt ihm im Verlauf von 8 Sek. ( 1 * 80 * 8) Naturschaden zu.\n(100ms Abklingzeit)"}
MultiLanguageSpellData['de'][443544] = {name = "Aggressionsablenkungsmodul", additional_info = "[q]Eure Spottfähigkeiten aktivieren die brechende Energie des Moduls und schützen Euch vor 50% des erlittenen Schadens, bis zu 7648 . Dies kann nur einmal pro 1 Min. geschehen.\n\nGilt nur für Tankspezialisierungen.\n(1Min. Abklingzeit)"}
MultiLanguageSpellData['de'][443545] = {name = "Endlose Schwarmdrüse", additional_info = "Ca. 6 Procs pro Minute\n[q]Die Drüse setzt Pheromone frei, die einen endlosen Schwarm von Insekten anlocken, die Euch umkreisen. Wenn Ihr Schaden erleidet, habt Ihr eine hohe Chance auf einen Gegenschlag, der über 6 Sek. ( 69 * 6) Naturschaden verursacht und den Euch zugefügten Schaden um 96 reduziert."}
MultiLanguageSpellData['de'][443549] = {name = "Edikt des Ernters", additional_info = "100 Meter Reichweite\nSofort\n[q]Eure Schadenszauber und -fähigkeiten haben eine Chance, eine Kugel aus instabilem Schwarzblut auf Euer Ziel zuschweben zu lassen, die beim Aufprall explodiert und ( 1 * 1418 ) Schattenschaden verursacht, die zwischen allen Gegnern in der Nähe aufgeteilt werden. Wenn Ihr die Kugel abfangt, könnt Ihr deren Macht entziehen und damit Eure Meisterschaft 15 Sek. lang um 156 erhöhen."}
MultiLanguageSpellData['de'][443552] = {name = "Erdrückende Ansprache", additional_info = "Sofort 2 min Abklingzeit\n[q]Schwenkt den Kehlkopf in der Luft, um einen quälenden Chor zu entfesseln, der Gegnern in der Nähe im Verlauf von 3 Sek. ( 1 * 1480 * 3) Schattenschaden zufügt. Euer Flüstern schließt sich dem Chor an und erhöht den Schaden, bevor er verstummt."}
MultiLanguageSpellData['de'][443553] = {name = "Elchansturmrückstoß", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Stürmt auf das Ziel zu, rammt es und stößt es zurück."}
MultiLanguageSpellData['de'][443556] = {name = "Doppelfangbesteck", additional_info = "Sofort 2 min Abklingzeit\n[q]Öffnet den Beutel und zückt die Schattenklinge von Nx, um schnell auf Gegner vor Euch loszugehen und allen getroffenen Gegnern ( 1 * 585 ) Schattenschaden zuzufügen.\n\n Ihr könnt den Beutel bis zu zwei weitere Male innerhalb von 20 Sek. benutzen, bevor er sich selbst versiegelt und seinen Inhalt magisch auflädt."}
MultiLanguageSpellData['de'][443557] = {name = "Zähflüssiges Koaglam", additional_info = "[q]Eure überschüssige Heilung lockt Schattenenergie aus der Nähe zu Eurer Gruppe, die bis zu 213 Heilung speichert und die Gesundheit des Ziels wiederherstellt, wenn es Schaden erleidet."}
MultiLanguageSpellData['de'][443558] = {name = "Geronnene Membran", additional_info = "46 Meter Reichweite\nSofort 1 min Abklingzeit\n[q]Kanalisiert die Kraft des Koaglmats, indem die gesamte aktuelle Schattenenergie auf Euer Ziel konzentriert wird."}
MultiLanguageSpellData['de'][443559] = {name = "Rankendes Mixtorium", additional_info = "Ca. 2 Procs pro Minute\n[q]Eure Zaubersprüche können Euch dazu inspirieren, an einem Verbündeten zu experimentieren und ihn auf unvorhergesehene Weise 20 Sek. lang zu verbessern."}
MultiLanguageSpellData['de'][443560] = {name = "Schnell und qualvoll", additional_info = "[q]Blut\n Wenn 'Seeleneruption' keine Gegner trifft, erlangt Ihr für 8 Sek. 10% Stärke.\n\n 'Welle der Seelen' ist gegen das Hauptziel Eures 'Mal des Schnitters' 100% effektiver.\n\nFrost\n Wenn 'Seeleneruption' keine Gegner trifft, erlangt Ihr für 8 Sek. 5% Stärke.\n\n 'Welle der Seelen' ist gegen das Hauptziel Eures 'Mal des Schnitters' 50% effektiver."}
