MultiLanguageSpellData['de'][444052] = {name = "Nazgrims Feldzug", additional_info = "[q]Wenn ein Gegner stirbt, solange Nazgrim aktiv ist, wird die Stärke von 'Apokalyptische Eroberung' um 3% erhöht.\n\n Außerdem erhöht jede Rune, die Ihr verbraucht, den Wert um 1%."}
