MultiLanguageSpellData['de'][444621] = {name = "Schutz der Errettung", additional_info = "[q]Erlernt folgenden Zauber.\n\n Schutz der Errettung\nStellt bei einem Verbündeten Gesundheit wieder her und gewährt ihm 8 Sek. lang 'Schutz der Errettung'.\n\n Solange 'Schutz der Errettung' anhält, gewährt die durch den Zaubernden erhaltene Heilung zusätzlich Absorption.\n\n Wenn der Schutz abläuft, explodiert er und fügt allen Gegnern innerhalb von 40 Metern Heiligschaden in Höhe der verbleibenden Absorption zu, der gleichmäßig aufgeteilt wird."}
MultiLanguageSpellData['de'][444622] = {name = "Schutz der Errettung", additional_info = "40 Meter Reichweite\nSofort 3 min Abklingzeit\n[q]Stellt bei einem Verbündeten Gesundheit wieder her und gewährt ihm 8 Sek. lang 'Schutz der Errettung'.\n\n Solange 'Schutz der Errettung' anhält, gewährt die durch den Zaubernden erhaltene Heilung zusätzlich Absorption.\n\n Wenn der Schutz abläuft, explodiert er und fügt allen Gegnern innerhalb von 40 Metern Heiligschaden in Höhe der verbleibenden Absorption zu, der gleichmäßig aufgeteilt wird."}
MultiLanguageSpellData['de'][444623] = {name = "Symbiosis: Dummy Spell", additional_info = "Wirken in 3.5 sek.\nTools: Schreibzeug des Virtuosen\n[q]Erlittener Schaden hat eine Chance, Euch und einem verbündeten Gruppenmitglied falls möglich Y lang einen gemeinsamen Absorptionsschild in Höhe von X zu gewähren. Wenn der Schild abläuft, erhalten beide Spielercharaktere Y Sek. lang X Vielseitigkeit."}
MultiLanguageSpellData['de'][444627] = {name = "Vivacity: Dummy Spell", additional_info = "Wirken in 3.5 sek.\nTools: Schreibzeug des Virtuosen\n[q]Eure Zauber und Fähigkeiten haben eine Chance, Eurem Siegel ein Trommelfeuer der Lebhaftigkeit zu verleihen, das Euch hilft, wie es ihm beliebt.\n\n Bei Auslösungen durch Schaden\n\n Explodiert im Kampf gegen mehrere Ziele nach 10 Sek. und verursacht X Feuerschaden.\n\n Erhöht bei über 90% Gesundheit 15 Sek. lang den höchsten Sekundärwert um X.\n\n Heilt bei weniger als 30% Gesundheit um X Gesundheit.\n\n Richtet das Ziel hin, wenn es weniger als 20% Gesundheit hat und 'Hinrichten' möglich ist.\n\n Wenn nichts davon zutrifft, wird der niedrigste Sekundärwert um Y erhöht.\n\n Bei Auslösungen durch Heilung\n\n Heilt das Ziel um X Gesundheit, wenn es weniger als 50% Gesundheit hat.\n\n Erhöht 15 Sek. lang den als höchsten Sekundärwert um X, wenn das Ziel mehr als 90% Gesundheit hat.\n\n Gewährt X Mana, wenn Ihr weniger als 50% Mana habt.\n\n Wenn nichts davon zutrifft, wird der niedrigste Sekundärwert um Y erhöht."}
