MultiLanguageSpellData['de'][444766] = {name = "Überprüfen", additional_info = nil}
MultiLanguageSpellData['de'][444767] = {name = "Dominanz des Schlächters", additional_info = "Ca. 7 Procs pro Minute\n[q]Eure Angriffe auf Euer Primärziel haben eine hohe Chance, dessen Abwehr zu überwältigen und 'Schlächterschlag' auszulösen. Verursacht (333.5% der Angriffskraft) Schaden und belegt Ziele mit 'Zum Tode verurteilt', wodurch der körperliche Schaden, den sie durch Euren nächsten Einsatz von 'Hinrichten' erleiden, um 15% erhöht wird. 3-mal stapelbar."}
MultiLanguageSpellData['de'][444769] = {name = "Bevorstehendes Ableben", additional_info = "[q]Ihr erhaltet bei jedem 3. Einsatz von 'Schlächterschlag' 'Plötzlicher Tod'.\n\n Der Einsatz von 'Plötzlicher Tod' beschleunigt Euren nächsten 'Klingensturm', wodurch er einmal öfter trifft (bis zu 3). Die Gesamtdauer von 'Klingensturm' bleibt unverändert."}
MultiLanguageSpellData['de'][444770] = {name = "Todestrieb", additional_info = "[q]Ihr heilt um 15% des durch 'Plötzlicher Tod' verursachten Schadens."}
MultiLanguageSpellData['de'][444771] = {name = "Kein Erbarmen zeigen", additional_info = "[q]'Zum Tode verurteilt' erhöht die kritische Trefferchance und den kritischen Trefferschaden Eures nächsten Einsatzes von 'Hinrichten' gegen das Ziel um 15%."}
MultiLanguageSpellData['de'][444772] = {name = "Überwältigende Klingen", additional_info = "[q]Jeder Treffer von 'Klingensturm' belegt alle betroffenen Gegner mit 'Überwältigt' und erhöht den Schaden, den Ihr ihnen zufügt, 20 Sek. lang um 1 %, maximal 10 Stapel."}
MultiLanguageSpellData['de'][444773] = {name = "Grausame Konsequenz", additional_info = "[q]Furor\n Kritische Treffer mit 'Blutdurst' erhöhen den Schaden Eures nächsten Einsatzes von 'Blutdurst' um 20%.\n\nWaffen\n Kritische Treffer mit 'Tödlicher Stoß' erhöhen den Schaden Eures nächsten Einsatzes von 'Tödlicher Stoß' um 20%."}
MultiLanguageSpellData['de'][444774] = {name = "Opportunist", additional_info = "[q]Furor\n Wenn 'Wütender Schlag' seine eigene Abklingzeit abschließt, verursacht Euer nächster Einsatz von 'Wütender Schlag' 20% mehr Schaden und 20% mehr kritischen Schaden.\n\nWaffen\n Wenn die Abklingzeit von 'Überwältigen' durch 'Taktiker' abgeschlossen wird, verursacht Euer nächster Einsatz von 'Überwältigen' 25% mehr Schaden sowie 25% mehr kritischen Schaden."}
MultiLanguageSpellData['de'][444775] = {name = "Sturm ernten", additional_info = "[q]Furor\n 'Blutdurst' gewährt eine Chance von 20%, dass Ihr einen Wirbel aus Stahl entfesselt, der allen Gegnern in der Nähe (371.11% der Angriffskraft) körperlichen Schaden zufügt und sie mit 'Überwältigt' belegt. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu.\n\nWaffen\n Wenn 'Tödlicher Stoß' und 'Spalten' mindestens 3 Ziele treffen, gewähren sie eine Chance von 20%, dass Ihr einen Wirbel aus Stahl entfesselt, der allen Gegnern in der Nähe (371.11% der Angriffskraft) körperlichen Schaden zufügt und sie mit 'Überwältigt' belegt. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu.\n\n(Procchance: 20%, 500ms Abklingzeit)"}
MultiLanguageSpellData['de'][444776] = {name = "Unerbittliche Verfolgung", additional_info = "[q]'Sturmangriff' erhöht Eure Bewegungsgeschwindigkeit 3 Sek. lang um 70%.\n\n 'Sturmangriff' entfernt alle bewegungseinschränkenden Effekte. Dieser Effekt kann nur einmal alle 30 Sek. auftreten."}
MultiLanguageSpellData['de'][444777] = {name = "Boshafte Beweglichkeit", additional_info = "[q]'Heldenhafter Sprung' verringert die Abklingzeit von 'Sturmangriff' um 5 Sek. und 'Sturmangriff' verringert die Abklingzeit von 'Heldenhafter Sprung' um 2 Sek."}
MultiLanguageSpellData['de'][444778] = {name = "Ausmerzender Zyklon", additional_info = "[q]Jeder Treffer von 'Klingensturm' verursacht 10% zusätzlichen Schaden, der gleichmäßig auf alle Ziele aufgeteilt wird."}
MultiLanguageSpellData['de'][444779] = {name = "Bösartigkeit des Schlächters", additional_info = "[q]Furor\n Schaden von 'Wütender Schlag' um 30% erhöht.\n\nWaffen\n Schaden von 'Überwältigen' um 30% erhöht."}
MultiLanguageSpellData['de'][444780] = {name = "Unerbittlicher Ansturm", additional_info = "[q]Wenn Ihr ein Ziel mit 'Hinrichten' angreift, das Ihr 'Zum Tode verurteilt' habt, wird die Abklingzeit von 'Klingensturm' um 5 Sek. verringert und Ihr belegt das Ziel für jeden verbrauchten Stapel von 'Zum Tode verurteilt' mit 2 Stapeln von 'Überwältigt'.\n\n Ihr könnt 'Zuschlagen' und 'Sturmblitz' einsetzen, während 'Klingensturm' aktiv ist."}
MultiLanguageSpellData['de'][444784] = {name = "Geisterhaftes Bild", additional_info = "[q]Euer 'Spiegelbild' beschwört einen zusätzlichen Klon.\n 'Spiegelbild' verringert nun allen erlittenen Schaden zusätzlich um 5%."}
MultiLanguageSpellData['de'][444785] = {name = "Blutbarsch", additional_info = "Sofort\n[q]Ein kleiner Fisch mit blutroten Schuppen, der in Gewässern in ganz Khaz Algar vorkommt. Wenn er sich bedroht fühlt, stoßen seine Kiemen eine zähflüssige Tinte aus, die Blut sehr ähnlich sieht.\n\nBesondere Verwendung:\n\n Blutiger Köder\n\n Wenn Ihr diesen Fisch zurück in die Gewässer von Khaz Algar werft, kann dieser Mechanismus aktiviert werden. Dabei werdet Ihr mit Pheromonen bedeckt, die beim Fangen des scheuen blutroten Dornhais helfen.\n\nVerbreitungsgebiete:\n\n - Insel von Dorn\n - Schallende Tiefen\n - Heilsturz\n - Sireneninsel\n - K'aresh-Oase\n\nFischschwärme:\n\n - Slumhaischwarm\n - Blut im Wasser\n - Schwärender Fäulnisteich\n - Blutbarschschwarm\n - Ruhige Oberflächenwellen\nBeruf:\nAngeln"}
MultiLanguageSpellData['de'][444786] = {name = "Kristalliner Stör", additional_info = "5 Meter Reichweite\nSofort\n[q]Mit seinem schlanken, länglichen Körper gleitet der Fisch mühelos durch die Gewässer von Khaz Algar. Im Vergleich zu seiner verwandten Art, dem Bismutbitterling, ist dieser urzeitliche Fisch deutlich größer. Er folgt aber gern Schwärmen seines kleineren Cousins, um die Nährstoffe aufzunehmen, die die Fische verlieren.\n\nBesondere Verwendung:\n\n Wahrnehmung\n\n Werft diesen Fisch zurück ins Wasser, um Eure Wahrnehmung von Khaz Algar zu erhöhen.\n\nVerbreitungsgebiete:\n\n - Insel von Dorn\n - Schallende Tiefen\n - Sireneninsel\n\nFischschwärme:\n\n - Glimmerbecken\nBeruf:\nAngeln"}
MultiLanguageSpellData['de'][444787] = {name = "Bismutbitterling", additional_info = "5 Meter Reichweite\nWirken in 3.2 sek.\n[q]Der kleine Fisch mit seinem fratzenhaften Ausdruck hat harte äußere Schuppen, die an Bismut erinnern. Diese Schuppen nehmen Mineralien und andere Schwebeteilchen auf und transportieren sie durch die Gewässer von Khaz Algar. Ein gewöhnlicher Fisch, der jedoch sehr wichtig für das Gedeihen der örtlichen Flora ist.\n\nBesondere Verwendung:\n\n Köder\n\n Werft diesen Fisch zurück ins Wasser, um Eure Angelfertigkeit zu erhöhen.\n\nVerbreitungsgebiete:\n\n - Insel von Dorn\n - Schallende Tiefen\n - Sireneninsel\n\nFischschwärme:\n\n - Glimmerbecken\nBeruf:\nAngeln"}
MultiLanguageSpellData['de'][444788] = {name = "Knabberelritze", additional_info = "5 Meter Reichweite\nWirken in 3.2 sek.\n[q]Eine unscheinbare Elritze, die unerfahrene Angler womöglich als wertlos erachten. Gerüchteweise versammelt sich der Fisch aber um besonders glänzende Gegenstände und knabbert am Schmutz, den sie ansetzen.\n\nBesondere Verwendung:\n\n Wahrnehmung\n\n Werft diesen Fisch zurück ins Wasser, um Eure Wahrnehmung von Khaz Algar zu erhöhen.\n\nVerbreitungsgebiete:\n\n - Insel von Dorn\n - Schallende Tiefen\n - Heilsturz\n - Azj-Kahet\n - Sireneninsel\n -Lorenhall\n - K'aresh-Oase\n\nFischschwärme:\n\n - Ruhige Oberflächenwellen\nBeruf:\nAngeln"}
MultiLanguageSpellData['de'][444789] = {name = "Flüsternder Sterngucker", additional_info = "5 Meter Reichweite\nWirken in 3.2 sek.\n[q]Der Fisch tritt in dichten Schwärmen auf und hat seinen Namen durch seine tintenschwarzen Schuppen erhalten, die aneinander reiben und vibrieren. Diese Vibrationen schrecken Räuber ab und sind so laut, dass man sie selbst über Wasser hören kann.\n\nBesondere Verwendung:\n\n Geflüster der Tiefe\n\n Setzt den flüsternden Sterngucker ein, um schlummernde Quastenflosser aus den Tiefen Azj-Kahets hervorzulocken.\n\nVerbreitungsgebiete:\n\n - Insel von Dorn\n - Schallende Tiefen\n - Heilsturz\n - Sireneninsel\n - K'aresh-Oase\n\nFischschwärme:\n\n - Sternguckerschwarm\nBeruf:\nAngeln"}
MultiLanguageSpellData['de'][444790] = {name = "Goldkiemenforelle", additional_info = "5 Meter Reichweite\nWirken in 3.2 sek.\n[q]Die Risse in seinen Kiemen schimmern leuchtend golden. Angler erzählen sich, dass der Fisch Glück, Wohlstand und ruhige See bringt.\n\nBesondere Verwendung:\n\n Wahrnehmung\n\n Diesen Fisch zu fangen, erhöht Eure Wahrnehmung von Khaz Algar.\n\nVerbreitungsgebiete:\n\n - Insel von Dorn\n - Schallende Tiefen\n - Heilsturz\n - Azj-Kahet\n - Sireneninsel\n - Lorenhall\n - K'aresh-Oase\n\nFischschwärme:\n\n - Glimmerbecken\n - Schwärender Fäulnisteich\n - Energieerfüllter Sekretfleck\nBeruf:\nAngeln"}
MultiLanguageSpellData['de'][444791] = {name = "Spiegelregenbogenfisch", additional_info = "5 Meter Reichweite\nWirken in 3.2 sek.\n[q]Das mehrfarbige Blut, das unter seinen durchscheinenden Schuppen fließt, verleiht diesem Fisch sein regenbogenartiges Aussehen. Neben dem kulinarischen Wert das Fleischs von Regenbogenfischen ist deren Blut auch fast identisch mit dem Perlmuttpigment, das Schreiber verwenden.\n\nBesondere Verwendung:\n\n Frisches Filet\n\n Die Verwertung dieses Fisches mit der Kochfertigkeit kann frisches Filet ergeben.\n\nVerbreitungsgebiete:\n\n - Insel von Dorn\n - Schallende Tiefen\n - Sireneninsel\n - K'aresh-Oase\n\nFischschwärme:\n\n - Glimmerbecken\nBeruf:\nAngeln"}
MultiLanguageSpellData['de'][444792] = {name = "Trödelnder Häsling", additional_info = "5 Meter Reichweite\nWirken in 3.2 sek.\n[q]Ein frecher Fisch, der durch Khaz Algar saust. Er wird oft mit einer Knabberelritze oder einem majestätischen Zwergbarsch verwechselt und findet sich dank seiner Geschwindigkeit und Größe oft an Orten wieder, an denen er nichts verloren hat.\n\nBesondere Verwendung:\n\n Köder\n\n Werft den Fisch zurück ins Wasser, um Eure Angelfertigkeit zu erhöhen.\n\nVerbreitungsgebiete:\n\n - Insel von Dorn\n - Schallende Tiefen\n - Heilsturz\n - Sireneninsel\n - K'aresh-Oase\n\nFischschwärme:\n\n - Ruhige Oberflächenwellen\n - Blut im Wasser\n - Schwärender Fäulnisteich\nBeruf:\nAngeln"}
MultiLanguageSpellData['de'][444793] = {name = "Dornischer Hecht", additional_info = "5 Meter Reichweite\nWirken in 3.2 sek.\n[q]Eine unscheinbare Kreatur, die sich mit ihrem gepunkteten Aussehen tarnt, um Angriffe von oben zu vermeiden, während sie auf kleinere Fische unten lauert. Mit dem großen, fleischigen Körper macht sie Jagd auf kristalline Störe, ist aber auch eine hervorragende Quelle für frisches Filet.\n\nBesondere Verwendung:\n\n Frisches Filet\n\n Die Verwertung dieses Fisches mit der Kochfertigkeit kann frisches Filet ergeben.\n\nVerbreitungsgebiete:\n\n - Insel von Dorn\n - Schallende Tiefen\n - Heilsturz\n - Sireneninsel\n\nFischschwärme:\n\n - Ruhige Oberflächenwellen\nBeruf:\nAngeln"}
MultiLanguageSpellData['de'][444794] = {name = "Tosender Anglersucher", additional_info = "5 Meter Reichweite\nWirken in 3.2 sek.\n[q]Ein aggressiver Fisch, der sich gern dort versammelt, wo Angler sind. Wenn er mit seiner kraftvollen Schwanzflosse und seinem muskulösen Leib durch die Wellen stößt, erzeugt er ein hörbares Rauschen.\n\nBesondere Verwendung:\n\n Frisches Filet\n\n Die Verwertung dieses Fisches mit der Kochfertigkeit kann frisches Filet ergeben.\n\nVerbreitungsgebiete:\n\n - Insel von Dorn\n - Schallende Tiefen\n - Heilsturz\n - Azj-Kahet\n - Sireneninsel\n\nFischschwärme:\n\n - Anglersucherstrom\nBeruf:\nAngeln"}
MultiLanguageSpellData['de'][444795] = {name = "Arathorhammerfisch", additional_info = "5 Meter Reichweite\nWirken in 3.2 sek.\n[q]Die Krone am Kopf dient als ernstzunehmende Waffe, wenn er mit seinen riesigen Flossen nach vorn stößt. Mit Schuppen, die fast im Farbton der Arathi schimmern, ist es kein Wunder, dass der muskulöse Fisch diesen Namen trägt.\n\nBesondere Verwendung:\n\n Holzhammermethode\n\nSchlägt Euren Gegner mit dem Hammerfisch und betäubt ihn für 1 Sek. Nur im Freien in Khaz Algar einsetzbar.\n\nVerbreitungsgebiete:\n\n - Heilsturz\n\nFischschwärme:\n\n - Blut im Wasser\nBeruf:\nAngeln"}
MultiLanguageSpellData['de'][444796] = {name = "Majestätischer Zwergbarsch", additional_info = "5 Meter Reichweite\nWirken in 3.2 sek.\n[q]Dunkelrote und magentafarbene Streifen zieren den kleinen, aber kraftvollen Leib. Dieser besonders seltene Fisch am königlichen Hof schützt die Gewässer um Königinnenköderfische aggressiv vor Arten wie dem verderbten Geisterfisch.\n\nBesondere Verwendung:\n\n Königsköder\n\n Wehrt verderbte Geisterfische ab und sorgt für sichere Gewässer für Königinnenköderfische.\n\nVerbreitungsgebiete:\n\n - Heilsturz\n - Azj-Kahet\n\nFischschwärme:\n\n - Königliche Welle\nBeruf:\nAngeln"}
MultiLanguageSpellData['de'][444797] = {name = "Slumhai der Kaheti", additional_info = "5 Meter Reichweite\nWirken in 3.2 sek.\n[q]In den Tiefen Azj-Kahets gleitet diese Kreatur über den Boden, ihre Silhouette kaum von den finsteren Tiefen zu unterscheiden. Dieses berechnende Raubtier lässt selbst erfahrene Angler von Glück reden.\n\nBesondere Verwendung:\n\n Frisches Filet\n\n Die Verwertung dieses Fisches mit der Kochfertigkeit kann eine große Menge frisches Filet ergeben.\n\nVerbreitungsgebiete:\n\n - Heilsturz\n - Azj-Kahet\n\nFischschwärme:\n\n - Blut im Wasser\n - Schwarm Slumhaie\nBeruf:\nAngeln"}
MultiLanguageSpellData['de'][444798] = {name = "Blasser Hüllenfisch", additional_info = "5 Meter Reichweite\nWirken in 3.2 sek.\n[q]Dieser große Fisch wird oft mit einem verderbten Geisterfisch verwechselt, ist aber der beste Freund jedes Anglers. Angezogen von Mineralien am Grund von Gewässern neigt der blasse Hüllenfisch dazu, eingebettete Kleintiere zu verschlingen.\n\nBesondere Verwendung:\n\n Hüllenfischmagen\n\n Weidet den Fisch aus in Hoffnung auf Schätze.\n\nVerbreitungsgebiete:\n\n - Azj-Kahet\n -Lorenhall\n\nFischschwärme:\n\n - Energieerfüllter Sekretfleck\n - Schwärender Fäulnisteich\nBeruf:\nAngeln"}
MultiLanguageSpellData['de'][444799] = {name = "Blutroter Dornhai", additional_info = "5 Meter Reichweite\nWirken in 3.2 sek.\n[q]Der blutrote Dornhai ist ein Meister des Hinterhalts und verfolgt kleinere Fische geduldig, bevor er seine karmesinroten Flossen für einen Geschwindigkeitsschub in Position bringt. Dieser große, scheue Fisch wird vor allem von Blutbarschschwärmen angezogen.\n\nBesondere Verwendung:\n\n Frisches Filet\n\n Die Verwertung dieses Fisches mit der Kochfertigkeit kann eine große Menge frisches Filet ergeben.\n\nVerbreitungsgebiete:\n\n - Insel von Dorn\n - Schallende Tiefen\n - Heilsturz\n - Azj-Kahet\n - Sireneninsel\n - K'aresh-Oase\n\nFischschwärme:\n\n - Blutbarschschwarm\n - Blut im Wasser\nBeruf:\nAngeln"}
MultiLanguageSpellData['de'][444800] = {name = "Stacheliger Seerabe", additional_info = "5 Meter Reichweite\nWirken in 3.2 sek.\n[q]Sein Körper ist mit scharfen Spitzen übersät, die in alle Richtungen zeigen und ihn in eine furchterregende Rüstung kleiden. Diese Spitzen dienen sowohl dem Schutz als auch der Tarnung auf dem steinigen Meeresboden, auf dem er sich oft aufhält. Trotz seines formidablen Äußeren bewegt er sich überraschend anmutig und schwimmt mühelos durch Unterwasserspalten und -höhlen.\n\nBesondere Verwendung:\n\n Frisches Filet\n\n Die Verwertung dieses Fisches mit der Kochfertigkeit kann eine große Menge frisches Filet ergeben.\n\nVerbreitungsgebiete:\n\n - Insel von Dorn\n - Heilsturz\n - Sireneninsel\n\nFischschwärme:\n\n - Ruhige Oberflächenwellen\n - Glimmerbecken\n - Sternguckerschwarm\n - Anglersucherstrom\nBeruf:\nAngeln"}
MultiLanguageSpellData['de'][444801] = {name = "Königinnenköderfisch", additional_info = "5 Meter Reichweite\nWirken in 3.2 sek.\n[q]Sein langgezogener Körper ist mit farbenfroh schimmernden, schillernden Schuppen geschmückt. Eine biolumineszente Angel hängt von seiner Stirn wie ein glühender Edelstein. Dieser Fisch gleitet anmutig durch die tintenschwarzen Tiefen von Khaz Algar und gedeiht dank seiner scharfen Sinne in der Dunkelheit.\n\nBesondere Verwendung:\n\n Frisches Filet\n\n Die Verwertung dieses Fisches mit der Kochfertigkeit kann eine große Menge frisches Filet ergeben.\n\nVerbreitungsgebiete:\n\n - Heilsturz\n - Azj-Kahet\n\nFischschwärme:\n\n - Königliche Welle\nBeruf:\nAngeln"}
MultiLanguageSpellData['de'][444802] = {name = "Verfluchter Geisterfisch", additional_info = "5 Meter Reichweite\nSofort\n[q]Vom Blut der Alten Götter verzerrt, spannt sich seine kränkliche, blasse Haut über seinen skelettartigen Körper. Angler in ganz Khaz Algar bezeichnen diesen Fisch als einen Boten der Verdammnis, der jeden Angler verflucht, der das Pech hat, ihn an Land zu ziehen. Wenn man dieser Kreatur in die Augen schaut, wird ihre Verdorbenheit nur noch umfassender, denn jedes Spiegelbild wird vom Abgrund verschlungen.\n\nDas Fangen dieses Fisches bewirkt:\n\n Geisterfischfluch\n\n Aber noch besteht Hoffnung. Angler mögen den verfluchten Geisterfisch meiden, doch für Köche ist er eine Gelegenheit. Die Verwertung dieses Fisches könnte Eurem Magen und Eurer Angelfertigkeit zum Vorteil gereichen.\n\nVerbreitungsgebiete:\n\n - Überall da, wo ein übermütiger Algarischer Angler seine Angel auswerfen kann.\n\nFischschwärme:\n\n - Alle Schwärme.\nBeruf:\nAngeln"}
MultiLanguageSpellData['de'][444803] = {name = "Erwachter Quastenflosser", additional_info = "5 Meter Reichweite\nSofort\n[q]Eine einfache, schlummernde Kreatur. Wenn sie erwacht, schimmern ihre Schuppen in allen Farben des Regenbogens und reflektieren jeden noch so kleinen Lichtstrahl. Eine ruhige Erhabenheit und ein treffliches Ziel für jeden aufstrebenden Angler.\n\nBesondere Verwendung:\n\n Frisches Filet\n\n Die Verwertung dieses Fisches mit der Kochfertigkeit kann eine große Menge frisches Filet ergeben.\n\nVerbreitungsgebiete:\n\n - Azj-Kahet\n - K'aresh-Oase\nBeruf:\nAngeln"}
MultiLanguageSpellData['de'][444806] = {name = "Wut der Aldrachi", additional_info = "Sofort\n[q]Das Verbrauchen von [ Verwüstung : 6 /\n\nRachsucht\n20 ] Seelenfragmenten oder das Einsetzen von 'Die Jagd' verwandelt Euren nächsten Einsatz von 'Gleve werfen' in 'Gleve des Reißers'.\n\n Gleve des Reißers :\nWirft eine mit der Essenz verschlungener Seelen verstärkte Gleve auf Euer Ziel. Diese verursacht (345% der Angriffskraft) körperlichen Schaden und prallt auf bis zu 2 weitere Gegner ab.\n\n Beginnt ein einstudiertes Muster der Glevenkunst, was Euren nächsten Einsatz von [ Verwüstung : 'Chaosstoß' / Fraktur : 'Fraktur' / 'Abscheren' ] und [ Verwüstung : 'Klingentanz' /\n\nRachsucht\n'Seelenspalter' ] verstärkt.\n\n Die verstärkte Fähigkeit, die Ihr als Erstes einsetzt, verursacht 10% mehr Schaden, die zweite 20% mehr Schaden."}
