MultiLanguageSpellData['de'][444827] = {name = "Reaktive Barriere", additional_info = "[q]Frost\n Eure 'Eisbarriere' kann je nach Eurer fehlenden Gesundheit bis 50% mehr Schaden absorbieren.\n\n Max. Effektivität, wenn die Gesundheit weniger als 50% beträgt.\n\nArkan\n Eure 'Prismatische Barriere' kann je nach Eurer fehlenden Gesundheit bis 50% mehr Schaden absorbieren.\n\n Max. Effektivität, wenn die Gesundheit weniger als 50% beträgt."}
