MultiLanguageSpellData['de'][444829] = {name = "Beschwörungen der Königin", additional_info = "Wirken in 3 sek.\n[q]Ansurek stößt einen schaurigen Schrei aus, der allen Spielercharakteren 2878158 Schattenschaden zufügt und beschworene Akolythen zu Hilfe ruft.\n\n Nach ihrem Tod werden sie zu ' Akolythenessenz '."}
