MultiLanguageSpellData['de'][445016] = {name = "Spektralschmetterschlag", additional_info = "300 Meter Reichweite\nWirken in 3 sek.\n[q]Der verlorene Wächter schlägt auf sein aktuelles Ziel ein und fügt ihm 6907579 körperlichen Schaden zu."}
MultiLanguageSpellData['de'][445017] = {name = "Gieriger Hunger", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Schleudert einen kyrianischen Speer an den Zielort, der sofort (110% der Angriffskraft) Arkanschaden und im Verlauf von 4 Sek. zusätzlich (120% der Angriffskraft) Schaden verursacht. Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu.\n\n Getroffene Gegner werden für die Dauer an die Position des Speers der Bastion gebunden.\n\nErzeugt 25 Wut."}
