MultiLanguageSpellData['de'][445021] = {name = "Nulldetonation", additional_info = "Wirken in 4 sek.\n[q]Der beschworene Akolyth fügt allen Spielercharakteren 690758 Schattenschaden zu. Jeder erfolgreiche Einsatz erhöht diesen verursachten Schaden um 100%."}
MultiLanguageSpellData['de'][445024] = {name = "Wirbelnde Elemente", additional_info = "[q]Verstärkung\n Elementare Partikel schweben um Euer Wogendes Totem herum. Eure Fähigkeiten verbrauchen die Partikel für verstärkte Effekte.\n\nLuft: [ Verstärkung : Euer nächster Einsatz von 'Blitzschlag', 'Kettenblitzschlag' oder 'Elementarschlag' entfesselt 3 'Wogende Blitze' auf Euer 'Wogendes Totem' /\n\nElementar, Wiederherstellung\nDie Zauberzeit Eures nächsten Heilzaubers ist um 40% verringert ]\nErde: [ Verstärkung : Euer nächster 'Flammenschock' verursacht 300% mehr direkten Schaden und trifft 5 Gegner in der Nähe /\n\nElementar, Wiederherstellung\nEure nächste 'Kettenheilung' gewährt allen getroffenen Zielen 'Lebensgeister' mit 150% Effektivität ]\nFeuer: Eure nächste 'Lavapeitsche' oder 'Feuernova' gewährt Euch 6 Sek. lang 'Heiße Hand'.\n\nWiederherstellung\n Elementare Partikel schweben um Euer Wogendes Totem herum. Eure Fähigkeiten verbrauchen die Partikel für verstärkte Effekte.\n\nWasser: Euer nächster Einsatz von 'Welle der Heilung' oder 'Heilende Woge' heilt zusätzlich einen Verbündeten im Effektbereich Eures Zaubers 'Heilender Regen' mit einer Effektivität von 100%.\n\nLuft: [ Verstärkung : Euer nächster Einsatz von 'Blitzschlag', 'Kettenblitzschlag' oder 'Elementarschlag' entfesselt 3 'Wogende Blitze' auf Euer 'Wogendes Totem' /\n\nElementar, Wiederherstellung\nDie Zauberzeit Eures nächsten Heilzaubers ist um 40% verringert ]\nErde: [ Verstärkung : Euer nächster 'Flammenschock' verursacht 300% mehr direkten Schaden und trifft 5 Gegner in der Nähe /\n\nElementar, Wiederherstellung\nEure nächste 'Kettenheilung' gewährt allen getroffenen Zielen 'Lebensgeister' mit 150% Effektivität ]"}
MultiLanguageSpellData['de'][445025] = {name = "Totemischer Abpraller", additional_info = "Ca. 10 Procs pro Minute\n[q]Verstärkung\n 'Blitzschlag', 'Kettenblitzschlag' und 'Elementarschlag' haben eine Chance, 'Wogender Blitz' auf Euer Wogendes Totem zu werfen, was den Schaden des Totems um 10% erhöht und den Blitz dann auf Euer Ziel weiterleitet, wo er (92% der Angriffskraft) Naturschaden verursacht. Der Schadensbonuseffekt ist stapelbar.\n\nWiederherstellung\n 'Kettenheilung' springt jetzt auf ein Totem innerhalb von 20 Metern über, sobald das letzte Ziel erreicht wurde, wodurch das Totem 'Kettenheilung' auf einen verletzten Verbündeten innerhalb von 30 Metern wirkt und diesen um (150% der Zaubermacht) Gesundheit heilt. Springt auf bis zu 2 Ziele innerhalb von 20 Metern über."}
MultiLanguageSpellData['de'][445026] = {name = "Übergroße Totems", additional_info = "[q]Erhöht die Größe und den Radius Eurer Totems um 15% und deren Heilung um 30%."}
MultiLanguageSpellData['de'][445027] = {name = "Rascher Rückruf", additional_info = "[q]Das erfolgreiche Entfernen eines schädlichen Effekts durch Euer Totem des Erdstoßes oder Totem der Giftreinigung oder das Kontrollieren eines Gegners durch Euer Totem der Energiespeicherung oder Totem des Erdgriffs verringert die Abklingzeit des verwendeten Totems um 5 Sek.\n\n Kann pro Totem nicht öfter als einmal alle 20 Sek. auftreten."}
MultiLanguageSpellData['de'][445028] = {name = "Verzauberungsmeisterschaft", additional_info = "[q]Verstärkung\n Erhöht die Chance, dass die 'Windzornwaffe' ausgelöst wird, um 5%, und erhöht ihren Schaden um 8%.\n\n Wenn Angriffe mit der 'Windzornwaffe' die 'Waffe der Flammenzunge' auslösen, hat sie eine Chance, einen Flammenwirbel um das Ziel herum zu beschwören, der allen Gegnern in der Nähe 300% ihres Schadens zufügt.\n\nWiederherstellung\n Erhöht die Dauer Eures Effekts 'Lebensgeister' um 3 Sek."}
MultiLanguageSpellData['de'][445029] = {name = "Verstärkungskern", additional_info = "[q]Während Euer Wogendes Totem aktiv ist, sind Euer verursachter Schaden und Heilung um 3% erhöht."}
MultiLanguageSpellData['de'][445030] = {name = "Überwoge", additional_info = "[q]Wiederherstellung\n Während 'Aszendenz' verursacht Euer Wogendes Totem 50% mehr Schaden .\n\nVerstärkung\n Während 'Aszendenz' verursacht Euer Wogendes Totem 50% mehr Schaden."}
MultiLanguageSpellData['de'][445031] = {name = "Windbarriere", additional_info = "[q]Wenn Ihr ein aktives Totem habt, gewähren Eure Totems Euch 30 Sek. lang alle 30 Sek. einen Schild, der (Gesamtgesundheit * 6 / 100) Schaden absorbiert."}
MultiLanguageSpellData['de'][445032] = {name = "Impulskondensator", additional_info = "[q]Verstärkung\n Erhöht den Schaden von des Wogenden Totems um 18%.\n\nWiederherstellung\n Erhöht die durch Wogendes Totem verursachte Heilung um 25%."}
MultiLanguageSpellData['de'][445033] = {name = "Unterstützende Verzauberungen", additional_info = "[q]Verstärkung\n Erhöht die kritische Trefferchance von 'Waffe der Flammenzunge' um 25% und den kritischen Trefferschaden um 100%.\n\nWiederherstellung\n Lernt eine neue Waffenverzauberung: 'Wache des Gezeitenrufers'.\n\n Wache des Gezeitenrufers\nErfüllt Euren Schild 1 Stunde lang mit dem Element des Wassers. Erhöht Eure hervorgerufene Heilung um 2.0% und die Dauer Eures Totems des heilenden Flusses und Totems des Wolkenbruchs um 3.0 Sek."}
MultiLanguageSpellData['de'][445034] = {name = "Lebhafte Totems", additional_info = "[q]Verstärkung\n 'Lavapeitsche' hat eine Chance, ein Totem der Verbrennung zu beschwören, das 'Sengende Blitze' schleudert, die Gegnern in der Nähe (65.205% der Zaubermacht) Feuerschaden zufügen. Hält 8 Sek. lang an.\n\n 'Frostschocks', die durch 'Hagelsturm', 'Lavapeitsche' oder 'Feuernova' ermächtigt wurden, lassen Eure 'Totems der Verbrennung' eine 'Verbrennende Salve' auf bis zu 5 Gegner in der Nähe schleudern, die (92.736% der Zaubermacht) Feuerschaden verursacht.\n\nWiederherstellung\n Wenn Ihr ein 'Totem der Heilungsflut', 'Totem des heilenden Flusses', 'Totem des Wolkenbruchs', oder 'Totem der Geistverbindung' beschwört, zaubert Ihr einen kostenlosen Spontanzauber von 'Kettenheilung' mit 100% Effektivität."}
MultiLanguageSpellData['de'][445035] = {name = "Reaktivität", additional_info = "[q]Wiederherstellung\n Eure 'Totems des heilenden Flusses' heilen jetzt auch einen zweiten Verbündeten mit 100% Effektivität.\n\n 'Totem des Wolkenbruchs' speichert 25% zusätzliche Heilung.\n\nVerstärkung\n Während 'Heiße Hand' aktiv ist, lässt 'Lavapeitsche' die Erde aufreißen und verursacht eine 'Zerschlagung' mit 50% Effektivität.\n\n Die 'Zerschlagung' aus diesem Effekt verursacht keine Handlungsunfähigkeit."}
MultiLanguageSpellData['de'][445036] = {name = "Totemische Koordination", additional_info = "[q]Wiederherstellung\n 'Kettenheilung' von 'Lebendiges Totem' und 'Totemischer Abpraller' ist 25% effektiver.\n\nVerstärkung\n Erhöht die kritische Trefferchance der Angriffe Eures Totems der Verbrennung um 15% und den kritischen Trefferschaden um 30%."}
