MultiLanguageSpellData['de'][445323] = {name = "[q4]Runenverzierte Nullsteinrute", additional_info = "Wirken in 3.5 sek. 2\nTools: Runenverzierte Verzauberkunstrute\nReagenzien:\nHändchen fürs Kunsthandwerk (400), Barren der Schallenden Tiefen (2), Nullstein , Sturmstaub (100), Schimmernder Splitter (10)\nOptionale Reagenzien:\nHerstellungswerte anpassen (#345) , Verzauberungen und Ausrüstung (#378) , Authentizität des Kunsthandwerks (#354)\nVerkäufer:\nLyrendal\nZone:\nDornogal\nKosten:\n150\n\n[q4]Runenverzierte Nullsteinrute\nWird beim Aufheben gebunden\nWerkzeug für Verzauberkunst\n[q2]+ 125 Zufallswert 1\n[q2]Anlegen: +18 Fertigkeit in Verzauberkunst von Khaz Algar\n[q2]Anlegen: Ihr braucht 1% weniger Konzentration bei Verzauberkunstformeln von Khaz Algar.\n68\n[q]\"Dient als runenverzierte Verzauberkunstrute.\""}
MultiLanguageSpellData['de'][445324] = {name = "[q3]Verzauberter Speerholzzauberstab", additional_info = "Wirken in 3.5 sek. 3\nTools: Runenverzierte Verzauberkunstrute\nReagenzien:\nSturmstaub (5), Kodifiziertes Grünholz\nOptionale Reagenzien:\nErmächtigen (#342) , Verzierung hinzufügen (#341) , Sekundärwerte anpassen (#365) , Verzauberungen und Ausrüstung (#378) , Authentizität des Kunsthandwerks (#354)\nBerufsausbilder:\nVerzauberkunst von Khaz Algar (40)\nKosten:\n150\n\n[q3]Verzauberter Speerholzzauberstab\nWird beim Anlegen gebunden\nDistanz Zauberstab\n270 - 451 Schattenschaden Geschwindigkeit 2.00\n(180.3 Schaden pro Sekunde)\n+1.847 Intelligenz\n+1.162 Ausdauer\n[q2]+ 222 Zufallswert 1\n[q2]+ 222 Zufallswert 2\nHaltbarkeit 90 / 90\n72"}
MultiLanguageSpellData['de'][445347] = {name = "[q4]Verzaubertes runenverziertes Heroldswappen", additional_info = "Wirken in 3.5 sek. 2\nTools: Runenverzierte Verzauberkunstrute\nReagenzien:\nAufkommendes runenverziertes Vorbotenwappen , Sturmstaub (60), Schimmernder Splitter (10), Glänzender Kristall\nBeute von:\nAbenteuer in Khaz Algar\n\n[q4]Verzaubertes runenverziertes Vorbotenwappen\nWird beim Aufheben gebunden\nOptionales Handwerksmaterial\n[q2]+10 Rezeptschwierigkeit\n[q]Benutzbar mit: Rezepte aus Khaz Algar für epische Ausrüstungsteile, die mit einem Funken der Omen hergestellt werden.\n[q]\"Ein mächtiges Reagenz, das von Verzauberern erschaffen wurde.\""}
MultiLanguageSpellData['de'][445354] = {name = "[q4]Verzaubertes vergoldetes Heroldswappen", additional_info = "Wirken in 3.5 sek. 3\nTools: Runenverzierte Verzauberkunstrute\nReagenzien:\nAufkommendes vergoldetes Vorbotenwappen , Sturmstaub (100), Schimmernder Splitter (15), Glänzender Kristall (2)\nBeute von:\nAbenteuer in Khaz Algar\n\n[q4]Verzaubertes vergoldetes Vorbotenwappen\nWird beim Aufheben gebunden\nOptionales Handwerksmaterial\n[q2]+20 Rezeptschwierigkeit\n[q]Benutzbar mit: Rezepte aus Khaz Algar für epische Ausrüstungsteile, die mit einem Funken der Omen hergestellt werden.\n[q]\"Ein mächtiges Reagenz, das von Verzauberern erschaffen wurde.\""}
MultiLanguageSpellData['de'][445355] = {name = "[q4]Szepter der strahlenden Magie", additional_info = "Wirken in 3.5 sek. 3\nTools: Runenverzierte Verzauberkunstrute\nReagenzien:\nEntweihter Zunderkasten (2), Schimmernder Splitter (6), Glänzender Kristall (2), Kodifiziertes Grünholz , Funke (#256)\nOptionale Reagenzien:\nMit Energie erfüllen (#366) , Verzierung hinzufügen (#341) , Sekundärwerte anpassen (#365) , Verzauberungen und Ausrüstung (#378) , Authentizität des Kunsthandwerks (#354) , Weiter Augmentieren (#384)\nSpezialisierung:\nEphemeren, Anreicherung und Ausrüstung - Schlachthandwerk\n\n[q4]Szepter der strahlenden Magie\nWird beim Aufheben gebunden\nDistanz Zauberstab\n907 - 1,513 Feuerschaden Geschwindigkeit 2.00\n(605.0 Schaden pro Sekunde)\n+6.201 Intelligenz\n+4.874 Ausdauer\n[q2]+ 364 Zufallswert 1\n[q2]+ 364 Zufallswert 2\nHaltbarkeit 110 / 110\n70"}
