MultiLanguageSpellData['de'][445465] = {name = "Welken", additional_info = "[q]Gebrechen\nBelegt das Ziel mit einer abscheulichen Verwünschung, die seine Sehnen und Muskeln verbrennt und ihm sofort (19.8375% der Zaubermacht) Schattenflammenschaden sowie im Verlauf von 18 Sek. (296.544% der Zaubermacht) zusätzlichen Schattenflammenschaden zufügt.\n\nErsetzt 'Verderbnis'.\n\nZerstörung\nBelegt das Ziel mit einer abscheulichen Verwünschung, die seine Sehnen und Muskeln verbrennt und ihm sofort (19.8375% der Zaubermacht) Schattenflammenschaden sowie im Verlauf von 18 Sek. (296.544% der Zaubermacht) zusätzlichen Schattenflammenschaden zufügt.\n\nRegelmäßiger Schaden erzeugt ein Seelensplitterfragment und hat eine Chance von 50%, bei kritischen Treffern ein zusätzliches zu erzeugen.\n\n Ersetzt 'Feuerbrand'."}
MultiLanguageSpellData['de'][445466] = {name = "Essenz zertrümmern", additional_info = "Wirken in 1.5 sek.\n[q]Zerschmettert eine magische Essenz von Khaz Algar, um die Macht im Innern für Eure Verzauberkunst zu nutzen.\n\n Ihr erhaltet beim Zerschmettern folgenden Effekt:\n\n Zerschmetterte Essenz :\n Ermächtigt von zerschmetterter magischer Essenz aus Khaz Algar. Erhöht den Einfallsreichtum, die Genialität und Mehrfachherstellung, während Ihr Zauberkunst von Khaz Algar praktiziert.\nSpezialisierung:\nSupplementäres Schmettern"}
MultiLanguageSpellData['de'][445468] = {name = "Welken", additional_info = "{1.5% von Grundmana} {40 Meter Reichweite}\nSofort\n[q]Gebrechen\n Belegt das Ziel mit einer abscheulichen Verwünschung, die seine Sehnen und Muskeln verbrennt und ihm sofort (19.8375% der Zaubermacht) Schattenflammenschaden sowie im Verlauf von 18 Sek. (296.544% der Zaubermacht) zusätzlichen Schattenflammenschaden zufügt.\n\nErsetzt 'Verderbnis'.\n\nZerstörung\n Belegt das Ziel mit einer abscheulichen Verwünschung, die seine Sehnen und Muskeln verbrennt und ihm sofort (19.8375% der Zaubermacht) Schattenflammenschaden sowie im Verlauf von 18 Sek. (296.544% der Zaubermacht) zusätzlichen Schattenflammenschaden zufügt.\n\nRegelmäßiger Schaden erzeugt ein Seelensplitterfragment und hat eine Chance von 50%, bei kritischen Treffern ein zusätzliches zu erzeugen.\n\n Ersetzt 'Feuerbrand'."}
