MultiLanguageSpellData['de'][445475] = {name = "Surekisches Sperrfeuer", additional_info = "Sofort\n[q]Zieht einen Bogen aus dem Arsenal, um eine Pfeilsalve nach vorne abzufeuern, die allen Gegnern innerhalb von 20 Metern ( 1 * 1478 ) Schattenschaden zufügt.\n\n Bis zum Ziehen der nächsten Waffe erhaltet Ihr 6 Sek. lang eine um 6% erhöhte Geschwindigkeit, wenn Ihr Euch nach dem Stillstand bewegt. Dieser Wert erhöht sich alle 2 Sek. bis zu 5-mal um 6%."}
MultiLanguageSpellData['de'][445479] = {name = "[q2]Glutnektar", additional_info = "Wirken in 2 sek.\nReagenzien:\nTrinkschlauch des Tiefenforschers (3), Heiße Honigwabe\nOptionale Reagenzien:\nGeheimzutat (#318)\n[q]Rezept für 10 Portionen. Die tatsächliche Anzahl an Portionen hängt von der Kochfertigkeit ab.\nVerkäufer:\nCendvin\nZone:\nInsel von Dorn\nKosten:\n120\n\n[q2]Glutnektar\n[q2]Benutzen: Stellt im Verlauf von 20 Sek. ( 937500 / 5 * 20) Mana wieder her. Ihr müsst beim Trinken sitzen bleiben.\n68"}
MultiLanguageSpellData['de'][445480] = {name = "[q2]Energie-im-Knie", additional_info = "Wirken in 2 sek.\nReagenzien:\nTrinkschlauch des Tiefenforschers (5)\nOptionale Reagenzien:\nGeheimzutat (#318)\n[q]Rezept für 1 Portionen. Die tatsächliche Anzahl an Portionen hängt von der Kochfertigkeit ab.\nVerkäufer:\nKapitänin Oathmyt\nZone:\nHeilsturz\nKosten:\n10\n\n[q2]Energie-im-Knie\n[q2]Benutzen: Stellt im Verlauf von 20 Sek. ( 937500 / 5 * 20) Mana wieder her. Ihr müsst beim Trinken sitzen bleiben.\n\n Energie-im-Knie\n Wenn Ihr mindestens 10 Sek. mit Trinken verbringt, erhaltet Ihr 10 Min. lang 167 Geschwindigkeit sowie die Fähigkeit, auf dem Wasser zu laufen.\n68"}
MultiLanguageSpellData['de'][445482] = {name = "[q2]Felssturzmischgetränk", additional_info = "Wirken in 2 sek.\nReagenzien:\nTrinkschlauch des Tiefenforschers (5), Schwammschlemmerei (3), Heiße Honigwabe , Bismut (10)\nOptionale Reagenzien:\nGeheimzutat (#318)\n[q]Rezept für 10 Portionen. Die tatsächliche Anzahl an Portionen hängt von der Kochfertigkeit ab.\nVerkäufer:\nKapitänin Oathmyt\nZone:\nHeilsturz\nKosten:\n10\n\n[q2]Felssturzmischgetränk\n[q2]Benutzen: Das ist überhaupt nicht gemischt... (5 Min Abklingzeit)\n68\n[q]\"Die perfekte Irdenenleckerei an einem heißen Tag in Khaz Algar.\""}
MultiLanguageSpellData['de'][445483] = {name = "[q2]Klebrig-süße Leckerei", additional_info = "Wirken in 2 sek.\nReagenzien:\nSchwammschlemmerei (3), Heiße Honigwabe , Klumpiges Mehl (5), Kernwegstaub (5)\nOptionale Reagenzien:\nGeheimzutat (#318)\n[q]Rezept für 10 Portionen. Die tatsächliche Anzahl an Portionen hängt von der Kochfertigkeit ab.\nBeute von:\nBrutverderber Ovi'nax\nZone:\nPalast der Nerub'ar\nMuster:\nErhältlich im Auktionshaus\n\n[q2]Klebrig-süße Leckerei\n[q2]Benutzen: Werdet wieder zum Kind! (5 Min Abklingzeit)\n68\n[q]\"Glutbienenhonig aus den oberen Höhlensystemen ist eine Delikatesse für jeden jungen Neruber.\""}
MultiLanguageSpellData['de'][445484] = {name = "[q2]Geschmolzener Kerzenstab", additional_info = "Wirken in 2 sek.\nReagenzien:\nSchwammschlemmerei (3), Heiße Honigwabe , Klumpiges Mehl (5)\nOptionale Reagenzien:\nGeheimzutat (#318)\n[q]Rezept für 10 Portionen. Die tatsächliche Anzahl an Portionen hängt von der Kochfertigkeit ab.\nVerkäufer:\nKapitänin Oathmyt\nZone:\nHeilsturz\nKosten:\n10\n\n[q2]Geschmolzener Kerzenstab\n[q2]Benutzen: Ein Versuch kann nicht schaden. (5 Min Abklingzeit)\n68\n[q]\"Eine perfekte Mischung aus zäh und knusprig. Ihr könnt Euch nicht vorstellen, dies mit irgendjemandem zu teilen.\""}
