MultiLanguageSpellData['de'][447364] = {name = "[q2]Unwiderstehlicher roter Knopf", additional_info = "Wirken in 2 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nHaufen rostigen Schrotts (10), Handvoll Bismutbolzen (12), Launische Verdrahtung (3), Kreisende Ausrüstung (4), Entropieverstärker\nOptionale Reagenzien:\nErsatzteile (#347) , Authentizität des Kunsthandwerks (#346)\nEntdeckung:\nErfinden, Prototypenerstellung und Notizen\n\n\n[q2]Unwiderstehlicher roter Knopf\nWird beim Aufheben gebunden\n[q2]Benutzen: Setzt ein Gerät ein, das von Euch oder einem Mitglied Eurer Gruppe bzw. Eures Schlachtzugs aktiviert werden kann, wenn eine Notlage droht. Wenn es aktiviert wird, versucht es, am Ende des Kampfes alle Verbündeten in der Nähe wiederzubeleben.\n\n Hält 1 Stunde lang an oder bis es aktiviert wird. Muss vor dem Kampf eingesetzt werden.\n68\nBenötigtIngenieurskunst von Khaz Algar\n(1)"}
MultiLanguageSpellData['de'][447365] = {name = "Pausierender Pylon", additional_info = "Wirken in 2 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nHaufen rostigen Schrotts (10), Handvoll Bismutbolzen (8), Launische Verdrahtung (2), Kreisende Ausrüstung (2)\nEntdeckung:\nErfinden, Prototypenerstellung und Notizen\n\n\n[q2]Benutzen: Platziert einen pausierenden Pylonen, der die Stoffwechselprozesse von Spielercharakteren in seiner Nähe unterbricht und den Ablauf der Fläschchen, Phiolen und Sättigungseffekte von Khaz Algar anhält.\n\n Der Pylon ist äußert zerbrechlich und explodiert in der Gegenwart von Gewalt.\n68"}
MultiLanguageSpellData['de'][447367] = {name = "[q2]Algarischer Reparaturbot 11-O", additional_info = "Wirken in 2 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nHaufen rostigen Schrotts (10), Handvoll Bismutbolzen (8), Launische Verdrahtung , Kreisende Ausrüstung (2), Entropieverstärker\nEntdeckung:\nErfinden, Prototypenerstellung und Notizen\n\n\n[q2]Algarischer Reparaturbot 11-O\nWird beim Aufheben gebunden\n[q2]Benutzen: Setzt einen kleinen irdenen Golem ein, der Euch und Euren Gefährten erlaubt, Eure Ausrüstung zu reparieren.\n\n Hält 10 Min. lang an.\n68\nBenötigtIngenieurskunst von Khaz Algar\n(1)"}
MultiLanguageSpellData['de'][447368] = {name = "[q3]Tragbarer Berufsmöglichkeitenprojektor", additional_info = "Wirken in 2 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nHaufen rostigen Schrotts (10), Handvoll Bismutbolzen (12), Launische Verdrahtung , Kreisende Ausrüstung (2), Entropieverstärker\nEntdeckung:\nErfinden, Prototypenerstellung und Notizen\n\n\n[q3]Tragbarer Berufsmöglichkeitenprojektor\n[q2]Benutzen: Beschwört einen Möglichkeitenprojektor, der für die Erfüllung der Anforderungen an Handwerkstische konfiguriert wurde. Es kann nur eine Werkbank gleichzeitig angezeigt und ausschließlich durch den Ingenieur ausgetauscht werden. (10 Min Abklingzeit)\n68\nBenötigtIngenieurskunst von Khaz Algar\n(1)"}
MultiLanguageSpellData['de'][447369] = {name = "[q3]Fass mit Feuerwerkskörpern", additional_info = "Wirken in 2 sek. 2\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nHaufen rostigen Schrotts (50), Handvoll Bismutbolzen (50), Launische Verdrahtung (24), Kreisende Ausrüstung (10), Chaosschaltkreis (8), Entropieverstärker (3)\nEntdeckung:\nErfinden, Prototypenerstellung und Notizen\n\n\n[q3]Fass mit Feuerwerkskörpern\nSpielzeug\n[q2]Benutzen: Stellt ein gefährliches Fass mit Feuerwerkskörpern auf, das 5 Min. Sek. lang stehen bleibt, um für Euch und Eure Freunde den Nachthimmel grell zu erleuchten!\n\n Andere Spielercharaktere können sich das Feuerwerk auch ansehen, indem sie das Fass angreifen.\n\n Während der Feierlichkeiten von betrunkenen Goblins ist die Abklingzeit verringert. (1 Stunde Abklingzeit)"}
MultiLanguageSpellData['de'][447370] = {name = "[q3]Defekte Rettungskapsel", additional_info = "Wirken in 2 sek. 2\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nHaufen rostigen Schrotts (50), Handvoll Bismutbolzen (75), Launische Verdrahtung (10), Kreisende Ausrüstung (16), Sicherheitsschalter (6), Entropieverstärker (2)\nEntdeckung:\nErfinden, Prototypenerstellung und Notizen\n\n\n[q3]Defekte Rettungskapsel\nSpielzeug\n[q2]Benutzen: Sucht dringend Schutz in einer defekten Rettungskapsel. Ihr kommt zwar nicht sehr weit, doch dafür seid Ihr in Sicherheit. (10 Min Abklingzeit)"}
MultiLanguageSpellData['de'][447371] = {name = "[q3]Filmlose Kamera", additional_info = "Wirken in 2 sek. 2\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nHaufen rostigen Schrotts (50), Handvoll Bismutbolzen (100), Launische Verdrahtung (6), Kreisende Ausrüstung (8), Sicherheitsschalter , Entropieverstärker\nEntdeckung:\nErfinden, Prototypenerstellung und Notizen\n\n\n[q3]Filmlose Kamera\nSpielzeug\n[q2]Benutzen: Weckt Euer Fotografietalent! (30 Sek. Abklingzeit)"}
