MultiLanguageSpellData['de'][447874] = {name = "[q2]Kleine Kumpelkekse", additional_info = "Wirken in 2 sek.\nReagenzien:\nGeronnenes Eigelb , Schwammschlemmerei (4), Klumpiges Mehl (5)\nOptionale Reagenzien:\nGeheimzutat (#318)\n[q]Rezept für 3 Portionen. Die tatsächliche Anzahl an Portionen hängt von der Kochfertigkeit ab.\nVerkäufer:\nTyro Whalekk\nZone:\nStadt der Fäden\nKosten:\n1500\n\n[q2]Kleine Kumpelkekse\n[q2]Benutzen: Belebt alle Eure Haustiere wieder und heilt sie auf 100% Gesundheit.\n68\n[q]\"Aus echten kleinen Kumpeln!\""}
MultiLanguageSpellData['de'][447875] = {name = "[q2]Azj-Kahet-Spezial", additional_info = "Wirken in 2 sek.\nReagenzien:\nTrinkschlauch des Tiefenforschers , Geronnenes Eigelb\nOptionale Reagenzien:\nGeheimzutat (#318)\n[q]Rezept für 1 Portionen. Die tatsächliche Anzahl an Portionen hängt von der Kochfertigkeit ab.\nVerkäufer:\nAx'ill\nZone:\nStadt der Fäden\nKosten:\n1500\n\nVerkäufer:\nTej die Unverwüstliche\nZone:\nStadt der Fäden\nKosten:\n1.500\n\n[q2]Azj-Kahet-Spezial\n[q2]Benutzen: Erhöht Eure Bewegungsgeschwindigkeit um 20%, während Ihr in der Stadt der Fäden seid. Kann nur im Freien eingesetzt werden.\n68\n[q]\"Stadtschlemmerei!\""}
MultiLanguageSpellData['de'][447876] = {name = "[q3]Geisterfisch-Schmaus", additional_info = "Wirken in 2 sek.\nReagenzien:\nVorbereiteter Geisterfisch , Einfacher Eintopf\nOptionale Reagenzien:\nGeheimzutat (#318)\n[q]Rezept für 5 Portionen. Die tatsächliche Anzahl an Portionen hängt von der Kochfertigkeit ab.\nVerkäufer:\nKapitänin Oathmyt\nZone:\nHeilsturz\nKosten:\n10\n\n[q3]Geisterfisch-Schmaus\nWird beim Aufheben gebunden\n[q2]Benutzen: Stellt im Verlauf von 20 Sek. ( 375000 / 5 * 20) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\n Satt\n Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr ' Satt ' und erhaltet 1 Stunde lang 30 Angelfertigkeit von Khaz Algar und 150 Wahrnehmung.\n75\n[q]\"Der schlimmste Alptraum des Anglers ist die Delikatesse des Kochs.\""}
