MultiLanguageSpellData['de'][448658] = {name = "Anrufung: Arkaner Phönix", additional_info = "[q]Arkan\n Wenn Ihr 'Arkane Woge' einsetzt, beschwört Ihr einen arkanen Phönix, der Euch im Kampf unterstützt.\n\n ' Arkaner Phönix '\n Euer arkaner Phönix unterstützt Euch für die Dauer von 'Arkane Woge' und setzt zufällige arkane und Feuerzauber ein.\n\nFeuer\n Wenn Ihr 'Einäschern' einsetzt, beschwört Ihr einen arkanen Phönix, der Euch im Kampf unterstützt.\n\n ' Arkaner Phönix '\n Euer arkaner Phönix unterstützt Euch für die Dauer von 'Einäschern' und setzt zufällige arkane und Feuerzauber ein."}
MultiLanguageSpellData['de'][448659] = {name = "Arkaner Phönix", additional_info = "40 Meter Reichweite\nSofort\n[q]Arkan\nWenn Ihr 'Arkane Woge' einsetzt, beschwört Ihr einen arkanen Phönix, der Euch im Kampf unterstützt.\n\n ' Arkaner Phönix '\n Euer arkaner Phönix unterstützt Euch für die Dauer von 'Arkane Woge' und setzt zufällige arkane und Feuerzauber ein.\n\nFeuer\nWenn Ihr 'Einäschern' einsetzt, beschwört Ihr einen arkanen Phönix, der Euch im Kampf unterstützt.\n\n ' Arkaner Phönix '\n Euer arkaner Phönix unterstützt Euch für die Dauer von 'Einäschern' und setzt zufällige arkane und Feuerzauber ein."}
