MultiLanguageSpellData['de'][448669] = {name = "Phantomernte", additional_info = "100 Meter Reichweite\nSofort\n[q]Eure Fähigkeiten haben eine hohe Chance, ein Phantom zu beschwören, das Eurem Ziel ( 1 * 600 ) Schattenschaden und allen anderen Gegnern in seinem Weg ( 1 * 600 * 0.09) Schattenschaden zufügt.\n\n Wenn sich das Ziel bei weniger als 35% Gesundheit befindet, beschwört dieser Effekt zwei zusätzliche Phantome mit 25% Effektivität."}
