MultiLanguageSpellData['de'][449563] = {name = "Nerubischer Giftpfeil", additional_info = "Ca. 3 Procs pro Minute\n[q]Eure Distanzangriffe haben eine Chance dem Ziel ein lähmendes Gift zu injizieren, das im Verlauf von 9 Sek. ( 1 * 592 ) Naturschaden verursacht.\n\n Für jede Sekunde, in der sich das betroffene Ziel bewegt, erhaltet Ihr 10 Sek. lang ( 24 / 5) Tempo. Bis zu 5-mal stapelbar."}
MultiLanguageSpellData['de'][449564] = {name = "Reparierende Flammen", additional_info = "10 Meter Reichweite\n{Sofort} {10 sek. Abklingzeit}\n[q]Erschafft einen Schild, der Euch vor jeglichem Schaden schützt und Euch schnell auf volle Gesundheit heilt. Hält 4 Sek. lang an."}
MultiLanguageSpellData['de'][449566] = {name = "Meteoritenbrand", additional_info = "100 Meter Reichweite\nSofort\n[q]Ruft einen Meteor herab, der nach 3 Sek. am Zielort einschlägt. Fügt allen Gegnern (444% der Zaubermacht) Feuerschaden zu und verbrennt den Boden, um allen Gegnern im Gebiet im Verlauf von 8.5 Sek. [8 * (8.53875% der Zaubermacht)] Feuerschaden zuzufügen.\n\n Der Gegner, der am nächsten zum Zentrum des Einschlags ist, erleidet 40% mehr Schaden. Der Schaden ist nach dem 8. Ziel verringert."}
MultiLanguageSpellData['de'][449567] = {name = "Filetieren", additional_info = "10 Meter Reichweite\nWirken in 1 sek.\n[q]Schneidet einen Feind und fügt ihm 150% Waffenschaden als körperlichen Schaden zu."}
MultiLanguageSpellData['de'][449568] = {name = "Netzblitz", additional_info = "30 Meter Reichweite\nWirken in 2 sek.\n[q]Der Zaubernde feuert einen dichten Klumpen aus Spinnweben auf sein aktuelles Ziel, der diesem Naturschaden zufügt und seine Bewegungsgeschwindigkeit 5 Sek. lang um 30% verringert."}
MultiLanguageSpellData['de'][449569] = {name = "Meteorit", additional_info = "100 Meter Reichweite\nSofort\n[q]Ruft einen Meteoriten herab, der nach 3 Sek. am Zielort einschlägt und allen getroffenen Gegnern (102% der Zaubermacht) Feuerschaden zufügt. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu."}
MultiLanguageSpellData['de'][449570] = {name = "Strahlendes Licht", additional_info = "Unbegrenzte Reichweite\nKanalisiert (Wirken in 7 tagen)\n[q]Segnet alle in der Nähe mit ' Strahlendes Licht '.\n\n\nStrahlendes Licht\n Unbegrenzte Reichweite\n\nSofort Strahlendes Licht umhüllt den Spielercharakter und schützt ihn vor ' Wuchernde Schatten '. Erlaubt Himmelsreiten, statisches Fliegen und Aufsitzen im Kampf.\n\n Sobald der Einflussbereich des Lampenanzünders verlassen wird, hält 'Strahlendes Licht' nicht mehr ewig an. Wenn 10 Sek. oder weniger Zeit verbleibt, erleiden Spielercharaktere ' Wuchernde Schatten '."}
MultiLanguageSpellData['de'][449571] = {name = "Quecksilbrige Kräuter", additional_info = "Wirken in 3 sek. 1 tag Wiederaufladung\n3 Aufladungen\nTools: Stein der Weisen\nReagenzien:\nQuecksilbriges Transmutagen (6), Instabiles Transmutagen (3)\nEntdeckung:\nThaumaturgie"}
