MultiLanguageSpellData['de'][449573] = {name = "Quecksilbrige Vereinigung", additional_info = "Wirken in 3 sek. 1 tag Wiederaufladung\n3 Aufladungen\nTools: Stein der Weisen\nReagenzien:\nInstabiles Transmutagen (6), Ominöses Transmutagen (6)\n[q]Vereinigt mit der Kraft Eures Steins der Weisen quecksilbriges Transmutagen durch die Kombination von ominösem und instabilem Transmutagen.\nSpezialisierung:\nThaumaturgie - Quecksilbrige Materialien"}
MultiLanguageSpellData['de'][449574] = {name = "Ominöse Vereinigung", additional_info = "Wirken in 3 sek. 1 tag Wiederaufladung\n3 Aufladungen\nTools: Stein der Weisen\nReagenzien:\nInstabiles Transmutagen (6), Quecksilbriges Transmutagen (6)\n[q]Vereinigt mit der Kraft Eures Steins der Weisen ominöses Transmutagen durch die Kombination von quecksilbrigem und instabilem Transmutagen.\nSpezialisierung:\nThaumaturgie - Ominöse Materialien"}
MultiLanguageSpellData['de'][449575] = {name = "Flüchtige Vereinigung", additional_info = "Wirken in 3 sek. 1 tag Wiederaufladung\n3 Aufladungen\nTools: Stein der Weisen\nReagenzien:\nOminöses Transmutagen (6), Quecksilbriges Transmutagen (6)\n[q]Vereinigt mit der Kraft Eures Steins der Weisen instabiles Transmutagen durch die Kombination von ominösem und quecksilbrigem Transmutagen.\nSpezialisierung:\nThaumaturgie - Instabile Materialien"}
