MultiLanguageSpellData['de'][449614] = {name = "Dämonenseele", additional_info = "[q]Dämonologie\n Ein dämonisches Wesen wohnt in Eurer Seele und ermöglicht es Euch zu entdecken, ob ein Seelensplitter bei seiner Entstehung über eine saftige Seele verfügt.\n\n Eine saftige Seele ermächtigt Euren nächsten Einsatz von 'Hand von Gul'dan', erhöht seinen Schaden um 60% und entfesselt Eure dämonische Seele, um (176.618% der Zaubermacht) zusätzlichen Schattenschaden zu verursachen.\n\nGebrechen\n Ein dämonisches Wesen wohnt in Eurer Seele und ermöglicht es Euch zu entdecken, ob ein Seelensplitter bei seiner Entstehung über eine saftige Seele verfügt.\n\n Eine saftige Seele ermächtigt Euren nächsten Einsatz von 'Unheilvolle Euphorie', erhöht seinen Schaden um 20% und entfesselt Eure dämonische Seele, um (176.618% der Zaubermacht) zusätzlichen Schattenschaden zu verursachen."}
MultiLanguageSpellData['de'][449619] = {name = "Erinnerung an Al'ar", additional_info = "[q]Arkan\n Während Ihr unter dem Effekt von 'Arkane Woge' steht, erhaltet Ihr doppelt so viele Stapel von 'Manakaskade'.\n\n Wenn Euer arkaner Phönix abläuft, ermächtigt er Euch und verleiht Euch 'Arkane Seele' für 2 Sek. und weitere 1.0 Sek. pro außergewöhnlichem Zauber, der zum Einsatz gekommen ist.\n\nArkane Seele :\n'Arkanbeschuss' gewährt 'Freizaubern' und erzeugt 4 arkane Aufladungen.\n\n Jedes Wirken von 'Arkanbeschuss' erhöht den Schaden von 'Arkanbeschuss' um 15%, bis maximal 150%.\n\nFeuer\n Während Ihr unter dem Effekt von 'Einäschern' steht, erhaltet Ihr doppelt so viele Stapel von 'Manakaskade'.\n\n Wenn Euer arkaner Phönix abläuft, ermächtigt er Euch und verleiht Euch 'Hyperthermie' für 2 Sek. und weitere 1.0 Sek. pro außergewöhnlichem Zauber, der zum Einsatz gekommen ist.\n\n Hyperthermie :\n'Pyroschlag' und 'Flammenstoß' sind Spontanzauber, erzielen garantiert kritische Treffer und erhöhen den Schaden von 'Pyroschlag' und 'Flammenstoß' um 15%."}
MultiLanguageSpellData['de'][449620] = {name = "Nekrolythenlehren", additional_info = "[q]Gebrechen\n 'Schattenblitz' und 'Seelendieb' um 20% erhöht. 'Nachtsturz' erhöht den Schaden von 'Schattenblitz' und 'Seelendieb' um zusätzliche 50%.\n\nDämonologie\n Schaden von 'Schattenblitz' um 20% erhöht. 'Kraftentzug' erhöht den Schaden von 'Dämonenblitz' um zusätzliche 20%."}
MultiLanguageSpellData['de'][449621] = {name = "[q3]Erinnerungen kombinieren", additional_info = "Wirken in 5 sek.\nReagenzien:\nErinnerung an Nordend (20)\n[q]Kombinieren 20 Erinnerungen von Nordend in eine verfestigte Essenz."}
MultiLanguageSpellData['de'][449622] = {name = "Netzsprechen", additional_info = "Sofort\n[q]Ihr zapft ein Netz aus uraltem Wissen an und erhöht Euer Zaubertempo 15 Sek. lang um 25%."}
MultiLanguageSpellData['de'][449623] = {name = "[q3]Erinnerungen kombinieren", additional_info = "Wirken in 5 sek.\nReagenzien:\nErinnerung an Kalimdor (20)\n[q]Kombinieren 20 Erinnerungen von Kalimdor in eine verfestigte Essenz."}
MultiLanguageSpellData['de'][449624] = {name = "Seelenbannfluch", additional_info = "[q]Das Entfesseln Eurer dämonischen Seele überträgt ein teuflisches Wesen auf die Seele ihrer Ziele und fügt ihnen im Verlauf von 10 Sek. (127.457% der Zaubermacht) Schattenschaden zu.\n\n Wird dieser Effekt erneut angewendet, wird verbleibender Schaden dem neuen 'Seelenbannfluch' hinzugefügt."}
