MultiLanguageSpellData['de'][449628] = {name = "[q3]Erinnerungen kombinieren", additional_info = "Wirken in 5 sek.\nReagenzien:\nErinnerung an die Östlichen Königreiche (20)\n[q]Kombinieren 20 Erinnerungen der Östlichen Königreiche in eine verfestigte Essenz."}
MultiLanguageSpellData['de'][449629] = {name = "Eifer des Besessenen", additional_info = "[q]Dämonologie\n Eure dämonische Seele fügt dem Hauptziel von 'Hand von Gul'dan' 100% mehr Schaden zu.\n\nGebrechen\n Eure dämonische Seele fügt von Eurem Zauber 'Instabiles Gebrechen' betroffenen Zielen 100% mehr Schaden zu."}
MultiLanguageSpellData['de'][449631] = {name = "Tückischer Schnitter", additional_info = "[q]Dämonologie\n Der von Eurer dämonischen Seele verursachte Schaden wird um 10% erhöht.\n\n Der Verbrauch von 'Dämonischer Kern' füttert das dämonische Wesen in Euch, das erscheint und Eurem Ziel [(240.402% der Zaubermacht) * 0.4] Schattenschaden zufügt.\n\nGebrechen\n Der von Eurer dämonischen Seele verursachte Schaden wird um 10% erhöht.\n\n Der Verbrauch von 'Nachtsturz' füttert das dämonische Wesen in Euch, das erscheint und Eurem Ziel (240.402% der Zaubermacht) Schattenschaden zufügt."}
MultiLanguageSpellData['de'][449632] = {name = "Erinnerung aufnehmen", additional_info = nil}
MultiLanguageSpellData['de'][449634] = {name = "Exitus", additional_info = "[q]Dämonologie\n Der Schaden von 'Seelenbannfluch' wird um 25% erhöht und um 20% schneller verursacht.\n\n Der Verbrauch von 'Dämonischer Kern' aktiviert 'Geteiltes Schicksal' oder 'Festmahl der Seelen'.\n\nGebrechen\n Der Schaden von 'Seelenbannfluch' wird um 25% erhöht und um 20% schneller verursacht.\n\n Der Verbrauch von 'Nachtsturz' aktiviert 'Geteiltes Schicksal' oder 'Festmahl der Seelen'."}
MultiLanguageSpellData['de'][449637] = {name = "Sataiels Wille", additional_info = "[q]Gebrechen\n 'Verderbnis' verursacht Schaden um 25% schneller, und 'Heimsuchung' gewährt 'Nachtsturz'.\n\nDämonologie\n Der Schaden von Wildwichteln wird um 5% erhöht, und implodierte Wildwichtel haben eine zusätzliche Chance von 5%, Euch 'Dämonischer Kern' zu gewähren."}
MultiLanguageSpellData['de'][449638] = {name = "Schatten des Todes", additional_info = "[q]Dämonologie\n Euer Zauber 'Dämonischen Tyrannen beschwören' ist vom dämonischen Wesen in Euch ermächtigt, sodass er Euch 3 Seelensplitter gewährt, die jeweils eine saftige Seele enthalten.\n\nGebrechen\n Euer Zauber 'Seelenfäule' ist vom dämonischen Wesen in Euch ermächtigt, sodass er Euch 3 Seelensplitter gewährt, die jeweils eine saftige Seele enthalten."}
MultiLanguageSpellData['de'][449639] = {name = "[q7]Erinnerungen durchtränken", additional_info = "Wirken in 5 sek.\nReagenzien:\nEssenz der Östlichen Königreiche , Essenz Kalimdors , Essenz Nordends , Lebloser Steinring\n[q]Durchtränke sie mit den Essenzen Azeroths, um ihre Macht wiederherzustellen."}
