MultiLanguageSpellData['de'][450283] = {name = "[q4]Hammer des irdenen Meisters", additional_info = "Wirken in 3.5 sek.\nTools: Schmiedehammer\nReagenzien:\nBarren der Schallenden Tiefen (2), Aufgeladene Legierung (10), Geheiligte Legierung (10), Eisenklauenlegierung (10)\nBeruf:\nSchmiedekunst von Khaz Algar (100)\n\n[q4]Hammer des irdenen Meisters\nWird beim Aufheben gebunden\n[q2]Benutzen: Repariert eine Waffe oder ein Plattenrüstungsteil, auf deren bzw. dessen Reparatur Ihr Euch spezialisiert habt.\nBenötigtSchmiedekunst von Khaz Algar\n(25)"}
MultiLanguageSpellData['de'][450291] = {name = "[q2]Kerngeschmiedeter Reparaturhammer", additional_info = "Wirken in 3.5 sek.\nTools: Schmiedehammer\nReagenzien:\nBismut (10), Eisenklauenerz (2)\nOptionale Reagenzien:\nSchmiedezubehör (#382)\nBerufsausbilder:\nSchmiedekunst von Khaz Algar (5)\nKosten:\n80\n\n[q2]Kerngeschmiedeter Reparaturhammer\n[q2]Benutzen: Repariert eine Waffe oder ein Plattenrüstungsteil vollständig. Wird bei Benutzung verbraucht.\n70\nBenötigtSchmiedekunst von Khaz Algar\n(1)"}
MultiLanguageSpellData['de'][450292] = {name = "[q2]Kerngeschmiedeter Dietrich", additional_info = "Wirken in 3.5 sek.\nTools: Schmiedehammer\nReagenzien:\nBismut (8), Eisenklauenerz (4)\nOptionale Reagenzien:\nSchmiedezubehör (#382)\nVerkäufer:\nWelthändler von Khaz Algar\nKosten:\n150\n1500\n\n[q2]Kerngeschmiedeter Dietrich\n[q2]Benutzen: Ermöglicht das Öffnen von Schlössern, die eine Fertigkeit von bis zu 80 im Schlossknacken benötigen. Dieser Vorgang verbraucht den Dietrich."}
