MultiLanguageSpellData['de'][450674] = {name = "Foliant der Hingabe des Lichts", additional_info = "[q]Ihr öffnet im Kampf den Foliant und lest \"Die 50 Verse der inneren Abhärtung\". Erhöht Eure Rüstung um 80 und gewährt Euren Angriffen eine Chance, einen Schutz zu erzeugen, der 1025 Magieschaden absorbiert. Anschließend seht Ihr die Passagen bis zum nächsten Kapitel durch.\n\n Einsatz: Seht sorgfältig die Passagen bis zum nächsten Kapitel durch und lest mit erhöhtem Strahlen."}
MultiLanguageSpellData['de'][450675] = {name = "Grimmwebenausbruch", additional_info = "40 Meter Reichweite\nSofort\n[q]Der Zaubernde webt Runen aus Spinnweben und beschwört einen instabilen Ball aus Spinnweben über der Position des Ziels. Beim Aufprall platzt er explosionsartig und fügt den getroffenen Spielercharakteren Naturschaden zu."}
MultiLanguageSpellData['de'][450676] = {name = "Netz des Anglers", additional_info = "{Wirken in} {2.5 sek. 1 sek. Abklingzeit}\n[q]Schießt Netze vor den Zaubernden, die Gegner packen und in sie hereinziehen. Die getroffenen Ziele werden dann zerdrückt und erleiden 348533 Naturschaden."}
MultiLanguageSpellData['de'][450677] = {name = "Berstende Runen", additional_info = "{Wirken in} {1.5 sek. 8 sek. Abklingzeit}\n[q]Orta beschwört 5 Sek. lang alle 1 Sek. eine Rune der Verwüstung. Wenn sie ausgelöst werden, betäuben diese Runen den auslösenden Spielercharakter und fügen ihm zusätzlich alle 1 Sek. 261400 Feuerschaden zu. Hält 8 Sek. lang an."}
