MultiLanguageSpellData['de'][451609] = {name = "Netzbombe", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Strangspinnerin Takazj verschießt explodierende Netze auf Spielercharaktere, die allen Spielercharakteren innerhalb von 10 Metern 20 Naturschaden zufügen.\n\n Wenn sich mehr als ein Spielercharakter im Bereich befindet, werden die Spielercharaktere mit ' Bindende Netze ' aneinander gefesselt, was die Bewegungsgeschwindigkeit um 20 % verringert.\n\n Wenn sich gefesselte Spielercharaktere mehr als 30 Meter voneinander entfernen oder Anub'arash durch das Netz stürmt, wird es zerstört und entfernt ' Bindende Netze '."}
MultiLanguageSpellData['de'][451610] = {name = "Netzbombe", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Takazj verschießt klebrige Gespinstknoten in der Kammer, die die Bewegungsgeschwindigkeit von Spielercharakteren um 20% verringern und ihnen alle 1 Sek. 345379 körperlichen Schaden zufügen, während diese sich im Effektbereich befinden.\n\n Der Knoten in der Mitte bricht bei Berührung aus, was Spielercharakteren innerhalb von 10 Metern 1732248 Naturschaden zufügt und ' Bindende Netze ' einsetzt, um zwei Spielercharaktere mit aneinanderzubinden.\n\n Wenn Anub'arash durch Stränge von 'Bindende Netze' stürmt, wird er 'Umschlungen'."}
