MultiLanguageSpellData['de'][452402] = {name = "Dämonenwoge", additional_info = "[q]Verwüstung\n Der Zauber 'Metamorphose' lässt 'Dämonenbiss' zusätzlich 15 Jähzorn erzeugen.\n\n Während die Dämonengestalt aktiv ist, löst der jeweils erste Einsatz jeder ermächtigten Fähigkeit 'Dämonenwoge' aus, wodurch Ihr vor Teufelsenergie explodiert und Gegnern in der Nähe (330% der Angriffskraft) Feuerschaden zufügt. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu.\n\nRachsucht\n Der Zauber 'Metamorphose' ermächtigt 'Seelenspalter' und 'Seelenbombe' stark.\n\n Während die Dämonengestalt aktiv ist, löst der jeweils erste Einsatz jeder ermächtigten Fähigkeit 'Dämonenwoge' aus, wodurch Ihr vor Teufelsenergie explodiert und Gegnern in der Nähe (330% der Angriffskraft) Feuerschaden zufügt. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu."}
MultiLanguageSpellData['de'][452403] = {name = "Welle der Entkräftung", additional_info = "[q]'Chaosnova' verlangsamt Gegner um 60% und verringert das Angriffs- und Zaubertempo 5 Sek. lang um 15%, nachdem ihre Betäubung abgeklungen ist."}
MultiLanguageSpellData['de'][452404] = {name = "Streben nach Wut", additional_info = "[q]Bewegungsgeschwindigkeit um 1% pro 10 Jähzorn erhöht."}
MultiLanguageSpellData['de'][452405] = {name = "Fokussierter Hass", additional_info = "[q]Eure 'Dämonenwoge' verursacht 50% mehr Schaden, wenn sie ein einzelnes Ziel trifft.\n\n Jedes weitere Ziel reduziert diesen Bonus um 10%."}
MultiLanguageSpellData['de'][452406] = {name = "Brennende Schmerzen", additional_info = "[q]5% sämtlichen erlittenen Schadens außer Feuerschaden wird stattdessen als Feuerschaden im Verlauf von 6 Sek. erlitten.\n\n Der erlittene Feuerschaden wird um 10% reduziert."}
MultiLanguageSpellData['de'][452407] = {name = "Verbesserter Seelenreißer", additional_info = "[q]Durch 'Seelenreißer' gewährter Lebensraub wurde um 2% und zusätzlich um 2% erhöht, während 'Metamorphose' aktiv ist."}
MultiLanguageSpellData['de'][452408] = {name = "Brennende Klingen", additional_info = "[q]Verwüstung\n Eure Klingen brennen mit Teufelsenergie, wodurch Eure 'Chaosstoß', 'Gleve werfen' und automatischen Angriffe zusätzlich 50% Schaden als Feuer über 6 Sek. zufügen.\n\nRachsucht\n Eure Klingen brennen mit Teufelsenergie, wodurch Eure 'Seelenspalter', 'Gleve werfen' und automatischen Angriffe zusätzlich 40% Schaden als Feuer über 6 Sek. zufügen."}
MultiLanguageSpellData['de'][452409] = {name = "Gewaltsame Verwandlung", additional_info = "[q]Rachsucht\n Wenn Ihr 'Metamorphose' aktiviert, werden die Abklingzeiten Eurer Zauber 'Zeichen der Flamme' und 'Dämonische Verwüstung' sofort zurückgesetzt.\n\nVerwüstung\n Wenn Ihr 'Metamorphose' aktiviert, werden die Abklingzeiten Eurer Zauber 'Zeichen der Flamme' und 'Feuerbrandaura' sofort zurückgesetzt."}
MultiLanguageSpellData['de'][452410] = {name = "Andauernde Folter", additional_info = "[q]Verwüstung\n Die Effekte Eurer Dämonenform bestehen in abgeschwächter Form auch außerhalb davon fort und erhöhen den Schaden von 'Chaosstoß' und 'Klingentanz' um 15% und Euer Tempo um 5%.\n\nRachsucht\n Die Effekte Eurer Dämonenform bestehen in abgeschwächter Form auch außerhalb davon fort und erhöhen die maximale Gesundheit um 5% und die Rüstung um 20%."}
MultiLanguageSpellData['de'][452411] = {name = "Freigelassener Jähzorn", additional_info = "[q]Erhöht den maximalen Jähzorn um 50."}
MultiLanguageSpellData['de'][452412] = {name = "Lehren des Leids", additional_info = "[q]'Zeichen der Flamme' kann 'Lehren des Leids' auf Euch anwenden, was Eure Meisterschaft um (8 * $mas)% erhöht und 6 Sek. lang alle 2 Sek. 5 Jähzorn gewährt."}
MultiLanguageSpellData['de'][452413] = {name = "Flammengebunden", additional_info = "[q]'Feuerbrandaura' hat einen um 2 Meter erhöhten Radius und einen um 50% erhöhten kritischen Schadensbonus."}
MultiLanguageSpellData['de'][452414] = {name = "Aufsteigendes Monster", additional_info = "[q]Beweglichkeit ohne Dämonenform um 8% erhöht."}
MultiLanguageSpellData['de'][452415] = {name = "Dämonische Intensität", additional_info = "[q]Verwüstung\n Die Aktivierung von 'Metamorphose' verstärkt 'Augenstrahl', 'Feuerbrandaura' und 'Zeichen der Flamme' stark.\n\n Der Schaden durch 'Dämonenwoge' wird für jede vorherige Aktivierung während Eurer Dämonenform um 10 % erhöht.\n\nRachsucht\n Die Aktivierung von 'Metamorphose' verstärkt 'Dämonische Verwüstung', 'Feuerbrandaura' und 'Zeichen der Flamme' stark.\n\n Der Schaden durch 'Dämonenwoge' wird für jede vorherige Aktivierung während Eurer Dämonenform um 10 % erhöht."}
MultiLanguageSpellData['de'][452416] = {name = "Dämonenwoge", additional_info = "Sofort\n[q]Der Zauber 'Metamorphose' [ Verwüstung : lässt 'Dämonenbiss' zusätzlich 15 Jähzorn erzeugen /\n\nRachsucht\nermächtigt 'Seelenspalter' und 'Seelenbombe' stark ]\n Während die Dämonengestalt aktiv ist, löst der jeweils erste Einsatz jeder ermächtigten Fähigkeit 'Dämonenwoge' aus, wodurch Ihr vor Teufelsenergie explodiert und Gegnern in der Nähe (330% der Angriffskraft) Feuerschaden zufügt. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu."}
