MultiLanguageSpellData['de'][452868] = {name = "Blitzkette", additional_info = "[q]Für den folgenden Effekt in einen Tüfteleisockel einsetzen:\n\n Blitzkette\nEntfesselt bis zu 8 Sek. lang eine Woge aus Elektrizität auf einen 5-25 Meter entfernten Gegner. Beträgt die Distanz zwischen Euch und Eurem Ziel mehr als 30 Meter, wird er in Eure Richtung gezogen und verliert seine Leine."}
MultiLanguageSpellData['de'][452869] = {name = "Übertaktete S.E.L.F.I.E.-Kamera", additional_info = "[q]Für den folgenden Effekt in einen Tüfteleisockel einsetzen:\n\n Always Malfunction (DNT)\nDiese Tüftelei wird immer eine Fehlfunktion haben. Wird zum Testen geteilter Fehlfunktionen verwendet.\n\n Dieser Gegenstand überspringt die Logik zum Auswürfeln, ob eine Fehlfunktion auftritt, und testet nur die Effekte.\n\n Wenn Ihr das hier seht, habt Ihr wahrscheinlich einen Platzhaltergegenstand vor Euch!"}
MultiLanguageSpellData['de'][452870] = {name = "Irdener Lieferbohrer", additional_info = "[q]Für den folgenden Effekt in einen Tüfteleisockel einsetzen:\n\n Irdener Lieferbohrer\nBeschwört einen irdenen Lieferbohrer, der nach verschiedenen Schlachtfeldstärkungen gräbt.\n\n Der Bohrer bleibt 28 Sek. lang aktiv und kann nur im Kampf beschworen werden. Sein Einsatz ist nur auf nicht gewerteten Schlachtfeldern und im Kriegsmodus auf Khaz Algar möglich."}
