MultiLanguageSpellData['de'][453245] = {name = "Trankbombe der Macht", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Werft eine Trankbombe, die in ihrem Explosionsradius bis zu 5 Verbündete mit einem Trank besprüht, der deren Primärwert 30 Sek. lang um ( 44 / 5) erhöht.\n\n Von der Explosion erfasste Gegner erleiden 255 Feuerschaden, der zwischen ihnen aufgeteilt wird."}
MultiLanguageSpellData['de'][453247] = {name = "Geplatztes Koagulum", additional_info = "100 Meter Reichweite\nSofort\n[q]Füttert das Koagulum und leitet 20% sämtlicher hervorgerufener Heilung um bis ( 10669 * 40 / 100) Heilung aufgezehrt wurde. Ist es gesättigt, bricht das Koagulum auf und heilt 5 Verbündete um [( 10669 + ( 10669 * 40 * .01 * 1.03)) / 5] Gesundheit.\n\n Anhaltende Ausdünstungen lassen die nächsten Angriffe betroffener Verbündeter basierend auf der überschüssigen Heilung durch das Koagulum 76 zusätzlichen Schattenschaden verursachen."}
