MultiLanguageSpellData['de'][454389] = {name = "Weißsträhne beschwören", additional_info = "Sofort\n[q]Beim Verbrauchen von Runen habt Ihr die Chance, 10 Sek. lang die Hilfe eines Reiters zu erhalten.\n\nMograine\n Wirkt 'Tod und Verfall' an seiner Position. Der Effektbereich folgt seiner Bewegung.\n\nWeißsträhne\n Wirkt 'Untot' auf Euer Ziel, was 24 Sek. lang alle 3 Sek. pro Stapel (9.15376% der Angriffskraft) Schattenfrostschaden verursacht. Wann immer 'Untot' Schaden verursacht, wird das Ziel mit einem weiteren Stapel belegt. Kann nicht erneuert werden.\n\nTrollbann\n Wirkt 'Eisketten' auf Euer Ziel, was 8 Sek. lang dessen Bewegungsgeschwindigkeit um 40% verringert und den Schaden, den Ihr ihm zufügt, um 5% erhöht.\n\nNazgrim\n Während Nazgrim aktiv ist, erhaltet Ihr 'Apokalyptische Eroberung', was Eure Stärke um 5% erhöht."}
MultiLanguageSpellData['de'][454390] = {name = "Trollbann beschwören", additional_info = "Sofort\n[q]Beim Verbrauchen von Runen habt Ihr die Chance, 10 Sek. lang die Hilfe eines Reiters zu erhalten.\n\nMograine\n Wirkt 'Tod und Verfall' an seiner Position. Der Effektbereich folgt seiner Bewegung.\n\nWeißsträhne\n Wirkt 'Untot' auf Euer Ziel, was 24 Sek. lang alle 3 Sek. pro Stapel (9.15376% der Angriffskraft) Schattenfrostschaden verursacht. Wann immer 'Untot' Schaden verursacht, wird das Ziel mit einem weiteren Stapel belegt. Kann nicht erneuert werden.\n\nTrollbann\n Wirkt 'Eisketten' auf Euer Ziel, was 8 Sek. lang dessen Bewegungsgeschwindigkeit um 40% verringert und den Schaden, den Ihr ihm zufügt, um 5% erhöht.\n\nNazgrim\n Während Nazgrim aktiv ist, erhaltet Ihr 'Apokalyptische Eroberung', was Eure Stärke um 5% erhöht."}
