MultiLanguageSpellData['de'][454426] = {name = "Unbändiges Unheil", additional_info = "[q]Der verursachte Schaden, wenn Eure 'Schicksalsgebundene Münze' auf Zahl landet, ist um 30% erhöht, wenn sich keine anderen Gegner in der Nähe des Ziels befinden.\n\n Jeder weitere Gegner in der Nähe verringert diesen Bonus um 6%."}
MultiLanguageSpellData['de'][454428] = {name = "Schicksalhaftes Ende", additional_info = "[q]Wenn Eure schicksalsgebundene Münze sieben Mal hintereinander die gleiche Seite zeigt, dürft Ihr die Glücksmünze behalten. Sie gewährt Euch 7% Beweglichkeit, bis Ihr den Kampf 10 Sek. lang verlasst. Wenn Ihr bereits eine Glücksmünze habt, fügt sie Eurem Ziel stattdessen (420% der Angriffskraft) kosmischen Schaden zu."}
MultiLanguageSpellData['de'][454429] = {name = "Verbundenes Schicksal", additional_info = "[q]Gesetzlosigkeit\n 'Verbundenes Schicksal' dupliziert 30% des kritischen Schadens von 'Tötung' als kosmischen Schaden auf 2 zusätzliche Gegner in der Nähe. Wenn es keine zusätzlichen Ziele in der Nähe gibt, werden stattdessen 30% des Schadens auf das Primärziel geleitet.\n\nMeucheln\n 'Verbundenes Schicksal' dupliziert 30% des kritischen Schadens von 'Vergiften' als kosmischen Schaden auf 2 zusätzliche Gegner in der Nähe. Wenn es keine zusätzlichen Ziele in der Nähe gibt, werden stattdessen 30% des Schadens auf das Primärziel geleitet."}
MultiLanguageSpellData['de'][454430] = {name = "Doppelmord", additional_info = "[q]Euer erster Wurf einer schicksalsgebundenen Münze nach Aufheben der Verstohlenheit löst zwei Würfe mit garantiert demselben Ergebnis aus."}
MultiLanguageSpellData['de'][454431] = {name = "[q4]Das abgetrennte Säckchen", additional_info = "Wirken in 2 sek. 2\nReagenzien:\nZierendes Band (2), Dämmergespinstballen (5), Morgengespinstballen (5)\nOptionale Reagenzien:\nStickereifaden (#333)\nSpezialisierung:\nHochwertiger Stoff (25)\n\n[q4]Das abgetrennte Säckchen\nWird beim Aufheben gebunden\nEinzigartig\n36 Platz Tasche\n[q2]Anlegen: Erhöht den maximalen Ertrag beim Zerfasern von Khaz Algar um 1.\n\n [ Anlegeeffekt erfordert Schneiderei von Khaz Algar 1 ][ Anlegeeffekt erfordert Schneiderei von Khaz Algar 1 ]68\n[q]\"Ein Behälter, der von den Meisterhandwerkern der Weberin gesponnen wurde, die den Wert von so seltenem Stoff wie Morgengespinst und Dämmergespinst voll ausnutzen.\""}
MultiLanguageSpellData['de'][454432] = {name = "Unerbittlicher Marsch", additional_info = "[q]Ihr könnt nicht auf weniger als 70% der normalen Bewegungsgeschwindigkeit verlangsamt werden, während Ihr eine Strähne von mindestens 2 Würfen der schicksalsgebundenen Münze mit demselben Ergebnis habt."}
MultiLanguageSpellData['de'][454433] = {name = "Ankunft des Todes", additional_info = "[q]Gesetzlosigkeit\n 'Greifhaken' kann innerhalb von 3 Sek. ohne Abklingzeit ein zweites Mal eingesetzt werden, doch die gesamte Abklingzeit wird um 5 Sek. erhöht.\n\nMeucheln\n 'Schattenschritt' kann innerhalb von 3 Sek. ohne Abklingzeit ein zweites Mal eingesetzt werden, doch die gesamte Abklingzeit wird um 5 Sek. erhöht."}
MultiLanguageSpellData['de'][454434] = {name = "Unausweichliches Ende", additional_info = "[q]Gesetzlosigkeit\n Die nächsten zwei Fähigkeiten profitieren jetzt von 'Kaltblütigkeit', allerdings nur 'Tötung'. 'Schicksalsgebundene Münzen', die von diesen Fähigkeiten geworfen werden, erzielen garantiert das gleiche Ergebnis, auf dem sie auch beim letzten Wurf gelandet sind.\n\nMeucheln\n Die nächsten zwei Fähigkeiten profitieren jetzt von 'Kaltblütigkeit', allerdings nur 'Vergiften'. 'Schicksalsgebundene Münzen', die von diesen Fähigkeiten geworfen werden, erzielen garantiert das gleiche Ergebnis, auf dem sie auch beim letzten Wurf gelandet sind."}
MultiLanguageSpellData['de'][454435] = {name = "Schicksalsbestimmt", additional_info = "[q]Gesetzlosigkeit\n 'Finsterer Stoß' hat eine 5% höhere Chance, ein zusätzliches Mal zuzuschlagen, und Eure schicksalsgebundenen Münzen haben bei einem Wurf eine 5% höhere Chance, dieselbe Seite zu zeigen wie beim letzten Wurf.\n\nMeucheln\n Waffengifte haben eine 5% höhere Chance, angewendet zu werden, und Eure schicksalsgebundenen Münzen haben bei einem Wurf eine 5% höhere Chance, dieselbe Seite zu zeigen wie beim letzten Wurf."}
MultiLanguageSpellData['de'][454436] = {name = "Trampeln", additional_info = "100 Meter Reichweite\nSofort\n[q]Stürmt auf einen zufälligen Gegner zu und fügt allen Spielercharakteren in seinem Weg 11025 Schattenschaden zu. Getroffene Ziele werden für 10 Sek. betäubt."}
MultiLanguageSpellData['de'][454437] = {name = "Azeritsprengladung", additional_info = "Sofort\n[q]Ziel von Azeritsprengladung!"}
MultiLanguageSpellData['de'][454438] = {name = "Azeritsprengladung", additional_info = "100 Meter Reichweite\nWirken in 3 sek.\n[q]Stürmt auf einen anvisierten Gegner zu und verursacht eine Explosion von Azeritenergie, die allen Gegnern innerhalb von 8 Metern um den Einschlag 4134 Arkanschaden und 5 Sek. lang alle 1 Sek. 1102 zusätzlichen Arkanschaden zufügt."}
MultiLanguageSpellData['de'][454439] = {name = "Azeritsprengladung", additional_info = "100 Meter Reichweite\nSofort\n[q]Stürmt auf einen anvisierten Gegner zu und verursacht eine Explosion von Azeritenergie, die allen Gegnern innerhalb von 8 Metern um den Einschlag 4134 Arkanschaden und 5 Sek. lang alle 1 Sek. 1102 zusätzlichen Arkanschaden zufügt."}
