MultiLanguageSpellData['de'][454747] = {name = "Alarmgeschütz 2000", additional_info = "[q]Für den folgenden Effekt in einen Tüfteleisockel einsetzen:\n\n Alarmgeschütz 2000\nPlatziert ein verborgenes Alarmgeschütz 2000 an einer Zielposition in der Nähe. Falls ein gegnerischer Spielercharakter dessen Entdeckungsradius betritt, macht es Euch auf diesen aufmerksam und versucht 30 Sek. lang, oder bis es zerstört wird, den Bereich zu verteidigen."}
MultiLanguageSpellData['de'][454748] = {name = "Ebenenvertauscher", additional_info = "[q]Für den folgenden Effekt in einen Tüfteleisockel einsetzen:\n\n Ebenenvertauscher\nGewährt dem Benutzer 14-18 Sek. lang Unsichtbarkeit."}
MultiLanguageSpellData['de'][454749] = {name = "Teilchenbeschleuniger 2000", additional_info = "[q]Für den folgenden Effekt in einen Tüfteleisockel einsetzen:\n\n Teilchenbeschleuniger 2000\nFixiert einen bis zu 12 bis 60 Meter entfernten Gegner als Ziel. Wenn Euer Weg nach 1.5 Sek. frei von Hindernissen bleibt, stürmt Ihr mit Schallgeschwindigkeit vorwärts. Wenn es zur Kollision kommt, werdet Ihr und das Ziel für 1.5 Sek. betäubt."}
MultiLanguageSpellData['de'][454750] = {name = "Schattenflammenraketen", additional_info = "[q]Für den folgenden Effekt in einen Tüfteleisockel einsetzen:\n\n Schattenflammenraketen\nSpringt auf ein Holzbrett, an das willkürlich Schattenflammenraketen genagelt wurde. Da kann gar nichts schiefgehen, aber wenn doch, würde das 526287 Schattenflammenschaden verursachen, die zwischen Euch und allen Gegnern aufgeteilt würden, die von der theoretischen Explosion getroffen werden."}
