MultiLanguageSpellData['de'][455395] = {name = "Monstrosität erwecken", additional_info = "{1 Rune / -10 Runenmacht} {40 Meter Reichweite}\nSofort 1.5 min Abklingzeit\n[q]Lässt für 30 Sek. eine Monstrosität auferstehen, die umherstreift und Gegner angreift. Sie belegt Ziele durch ihre Nahkampfangriffe mit 'Schwärende Wunde' und Ziele in ihrer Nähe mit 'Virulente Seuche'."}
MultiLanguageSpellData['de'][455396] = {name = "Faulende Infektionen", additional_info = "[q]Eure Krankheiten verursachen 10% mehr Schaden und haben eine 5% höhere Chance auf kritische Treffer."}
MultiLanguageSpellData['de'][455397] = {name = "Schwärende Sense", additional_info = "[q]Jeder 20. Einsatz von 'Schwärende Wunden' bewirkt, dass Euer nächster 'Schwärender Stoß' zu 'Schwärende Sense' wird.\n\nSchwärende Sense\nFegt durch alle Gegner innerhalb von 14 Metern vor Euch, fügt ihnen (200% der Angriffskraft) Schattenschaden zu und infiziert sie mit 2 bis 3 Stapeln von 'Schwärende Wunde'."}
MultiLanguageSpellData['de'][455398] = {name = "Verrottung", additional_info = "[q]'Virulente Seuche' hat eine Chance, plötzlich zu entbrennen und dem Ziel 50% des Schadens zuzufügen, den sie ihm in den letzten 4 Sek. verursacht hat.\n\n Bei Auslösung dieses Effekts wird die Dauer Eurer aktiven Diener um 1.0 Sek. verlängert, bis zu einem Maximum von 3.0 Sek."}
MultiLanguageSpellData['de'][455399] = {name = "Walzende Säure", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Rasha'nan stößt ein giftiges Gebräu auf markierte Ziele aus, das in Wellen vom Ziel aus in die angegebene Richtung schwappt.\n\n Spielercharaktere, die von der anfänglichen ätzenden Eruption bespritzt werden, erleiden ' Ätzende Benommenheit '.\n\n Jeder Spielercharakter, der eine Welle berührt, wird um 50% verlangsamt und wird alle 1 Sek. mit ' Korrosion ' belegt.\n\n Die Wellen verbrennen ' Klebrige Netze ', fügen Spielcharakteren im Umkreis von 5 Metern 1726895 Naturschaden zu und erzeugen ' Säurepfützen '."}
