MultiLanguageSpellData['de'][456587] = {name = "Königsköder", additional_info = "12 - 15 Meter Reichweite\nSofort\n[q]Wirft diesen Fisch zurück ins Wasser und gewährt einen Stapel von 'Königsköder', der die Gewässer um Euch herum vor verderbten Geisterfischen schützt und 30 Sek. lang die Wahrscheinlichkeit erhöht, einen Königinnenköderfisch zu fangen.\n\n Durch das Zurückwerfen mehrerer Fische kann diese Stärkung auf bis zu 10 Min. verlängert werden."}
MultiLanguageSpellData['de'][456588] = {name = "Insel von Dorn", additional_info = "Sofort\n[q]Empfohlene Fertigkeit: 1\n\n Ruhige Gewässer und vertraute Bedingungen machen dieses Gebiet perfekt für Angler, die ihre Fähigkeiten ausbauen wollen, bevor sie tiefer nach Khaz Algar vorstoßen.\n\n Angelmöglichkeiten in dieser Zone:\n - Glimmerbecken\n - Uferschatz\n - Sternguckerschwarm\n - Schwärender Fäulnisteich\n - Ruhige Oberflächenwellen\n - Flussbarschteich\n - Blutbarschschwarm\nBeruf:\nAngeln (1)"}
MultiLanguageSpellData['de'][456589] = {name = "Die Schallenden Tiefen", additional_info = "Sofort\n[q]Empfohlene Fertigkeit: 125\n\n Ein Höhlensystem, gekennzeichnet von der Verbindung zwischen Industrie und Anpassung. In den Flüssen wimmelt es von allerlei Leben von oben und unten.\n\n Angelmöglichkeiten in dieser Zone:\n - Glimmerbecken\n - Ruhige Oberflächenwellen\n - Flussbarschteich\n - Anglersucherstrom\n - Treibender tiefer Schatz\nBeruf:\nAngeln (75)"}
MultiLanguageSpellData['de'][456590] = {name = "Heilsturz", additional_info = "Sofort\n[q]Empfohlene Fertigkeit: 225\n\n Ein Gebiet, das erstaunlicherweise alle Arten von Leben ermöglicht. Tiefe Abgründe und kilometerweite unterirdische Flüsse bilden eine Kreuzung, an der Angler ihre Fähigkeiten auf die Probe stellen können.\n\n Angelmöglichkeiten in dieser Zone:\n - Ruhige Oberflächenwellen\n - Glimmerbecken\n - Anglersucherstrom\n - Treibender tiefer Schatz\n - Energieerfüllter Sekretfleck\n - Geflüster der Tiefe\n - Königliche Welle\n - Blut im Wasser\nBeruf:\nAngeln (150)"}
MultiLanguageSpellData['de'][456591] = {name = "Azj-Kahet", additional_info = "Sofort\n[q]Empfohlene Fertigkeit: 375\n\n Karge Gewässer, die mit dem Sekret diverser Seltsamkeiten geronnen sind. Sehr schwer zu durchqueren für ungenügend vorbereitete Angler.\n\n In dieser Zone:\n - Ruhige Oberflächenwellen\n - Glimmerbecken\n - Energieerfüllter Sekretfleck\n - Königliche Welle\n - Slumhaischwarm\n - Geflüster der Tiefe\nBeruf:\nAngeln (225)"}
