MultiLanguageSpellData['de'][456934] = {name = "Makroraketenmassaker", additional_info = "100 Meter Reichweite\nSofort\n[q]Entfesselt einen Beschuss aus Raketen, die alle Gegner innerhalb von 6 Metern um das Ziel mehrfach treffen und ihnen 4 Feuerschaden zufügen.\n\n Sehr wirksam bei unbeweglichen Zielen."}
MultiLanguageSpellData['de'][456935] = {name = "Makroraketenmassaker", additional_info = "100 Meter Reichweite\nSofort\n[q]Entfesselt einen Beschuss aus Raketen, die alle Gegner innerhalb von 6 Metern um das Ziel mehrfach treffen und ihnen 4 Feuerschaden zufügen.\n\n Sehr wirksam bei unbeweglichen Zielen."}
MultiLanguageSpellData['de'][456936] = {name = "Sengendes Licht", additional_info = "30 Meter Reichweite\nWirken in 1.5 sek.\n[q]Der Zaubernde bestrahlt das Ziel mit Licht, verursacht Heiligschaden und verbrennt das Ziel 8 Sek. lang alle 2 Sek. für zusätzlichen Heiligschaden."}
MultiLanguageSpellData['de'][456938] = {name = "Schattenblick", additional_info = "50 Meter Reichweite\nWirken in 2.5 sek.\n[q]Der Zaubernde feuert einen Strahl Schattenenergie auf sein Ziel, der auf bis zu 2 weitere Spielercharaktere überspringt und dem ersten Ziel 13 Schattenschaden zufügt. Fügt jedem folgenden Ziel weniger Schaden zu."}
MultiLanguageSpellData['de'][456939] = {name = "Brennende Verkümmerung", additional_info = "[q]Erhöht den Schaden von 'Schattenbrand' um 20%. Die kritische Trefferchance von 'Schattenbrand' ist um weitere 50% erhöht, wenn ein Ziel mit 30% oder weniger Gesundheit getroffen wird."}
MultiLanguageSpellData['de'][456940] = {name = "Heilige Woge", additional_info = "30 Meter Reichweite\nWirken in 4 sek.\n[q]Der Zaubernde entfesselt eine Welle der Zerstörung, fügt allen getroffenen Spielercharakteren Heiligschaden zu und desorientiert sie 2 Sek. lang."}
MultiLanguageSpellData['de'][456942] = {name = "Bebendes Schmettern", additional_info = "300 Meter Reichweite\nWirken in 2 sek.\n[q]Der Zaubernde schlägt auf den Boden und bringt ihn zum Beben, fügt allen Spielercharakteren körperlichen Schaden zu und verringert deren Bewegungsgeschwindigkeit 10 Sek. lang um 30%."}
MultiLanguageSpellData['de'][456943] = {name = "Abscheuliche Grausamkeit", additional_info = "[q]Wenn 'Schattenbrand' ein Ziel mit 30% oder weniger Gesundheit nicht tötet, wird seine Abklingzeit um 5 Sek. verringert."}
