MultiLanguageSpellData['de'][456948] = {name = "Läuterungsprotokoll", additional_info = "Kanalisiert (Wirken in 8 sek.)\n[q]Der Zaubernde ruft eine Salve geschmolzener Meteore hinab, die Spielercharakteren innerhalb von 8 Metern jeweils 6 Feuerschaden zufügen."}
MultiLanguageSpellData['de'][456951] = {name = "Verbesserter Chaosblitz", additional_info = "[q]Erhöht den Schaden von 'Chaosblitz' um 10% und verringert dessen Zauberzeit um 0.5 Sek."}
MultiLanguageSpellData['de'][456952] = {name = "Läuterungsprotokoll", additional_info = "300 Meter Reichweite\nSofort\n[q]Der Zaubernde ruft eine Salve geschmolzener Meteore hinab, die Spielercharakteren innerhalb von 8 Metern jeweils 6 Feuerschaden zufügen."}
MultiLanguageSpellData['de'][456954] = {name = "Geschenk des Sonnenkönigs", additional_info = "Sofort\n[q]Heilt das Ziel alle 1 Sek. um 1% seiner maximalen Gesundheit."}
MultiLanguageSpellData['de'][456956] = {name = "Läuterungsprotokoll", additional_info = "300 Meter Reichweite\nSofort\n[q]Der Zaubernde ruft eine Salve geschmolzener Meteore hinab, die Spielercharakteren innerhalb von 8 Metern jeweils 6 Feuerschaden zufügen."}
MultiLanguageSpellData['de'][456957] = {name = "Hinzufügen", additional_info = "Wirken in 1.5 sek.\nReagenzien:\nPfeilspitzengötze aus Porzellan\n[q]Branns Zauber und Fähigkeiten haben eine Chance, Gegner zu schwächen, was die Chance auf kritische Treffer gegen diese Gegner 5 Sek. lang um 30 % erhöht.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung."}
MultiLanguageSpellData['de'][456958] = {name = "Hinzufügen", additional_info = "Wirken in 1.5 sek.\nReagenzien:\nGötze der brutalen Kraft\n[q]Springt auf Brann, wenn er dazu auffordert, damit er Spielercharaktere auf ihre Gegner schleudert, was diese zurückstößt und ihnen erheblichen körperlichen Schaden zufügt, der unter ihnen aufgeteilt wird. Dieser Effekt hat eine Chance, bis zu 2 -mal hintereinander aufzutreten.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung."}
MultiLanguageSpellData['de'][456959] = {name = "Hinzufügen", additional_info = "Wirken in 1.5 sek.\nReagenzien:\nGötze der Erdenmutter\n[q]Branns Zauber und Fähigkeiten haben eine Chance, den Götzen zu erwecken, was einem verletzten Spielercharakter einen Schild in Höhe von 30 % seiner fehlenden Gesundheit gewährt.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung."}
MultiLanguageSpellData['de'][456960] = {name = "Hinzufügen", additional_info = "Wirken in 1.5 sek.\nReagenzien:\nUnverwüstlicher Eisengötze\n[q]Wenn die Gesundheit eines Spielercharakters im Kampf unter 40 % fällt, erwacht der Götze, fügt Gegnern in der Nähe moderaten körperlichen Schaden zu und verspottet sie für 6 Sek. Kann nur alle 2 Min. auftreten.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung."}
MultiLanguageSpellData['de'][456961] = {name = "Zünftig satt werden", additional_info = "Sofort\n[q]Erhöht Werte und gewährt zusätzliche Effekte basierend auf den Nahrungsmitteln aus Khaz Algar, die verspeist wurden."}
MultiLanguageSpellData['de'][456962] = {name = "Hinzufügen", additional_info = "Wirken in 1.5 sek.\nReagenzien:\nLichtberührter Götze\n[q]Sobald ein Spielercharakter eine Defensivfähigkeit mit einer Abklingzeit von 30 Sek. oder länger benutzt, wird der Götze aktiviert und heilt ihn 10 Sek. lang alle 1 Sek. um ( 200 / 100)% seiner maximalen Gesundheit.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung."}
MultiLanguageSpellData['de'][456963] = {name = "Hinzufügen", additional_info = "Wirken in 1.5 sek.\nReagenzien:\nGötze des finalen Willens\n[q]Im Kampf bestimmt Brann einen Spielercharakter, der seinen Schuss 4 Sek. lang lenkt, bevor er ihn auf die Position abfeuert und dem ersten getroffenen Gegner erheblichen körperlichen Schaden zufügt.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung."}
MultiLanguageSpellData['de'][456965] = {name = "Hinzufügen", additional_info = "Wirken in 1.5 sek.\nReagenzien:\nAmorphes Relikt\n[q]Beim Kampfbeginn erhalten Spielercharaktere entweder Massiv oder Miniatur bis zum Ende des Kampfes.\n\nMassiv\nErhöht Eure Größe um 20%, Eure maximale Gesundheit um 10% und Euren verursachten Schaden und hervorgerufene Heilung um 6%.\n\n Miniatur\nVerringert Eure Größe um 20% und erhöht Eure Bewegungsgeschwindigkeit um 10% und Euer Tempo um 6%.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung."}
MultiLanguageSpellData['de'][456966] = {name = "Hinzufügen", additional_info = "Wirken in 1.5 sek.\nReagenzien:\nZeitverlorenes Relikt\n[q]Branns Zauber und Fähigkeiten haben eine Chance, Energieausbrüche zu erzeugen und so den Zeitstrom für alle Einheiten in der Nähe 12 Sek. lang um 20 % zu verzerren.\n\n Die Zeitverzerrung hat einen Einfluss auf Zauber-, Bewegungs- und regelmäßige Effekte, Abklingzeiten und Angriffstempo.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung."}
MultiLanguageSpellData['de'][456967] = {name = "Hinzufügen", additional_info = "Wirken in 1.5 sek.\nReagenzien:\nRelikt der Sucher aus alten Zeiten\n[q]Wenn Brann ' Sammelwerkzeuge ' einsetzt, besteht eine Chance von 35 %, ein mächtiges Artefakt freizulegen, das Eurer Gruppe einen mächtigen Segen gewährt.\n\n Sammelwerkzeuge\nBrann setzt seine Sammelwerkzeuge ein, um Spielercharakteren zu helfen, zusätzliches Gold, Erz, Leder, zusätzliche Kräuter, Fische und Schätze zu finden.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung."}
MultiLanguageSpellData['de'][456968] = {name = "Erfrischung", additional_info = "Sofort\n[q]Stellt im Verlauf von 20 Sek. ( 1350000 / 5 * 20) Gesundheit und ( 675000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben.\n\n Satt\n Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr ' Satt ' und erhaltet 1 Stunde lang ( 470 * .7) kritischen Trefferwert."}
MultiLanguageSpellData['de'][456969] = {name = "Hinzufügen", additional_info = "Wirken in 1.5 sek.\nReagenzien:\nLebloses Relikt der Nekrotischen Fäulnis\n[q]Der Götze benutzt unheilige Energie, um tödlichen Schaden bei Spielercharakteren zu verhindern und heilt sie stattdessen um einen Betrag, der 100 % ihrer maximalen Gesundheit entspricht, und verwandelt sie in Untote.\n\n Solange sie untot sind, können sie nicht geheilt werden, verlieren alle 1 Sek. 11 % ihrer maximalen Gesundheit, und ihr Schaden und ihre Heilung ist um 8 % erhöht.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung."}
MultiLanguageSpellData['de'][456970] = {name = "Hinzufügen", additional_info = "Wirken in 1.5 sek.\nReagenzien:\nRelikt der Empfindungsfähigkeit\n[q]Wenn eine Stahlfalle aktiviert wird, besteht eine Chance, dass Brann eine zusätzliche Falle auslegt.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung."}
MultiLanguageSpellData['de'][456971] = {name = "Hinzufügen", additional_info = "Wirken in 1.5 sek.\nReagenzien:\nReliktblut von Zekvir\n[q]An zufälligen Zeitpunkten während des Kampfes wird eine Blutbestie erscheinen, die sich an Brann festsetzt und in der Nähe von Spielercharakteren regelmäßig Stücke von sich selbst schleudert. Spielercharaktere, die über diese Stücke laufen, erhalten ' Blutbefleckter Segen '.\n\n Blutbefleckter Segen\nVerursachter Schaden und hervorgerufene Heilung um 2% und maximale Gesundheit um 5% verringert. Hält 1 Min. lang an.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung."}
MultiLanguageSpellData['de'][456972] = {name = "Hinzufügen", additional_info = "Wirken in 1.5 sek.\nReagenzien:\nOptimiertes Relikt\n[q]Außerhalb eines Kampfes steigt die Bewegungsgeschwindigkeit der Gruppenmitglieder um 20 %. Bei Kampfeintritt steigt das Tempo der Gruppenmitglieder 8 Sek. lang um 10 %.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung."}
MultiLanguageSpellData['de'][456973] = {name = "Stachelausbruch", additional_info = "50 Meter Reichweite\nWirken in 3 sek.\n[q]Der Zaubernde taucht ab, bevor er hervorbricht und Stacheln mit sich zieht, die Spielercharakteren, die von ihnen getroffen werden, 25 körperlichen Schaden zufügen."}
