MultiLanguageSpellData['de'][456997] = {name = "Hinzufügen", additional_info = "Wirken in 1.5 sek.\nReagenzien:\nGötze der Erdenmutter\n[q]Branns Zauber und Fähigkeiten haben eine Chance, den Götzen zu erwecken, was einem verletzten Spielercharakter einen Schild in Höhe von 70 % seiner fehlenden Gesundheit gewährt.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung."}
MultiLanguageSpellData['de'][456998] = {name = "Hinzufügen", additional_info = "Wirken in 1.5 sek.\nReagenzien:\nUnverwüstlicher Eisengötze\n[q]Wenn die Gesundheit eines Spielercharakters im Kampf unter 40 % fällt, erwacht der Götze, fügt Gegnern in der Nähe moderaten körperlichen Schaden zu und verspottet sie für 10 Sek. Kann nur alle 2 Min. auftreten.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung."}
MultiLanguageSpellData['de'][456999] = {name = "Hinzufügen", additional_info = "Wirken in 1.5 sek.\nReagenzien:\nLichtberührter Götze\n[q]Sobald ein Spielercharakter eine Defensivfähigkeit mit einer Abklingzeit von 30 Sek. oder länger benutzt, wird der Götze aktiviert und heilt ihn 10 Sek. lang alle 1 Sek. um ( 400 / 100)% seiner maximalen Gesundheit.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung."}
MultiLanguageSpellData['de'][457001] = {name = "Hinzufügen", additional_info = "Wirken in 1.5 sek.\nReagenzien:\nGötze des finalen Willens\n[q]Im Kampf bestimmt Brann einen Spielercharakter, der seinen Schuss 4 Sek. lang lenkt, bevor er ihn auf die Position abfeuert und den ersten beiden getroffenen Gegnern massiven körperlichen Schaden zufügt.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung."}
MultiLanguageSpellData['de'][457002] = {name = "Hinzufügen", additional_info = "Wirken in 1.5 sek.\nReagenzien:\nAmorphes Relikt\n[q]Beim Kampfbeginn erhalten Spielercharaktere entweder Massiv oder Miniatur bis zum Ende des Kampfes.\n\n\nMassiv\nErhöht Eure Größe um 20 %, Eure maximale Gesundheit um 20 % und Euren verursachten Schaden und hervorgerufene Heilung um 12 %.\n\nMiniatur\nVerringert Eure Größe um 20 % und erhöht Eure Bewegungsgeschwindigkeit um 20 % und Euer Tempo um 12 %.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung."}
MultiLanguageSpellData['de'][457003] = {name = "Hinzufügen", additional_info = "Wirken in 1.5 sek.\nReagenzien:\nZeitverlorenes Relikt\n[q]Branns Zauber und Fähigkeiten haben eine Chance, Energieausbrüche zu erzeugen und so den Zeitstrom für alle Einheiten in der Nähe 12 Sek. lang um 30 % zu verzerren.\n\n Die Zeitverzerrung hat einen Einfluss auf Zauber-, Bewegungs- und regelmäßige Effekte, Abklingzeiten und Angriffstempo.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung."}
MultiLanguageSpellData['de'][457004] = {name = "Hinzufügen", additional_info = "Wirken in 1.5 sek.\nReagenzien:\nRelikt der Sucher aus alten Zeiten\n[q]Wenn Brann ' Sammelwerkzeuge ' einsetzt, besteht eine Chance von 50 %, bis zu 2 mächtige Artefakte freizulegen, die Eurer Gruppe einen mächtigen Segen gewähren.\n\n Sammelwerkzeuge\nBrann setzt seine Sammelwerkzeuge ein, um Spielercharakteren zu helfen, zusätzliches Gold, Erz, Leder, zusätzliche Kräuter, Fische und Schätze zu finden.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung."}
MultiLanguageSpellData['de'][457005] = {name = "Hinzufügen", additional_info = "Wirken in 1.5 sek.\nReagenzien:\nLebloses Relikt der Nekrotischen Fäulnis\n[q]Der Götze benutzt unheilige Energie, um tödlichen Schaden bei Spielercharakteren zu verhindern und heilt sie stattdessen um einen Betrag, der 100 % ihrer maximalen Gesundheit entspricht, und verwandelt sie in Untote.\n\n Solange sie untot sind, können sie nicht geheilt werden, verlieren alle 1 Sek. 3 % ihrer maximalen Gesundheit, und ihr Schaden und ihre Heilung ist um 12 % erhöht.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung."}
MultiLanguageSpellData['de'][457006] = {name = "Hinzufügen", additional_info = "Wirken in 1.5 sek.\nReagenzien:\nRelikt der Empfindungsfähigkeit\n[q]Wenn eine Stahlfalle aktiviert wird, besteht eine Chance, dass Brann eine zusätzliche Falle auslegt.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung."}
MultiLanguageSpellData['de'][457007] = {name = "Hinzufügen", additional_info = "Wirken in 1.5 sek.\nReagenzien:\nReliktblut von Zekvir\n[q]An zufälligen Zeitpunkten während des Kampfes wird eine Blutbestie erscheinen, die sich an Brann festsetzt und in der Nähe von Spielercharakteren regelmäßig Stücke von sich selbst schleudert. Spielercharaktere, die über diese Stücke laufen, erhalten ' Blutbefleckter Segen '.\n\n Blutbefleckter Segen\nVerursachter Schaden und hervorgerufene Heilung um 2% und maximale Gesundheit um 3% verringert. Hält 1 Min. lang an.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung."}
MultiLanguageSpellData['de'][457008] = {name = "Hinzufügen", additional_info = "Wirken in 1.5 sek.\nReagenzien:\nOptimiertes Relikt\n[q]Außerhalb eines Kampfes steigt die Bewegungsgeschwindigkeit der Gruppenmitglieder um 40 %. Bei Kampfeintritt wird das Tempo der Gruppenmitglieder für 8 Sek. um 20 % erhöht.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung."}
