MultiLanguageSpellData['de'][457052] = {name = "Mal des Todespirschers", additional_info = "[q]Meucheln\n Belegt Euer Ziel mit 3 Stapeln von 'Mal des Todespirschers', wenn Ihr 'Hinterhalt' aus der Verstohlenheit einsetzt. Wenn Ihr 5 oder mehr Combopunkte für Angriffe gegen ein markiertes Ziel einsetzt, verbraucht Ihr ein 'Mal des Todespirschers' auf dem Ziel, was (120% der Angriffskraft) Seuchenschaden verursacht und den Schaden Eures nächsten Einsatzes von 'Hinterhalt' oder 'Verstümmeln' um 50% erhöht.\n Es kann immer nur ein Gegner zur gleichen Zeit mit einem Mal belegt sein.\n\nTäuschung\n Belegt Euer Ziel mit 3 Stapeln von 'Mal des Todespirschers', wenn Ihr 'Schattenschlag' aus der Verstohlenheit oder 'Schattentanz' einsetzt. Wenn Ihr 5 oder mehr Combopunkte für Angriffe gegen ein markiertes Ziel einsetzt, verbraucht Ihr ein 'Mal des Todespirschers' auf dem Ziel, was (120% der Angriffskraft) Seuchenschaden verursacht und den Schaden Eures nächsten Einsatzes von um 50% erhöht.\n Es kann immer nur ein Gegner zur gleichen Zeit mit einem Mal belegt sein."}
MultiLanguageSpellData['de'][457053] = {name = "Beseitigt die Zeugen", additional_info = "[q]Meucheln\n Nachdem Ihr ein Ziel mit 'Mal des Todespirschers' belegt, verursacht Euer nächster Einsatz von 'Dolchfächer' zusätzlich (100% der Angriffskraft) Seuchenschaden und erzeugt 1 zusätzlichen Combopunkt.\n\nTäuschung\n Nachdem Ihr ein Ziel mit 'Mal des Todespirschers' belegt, verursacht Euer nächster Einsatz von 'Shurikensturm' zusätzlich (100% der Angriffskraft) Seuchenschaden und erzeugt 1 zusätzlichen Combopunkt."}
MultiLanguageSpellData['de'][457054] = {name = "Zur Strecke bringen", additional_info = "[q]Automatische Angriffe gegen markierte Ziele verursachen zusätzlich (25% der Angriffskraft) Seuchenschaden."}
MultiLanguageSpellData['de'][457055] = {name = "Einzelner Fokus", additional_info = "[q]Schaden, der anderen Zielen als dem von Euch markierten Ziel zugefügt wird, fügt dem von Euch markierten Ziel 5% Seuchenschaden zu."}
MultiLanguageSpellData['de'][457056] = {name = "Lauernde Dunkelheit", additional_info = "[q]Meucheln\n Erhöht 30 Sek. lang den von Euch verursachten Naturschaden um 30%, nachdem 'Todesmal' ausläuft.\n\nTäuschung\n Erhöht 30 Sek. lang den von Euch verursachten Schattenschaden um 30%, nachdem 'Schattenklingen' ausläuft."}
MultiLanguageSpellData['de'][457057] = {name = "Schattenwandler", additional_info = "[q]Immer, wenn Ihr einen Stapel von 'Mal des Todespirschers' aufbraucht, wird die Abklingzeit von 'Schattenschritt' um 3 Sek. verringert."}
MultiLanguageSpellData['de'][457058] = {name = "Dunkelste Nacht", additional_info = "[q]Täuschung\n Wenn Ihr den letzten Stapel von 'Mal des Todespirschers' auf Eurem Ziel verbraucht oder Euer Ziel stirbt, erhaltet Ihr 40 Energie und Euer nächster Einsatz von 'Ausweiden' mit maximalen Combopunkten trifft garantiert kritisch, verursacht 60% zusätzlichen Schaden und belegt das Ziel mit 3 Stapeln von 'Mal des Todespirschers'.\n\nMeucheln\n Wenn Ihr den letzten Stapel von 'Mal des Todespirschers' auf Eurem Ziel verbraucht oder Euer Ziel stirbt, erhaltet Ihr 40 Energie und Euer nächster Einsatz von 'Vergiften' mit maximalen Combopunkten trifft garantiert kritisch, verursacht 60% zusätzlichen Schaden und belegt das Ziel mit 3 Stapeln von 'Mal des Todespirschers'."}
