MultiLanguageSpellData['de'][457062] = {name = "Symbolischer Sieg", additional_info = "[q]Täuschung\n 'Symbole des Todes' erhöht zusätzlich den Schaden Eures nächsten Einsatzes von 'Ausweiden' oder 'Schwarzpulver' um 18%.\n\nMeucheln\n 'Tückische Klinge' erhöht zusätzlich den Schaden Eures nächsten Einsatzes von 'Vergiften' um 18%."}
