MultiLanguageSpellData['de'][460156] = {name = "Schnellstart", additional_info = "Wirken in 1.5 sek.\n[q]Sobald alle Mechadrohnen der Düsternisverschmolzenen besiegt wurden, versucht die Große M.A.M.A., ihre erschöpfte Batterie mit externer Energie zu versorgen. Durch diesen Prozess erleidet sie 200% mehr Schaden und entfesselt 12 Sek. lang alle 1.5 Sek. Energieladungen. Jede Energieladung fügt allen Spielercharakteren 1745604 Naturschaden zu.\n\n Wenn die Batterie wieder voll aufgeladen ist, verursacht Große M.A.M.A. eine ' Exzessive Elektrifizierung '."}
MultiLanguageSpellData['de'][460158] = {name = "Schnellstart", additional_info = "Sofort\n[q]Sobald alle Mechadrohnen der Düsternisverschmolzenen besiegt wurden, versucht die Große M.A.M.A., ihre erschöpfte Batterie mit externer Energie zu versorgen. Durch diesen Prozess erleidet sie 200% mehr Schaden und entfesselt 12 Sek. lang alle 1.5 Sek. Energieladungen. Jede Energieladung fügt allen Spielercharakteren 1745604 Naturschaden zu.\n\n Wenn die Batterie wieder voll aufgeladen ist, verursacht Große M.A.M.A. eine ' Exzessive Elektrifizierung '."}
