MultiLanguageSpellData['de'][460436] = {name = "Springflut", additional_info = "40 Meter Reichweite\n{Sofort} {5 sek. Abklingzeit}\n[q]Heilende Wasser fließen über ein verbündetes Ziel hinweg, heilen es um 183476 Gesundheit sowie zusätzlich im Verlauf von 18 Sek. um 0 Gesundheit."}
MultiLanguageSpellData['de'][460438] = {name = "Heilende Woge", additional_info = "40 Meter Reichweite\nWirken in 1.5 sek.\n[q]Eine schnelle Woge heilender Energie, die 338724 Gesundheit eines verbündeten Ziels wiederherstellt."}
MultiLanguageSpellData['de'][460439] = {name = "Kettenheilung", additional_info = "{3% von Grundmana} {40 Meter Reichweite}\nWirken in 2.4 sek.\n[q]Heilt das verbündete Ziel um 191778 Gesundheit und springt dann bis zu 15 Meter auf die 3 am schwersten verletzten Verbündeten in der Nähe über, um sie zu heilen. Mit jedem Sprung verringert sich die Heilung um 30%."}
MultiLanguageSpellData['de'][460443] = {name = "Blitzschlag", additional_info = "40 Meter Reichweite\nWirken in 1.4 sek.\n[q]Schleudert einen Blitzschlag auf das Ziel, der 276387 Naturschaden verursacht.\n\nErzeugt 8 Mahlstrom."}
MultiLanguageSpellData['de'][460444] = {name = "Glücksroller!", additional_info = "Sofort\n[q]Spielercharaktere werden zu Glücksrollern, was 15 Sek. lang ihren verursachten Schaden und ihre hervorgerufene Heilung um 10% und ihre Bewegungsgeschwindigkeit um 30% erhöht."}
MultiLanguageSpellData['de'][460448] = {name = "Unheilige Verseuchung", additional_info = "[q]'Dunkle Transformation' umgibt Euren Ghul für 6 Sek. mit einem üblen Schwarm aus Insekten, die alle Gegner in der Nähe stechen und sie mit der Virulenten Seuche sowie einer unheiligen Krankheit infizieren, die im Verlauf von 14 Sek. (27.832% der Angriffskraft) Schaden verursacht. Bis zu 4-mal stapelbar."}
