MultiLanguageSpellData['de'][460468] = {name = "Hand der Provokation", additional_info = "40 Meter Reichweite\n{Sofort} {1.5 sek. Abklingzeit}\n[q]Verspottet das Ziel, damit es Euch angreift, hat aber keinerlei Effekt, wenn das Ziel Euch bereits angreift."}
MultiLanguageSpellData['de'][460469] = {name = "Energiegeladene Sturmkrähenfeder", additional_info = "15 Meter Reichweite\nSofort 1.5 min Abklingzeit\n[q]Hält die Feder für [1.0][1] Sek. hoch, um mit der Macht des Sturms zuzuschlagen, der auf den Zielort niedergeht und ( 1 * 3166 ) Naturschaden verursacht, die auf Gegner in der Nähe aufgeteilt werden."}
MultiLanguageSpellData['de'][460472] = {name = "Der Volltreffer", additional_info = "100 Meter Reichweite\n{Wirken in} {2.5 sek. 3 sek. Abklingzeit}\n[q]Der einarmige Bandit schmettert mit seinem großen Arm auf den Boden, fügt seinem Ziel so 50310521 körperlichen Schaden zu und lässt es 30 Sek. lang 750% mehr Schaden durch ' Der Volltreffer ' erleiden. Dieser Effekt ist stapelbar.\n\n Zusätzlich hinterlässt ' Der Volltreffer ' ein ' Schockfeld '."}
MultiLanguageSpellData['de'][460474] = {name = "Schockfeld", additional_info = "100 Meter Reichweite\nSofort\n[q]Spielercharaktere, die im elektrischen Feld stehen, erleiden 150% mehr Schaden und alle 1 Sek. 838509 Naturschaden."}
MultiLanguageSpellData['de'][460475] = {name = "Pyroschlag", additional_info = "40 Meter Reichweite\nSofort\n[q]Schleudert einen immensen feurigen Felsen, der (150% der Zaubermacht) Feuerschaden verursacht."}
MultiLanguageSpellData['de'][460476] = {name = "Flammenstoß", additional_info = "40 Meter Reichweite\nWirken in 3.5 sek.\n[q]Lässt eine Feuersäule niedergehen, die alle Gegner im Bereich verbrennt und ihnen so (60% der Zaubermacht) Feuerschaden zufügt. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu."}
MultiLanguageSpellData['de'][460478] = {name = "Windlaufen", additional_info = "[q]Teilt Euch für 15 Sek. in 3 Elementargeister auf, die jeweils 40% des normalen Schadens und der Heilung verursachen.\n\n Ihr kontrolliert den Sturmgeist direkt, während der Erd- und der Feuergeist Eure Angriffe bei Gegnern in der Nähe imitieren.\n\n Während die Geister aktiv sind, führt der erneute Einsatz von 'Sturm, Erde und Feuer' dazu, dass die Geister sich auf Euer Ziel fixieren."}
MultiLanguageSpellData['de'][460482] = {name = "Überragender Wildtierköder", additional_info = "2 Meter ReichweiteWirken in 2 sek. 1 min Abklingzeit\n[q]Platziert den Köder und lockt eine hochkarätige scheue Kreatur aus ihrem Versteck.\n\n Kann nur in der Grollenden Einöde in den Schallenden Tiefen eingesetzt werden."}
