MultiLanguageSpellData['de'][461248] = {name = "Hochspannung", additional_info = "[q]Wenn 'Arkane Geschosse' Schaden verursacht, besteht eine Chance von 10%, Euch 1 Arkane Aufladung zu gewähren.\n\n Die Chance wird jedes Mal, wenn Ihr durch 'Arkane Geschosse' keine Arkane Aufladung erhaltet, um 15% erhöht."}
MultiLanguageSpellData['de'][461250] = {name = "Licht der aufgehenden Sonne", additional_info = "[q][ Kreuzzug der Vergeltung : Nachdem Ihr 'Kreuzzug der Vergeltung' eingesetzt habt, wird Euer nächster Einsatz von 'Heiliger Schock' 2 weitere Male eingesetzt / Nachdem Ihr 'Zornige Vergeltung' eingesetzt habt, werden Eure nächsten 2 Einsätze von 'Heiliger Schock' 2 weitere Male eingesetzt.]\n Nachdem Ihr 'Göttlicher Glockenschlag' eingesetzt habt, werden Eure nächsten 2 Einsätze von 'Heiliger Schock' 2 weitere Male eingesetzt."}
