MultiLanguageSpellData['de'][461388] = {name = "Im Netz gefangen", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Ein dickes Netz schnürt das Opfer ein und verringert sein Tempo um 50% sowie seine Bewegungsgeschwindigkeit um 20% und fügt ihm alle 1 Sek. 575632 Naturschaden zu. Hält 10 Sek. lang an."}
MultiLanguageSpellData['de'][461389] = {name = "Belohnung: Flamme und Münze", additional_info = "Kanalisiert (Wirken in 8 sek.)\n[q]Das Einwerfen einer Flammenmarke und einer Münzmarke führt dazu, dass der einarmige Bandit 8 Sek. lang alle 0.5 Sek. glühend heiße Münzen auf alle Spielercharaktere verschießt. Diese Münzen verursachen 6 Sek. lang alle 0.5 Sek. 251553 Feuerschaden. Dieser Effekt ist stapelbar."}
MultiLanguageSpellData['de'][461390] = {name = "Flamme und Münze", additional_info = "Sofort\n[q]Das Einwerfen einer Flammenmarke und einer Münzmarke führt dazu, dass der einarmige Bandit 8 Sek. lang alle 0.5 Sek. glühend heiße Münzen auf alle Spielercharaktere verschießt. Diese Münzen verursachen 6 Sek. lang alle 0.5 Sek. 251553 Feuerschaden. Dieser Effekt ist stapelbar."}
