MultiLanguageSpellData['de'][461395] = {name = "Belohnung: Münze und Bombe", additional_info = "Sofort\n[q]Das Einwerfen einer Münzmarke und einer Bombenmarke führt dazu, dass mehrere vergoldete Premiumdynamitbeuten herbeigerufen werden. Die Premiumwährung erhöht die Gesundheit um 75% und den verursachten Schaden um 50% und gewährt Immunität gegen Kontrollverlust- und Unterbrechungseffekte."}
MultiLanguageSpellData['de'][461401] = {name = "Kollabierende Nova", additional_info = "300 Meter Reichweite\nSofort\n[q]Wenn ein kosmisches Simulakrum sich innerhalb von 8 Metern um ein anderes Simulakrum befindet, reagieren sie aufeinander und verbrennen, was allen Spielercharakteren 1439079 Schattenschaden zufügt."}
MultiLanguageSpellData['de'][461404] = {name = "Chistoß", additional_info = "40 Meter Reichweite\n{Wirken in} {1 sek. 0.1 sek. Abklingzeit}\n[q]Schleudert einen Schwall Chienergie bis zu 40 Meter vorwärts, wobei er allen Gegnern in seinem Weg (280% der Angriffskraft) Naturschaden zufügt und den Mönch sowie alle Verbündeten im Effektbereich um (220% der Angriffskraft) Gesundheit heilt. Schaden und Heilung bei Zielen über 5 Ziele hinaus verringert.\n [ Braumeister : Beim Einsatz von 'Chistoß' sind Vermeidungsmechaniken weiterhin aktiv ]"}
MultiLanguageSpellData['de'][461408] = {name = "Verschlingen", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Ansurek verschlingt die Essenz ihres Opfers und fügt ihm 115126303 Schattenschaden zu."}
MultiLanguageSpellData['de'][461409] = {name = "Fass!", additional_info = "Sofort\n[q]Die Chance, dass 'Tötungsbefehl' 'Todesstoß' auslöst, ist um 5% erhöht, und 'Todesstoß\" sorgt jetzt dafür, dass 'Tödlicher Schuss' bis zu 2 zusätzliche Ziele trifft.\n\n Eure Chance, 'Todesstoß' zu erhalten, ist während 'Koordinierter Angriff' doppelt so hoch.\n\n Todesstoß\n Die Abklingzeit von 'Tödlicher Schuss' wird zurückgesetzt. Euer nächster Einsatz von 'Tödlicher Schuss' kann gegen jedes Ziel unabhängig von seiner aktuellen Gesundheit eingesetzt werden."}
