MultiLanguageSpellData['de'][462527] = {name = "Citrin des Meeresbodenleviathans", additional_info = "[q]Gewährt 6 [( 229 / 10779) * 4.35 * 1887.67] / 8211.35 Ausdauer und erhöht Eure Größe leicht. Zusätzlich erleiden Angreifer ( 36 * 0.82) Frostschaden, wenn Ihr über mehr als 80% Gesundheit verfügt."}
